INSERT INTO `wp_options` VALUES (78,'widget_text','a:5:{i:1;a:0:{}i:2;a:3:{s:5:\"title\";s:0:\"\";s:4:\"text\";s:1156:\"<p><a href=\"http://theme-fusion.com/avada/construction/\"><img src=\"http://warmvast.local/wp-content/uploads/2017/02/footer-logo.png\" alt=\"\" /></a></p>\r\n\r\n[fusion_separator style_type=\"none\" top_margin=\"10\" bottom_margin=\"0\" sep_color=\"\" border_size=\"\" icon=\"\" icon_circle=\"\" icon_circle_color=\"\" width=\"\" alignment=\"left\" class=\"\" id=\"\"]\r\n\r\n<p>We are specialists in the construction of unique and exclusive properties. Our work inspires. We pride ourselves on delivering outstanding quality and design for leading clients across the world. </p>\r\n\r\n[fusion_separator style_type=\"none\" top_margin=\"20\" bottom_margin=\"0\" sep_color=\"\" border_size=\"\" icon=\"\" icon_circle=\"\" icon_circle_color=\"\" width=\"\" alignment=\"left\" class=\"\" id=\"\"]\r\n\r\n\r\n[fusion_button link=\"http://warmvast.local/about/\" color=\"custom\" size=\"large\" type=\"\" shape=\"\" target=\"_self\" title=\"\" gradient_colors=\"\" gradient_hover_colors=\"#333\" accent_color=\"\" accent_hover_color=\"#fff\" bevel_color=\"\" border_width=\"\" shadow=\"\" icon=\"\" icon_divider=\"yes\" icon_position=\"left\" modal=\"\" animation_type=\"0\" animation_direction=\"down\" animation_speed=\"0.1\" class=\"\" id=\"\"]Learn More[/fusion_button]\r\n\";s:6:\"filter\";b:0;}i:3;a:15:{s:5:\"title\";s:16:\"CONTACT US TODAY\";s:4:\"text\";s:833:\"[fusion_checklist icon=\"fa-check fas\" iconcolor=\"#717171\" circle=\"\" circlecolor=\"\" size=\"14px\" class=\"\" id=\"\"][fusion_li_item icon=\"fa-globe fas\"]\r\n<p>Corporate Location<br />\r\n1600 Amphitheatre Parkway<br />\r\nLondon WC1 1BA</p>\r\n[/fusion_li_item]\r\n[fusion_li_item icon=\"fa-home fas\"]\r\n<p>Residential Location<br />\r\n9521 Broadsberry Avenue<br />\r\nPaddington RC7 9ZA</p>\r\n[/fusion_li_item]\r\n[fusion_li_item icon=\"fa-phone fas\"]1.800.458.556 / 1.800.532.2112[/fusion_li_item]\r\n[fusion_li_item icon=\"fa-envelope far\"]<a style=\"padding: 0;border-bottom: none\" href=\"mailto:info@your-domain.com\">info@your-domain.com</a>[/fusion_li_item][fusion_li_item icon=\"fa-clock far\"]Monday - Friday: 9:00 AM - 6:00 PM[/fusion_li_item]\r\n[fusion_li_item icon=\"fa-clock far\"]Saturday - Sunday: 9:00 AM - 12:00 PM[/fusion_li_item]\r\n[/fusion_checklist]\";s:6:\"filter\";b:0;s:6:\"visual\";b:0;s:20:\"fusion_display_title\";s:3:\"yes\";s:20:\"fusion_padding_color\";s:0:\"\";s:13:\"fusion_margin\";s:0:\"\";s:15:\"fusion_bg_color\";s:0:\"\";s:21:\"fusion_bg_radius_size\";s:0:\"\";s:18:\"fusion_border_size\";s:0:\"\";s:19:\"fusion_border_style\";s:5:\"solid\";s:19:\"fusion_border_color\";s:0:\"\";s:20:\"fusion_divider_color\";s:0:\"\";s:12:\"fusion_align\";s:0:\"\";s:19:\"fusion_align_mobile\";s:0:\"\";}i:5;a:12:{s:5:\"title\";s:7:\"FIND US\";s:4:\"text\";s:593:\"[fusion_map api_type=\"static\" embed_address=\"Notting Hill, London\" embed_map_type=\"roadmap\" address=\"Notting Hill, London\" type=\"terrain\" width=\"328px\" height=\"275px\" zoom=\"14\" scrollwheel=\"yes\" scale=\"yes\" zoom_pancontrol=\"yes\" animation=\"no\" popup=\"yes\" map_style=\"default\" overlay_color=\"\" static_map_color=\"\" infobox_content=\"\" infobox=\"default\" infobox_text_color=\"\" infobox_background_color=\"\" icon=\"\" icon_static=\"http://warmvast.local/wp-content/uploads/2017/03/construction_map_pin.png\" hide_on_mobile=\"small-visibility,medium-visibility,large-visibility\" class=\"\" id=\"\"][/fusion_map]\";s:6:\"filter\";b:1;s:6:\"visual\";b:1;s:20:\"fusion_padding_color\";s:0:\"\";s:15:\"fusion_bg_color\";s:0:\"\";s:21:\"fusion_bg_radius_size\";s:0:\"\";s:18:\"fusion_border_size\";s:0:\"\";s:19:\"fusion_border_style\";s:0:\"\";s:19:\"fusion_border_color\";s:0:\"\";s:12:\"fusion_align\";s:0:\"\";s:19:\"fusion_align_mobile\";s:0:\"\";}s:12:\"_multiwidget\";i:1;}','auto');
