INSERT INTO `wp_options` VALUES (791,'_site_transient_feed_bc9fd7f8eaf5e82b6773ce761d04a9c6','a:6:{s:5:\"child\";a:1:{s:0:\"\";a:1:{s:3:\"rss\";a:1:{i:0;a:6:{s:4:\"data\";s:3:\"\n\n\n\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:7:\"version\";s:3:\"2.0\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:0:\"\";a:1:{s:7:\"channel\";a:1:{i:0;a:6:{s:4:\"data\";s:49:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n		\n		\n		\n		\n		\n		\n		\n		\n		\n	\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:3:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:21:\"Avada Website Builder\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:17:\"https://avada.com\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:27:\"For WordPress & WooCommerce\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:13:\"lastBuildDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 29 Jun 2026 08:14:39 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"language\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"en-US\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:9:\"generator\";a:1:{i:0;a:5:{s:4:\"data\";s:28:\"https://wordpress.org/?v=7.0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"item\";a:10:{i:0;a:6:{s:4:\"data\";s:82:\"\n		\n		\n					\n		\n		\n		\n				\n		\n		\n		\n		\n\n					\n										\n					\n					\n			\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:5:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:33:\"How to Manage Your Avada Licenses\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:57:\"https://avada.com/blog/how-to-manage-your-avada-licenses/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:65:\"https://avada.com/blog/how-to-manage-your-avada-licenses/#respond\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 29 Jun 2026 05:45:34 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:4:{i:0;a:5:{s:4:\"data\";s:5:\"Avada\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:15:\"Beginners Guide\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:2;a:5:{s:4:\"data\";s:8:\"My Avada\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:3;a:5:{s:4:\"data\";s:15:\"Tutorial Videos\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:24:\"https://avada.com/blog//\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:345:\"Managing your Avada licenses has never been more accessible, thanks to the comprehensive features on the My Avada support and license management portal. For those new to the platform or looking for guidance, here\'s a detailed walkthrough of how to efficiently handle your Avada licenses and ensure the smooth operation of your web products.  ...\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"michaelb\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:18479:\"<div class=\"fusion-fullwidth fullwidth-box fusion-builder-row-1 fusion-flex-container has-pattern-background has-mask-background nonhundred-percent-fullwidth non-hundred-percent-height-scrolling\" style=\"--awb-border-radius-top-left:0px;--awb-border-radius-top-right:0px;--awb-border-radius-bottom-right:0px;--awb-border-radius-bottom-left:0px;--awb-flex-wrap:wrap;\" ><div class=\"fusion-builder-row fusion-row fusion-flex-align-items-flex-start fusion-flex-content-wrap\" style=\"max-width:1331.2px;margin-left: calc(-4% / 2 );margin-right: calc(-4% / 2 );\"><div class=\"fusion-layout-column fusion_builder_column fusion-builder-column-0 fusion_builder_column_1_1 1_1 fusion-flex-column\" style=\"--awb-bg-size:cover;--awb-width-large:100%;--awb-margin-top-large:20px;--awb-spacing-right-large:1.92%;--awb-margin-bottom-large:20px;--awb-spacing-left-large:1.92%;--awb-width-medium:100%;--awb-order-medium:0;--awb-spacing-right-medium:1.92%;--awb-spacing-left-medium:1.92%;--awb-width-small:100%;--awb-order-small:0;--awb-spacing-right-small:1.92%;--awb-spacing-left-small:1.92%;\"><div class=\"fusion-column-wrapper fusion-column-has-shadow fusion-flex-justify-content-flex-start fusion-content-layout-column\"><div class=\"fusion-text fusion-text-1\"><p>Managing your <a href=\"https://1.envato.market/e4rPJ1\" target=\"_blank\" rel=\"noopener noreferrer\">Avada</a> licenses has never been more accessible, thanks to the comprehensive features on the <a href=\"https://avada.com/blog/my-avada-dot-com/\" target=\"_blank\" rel=\"noopener noreferrer\">My Avada support and license management portal</a>. For those new to the platform or looking for guidance, here&#8217;s a detailed walkthrough of how to efficiently handle your <a href=\"https://avada.com/\" target=\"_blank\" rel=\"noopener noreferrer\">Avada</a> licenses and ensure the smooth operation of your web products.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-1 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">Overview</h2></div><div class=\"awb-toc-el awb-toc-el--1\" data-awb-toc-id=\"1\" data-awb-toc-options=\"{&quot;allowed_heading_tags&quot;:{&quot;h2&quot;:0,&quot;h3&quot;:1},&quot;ignore_headings&quot;:&quot;.awb-toc-el__list.awb-toc-el__list--0 li:first-child&quot;,&quot;ignore_headings_words&quot;:&quot;&quot;,&quot;enable_cache&quot;:&quot;yes&quot;,&quot;highlight_current_heading&quot;:&quot;no&quot;,&quot;hide_hidden_titles&quot;:&quot;yes&quot;,&quot;limit_container&quot;:&quot;post_content&quot;,&quot;select_custom_headings&quot;:&quot;&quot;,&quot;icon&quot;:&quot;fa-angle-right far&quot;,&quot;counter_type&quot;:&quot;custom_icon&quot;}\" style=\"--awb-item-font-size:var(--awb-typography4-font-size);--awb-item-line-height:var(--awb-typography4-line-height);--awb-item-letter-spacing:var(--awb-typography4-letter-spacing);--awb-item-text-transform:var(--awb-typography4-text-transform);--awb-item-color:var(--awb-color8);--awb-item-color-hover:var(--awb-color5);--awb-item-bg-color-hover:rgba(101,189,125,0);--awb-counter-color:var(--awb-color6);--awb-hover-counter-color:var(--awb-color5);--awb-list-indent:15px;--awb-item-padding-top:3px;--awb-item-padding-right:0;--awb-item-padding-bottom:5px;--awb-item-padding-left:0;--awb-item-font-family:var(--awb-typography4-font-family);--awb-item-font-weight:var(--awb-typography4-font-weight);--awb-item-font-style:var(--awb-typography4-font-style);\"><div class=\"awb-toc-el__content\"></div></div>\n<div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:50px;width:100%;\"></div><div class=\"fusion-title title fusion-title-2 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">Accessing The My Avada Portal</h2></div><div class=\"fusion-text fusion-text-2\"><p>To begin managing your licenses, navigate to the <a href=\"https://my.avada.com/\" target=\"_blank\" rel=\"noopener noreferrer\">My Avada portal</a>, which is accessible here. If you haven&#8217;t registered for an Avada Support account yet, watch the <a href=\"https://avada.com/documentation/how-to-register-for-my-avada/\" target=\"_blank\" rel=\"noopener noreferrer\">How to Register for My Avada</a> video for a step-by-step guide. Once registered, log in to access your account dashboard.</p>\n</div><div class=\"fusion-image-element\" style=\"--awb-caption-title-font-family:var(--h2_typography-font-family);--awb-caption-title-font-weight:var(--h2_typography-font-weight);--awb-caption-title-font-style:var(--h2_typography-font-style);--awb-caption-title-size:var(--h2_typography-font-size);--awb-caption-title-transform:var(--h2_typography-text-transform);--awb-caption-title-line-height:var(--h2_typography-line-height);--awb-caption-title-letter-spacing:var(--h2_typography-letter-spacing);\"><span class=\" fusion-imageframe imageframe-none imageframe-1 hover-type-none\"><img fetchpriority=\"high\" decoding=\"async\" width=\"1600\" height=\"1000\" alt=\"My Avada Login Screen\" title=\"My Avada Login Screen\" src=\"https://avada.com/wp-content/uploads/2024/10/my-avada-portal-post-login.png\" class=\"img-responsive wp-image-895033\" srcset=\"https://avada.com/wp-content/uploads/2024/10/my-avada-portal-post-login-200x125.png 200w, https://avada.com/wp-content/uploads/2024/10/my-avada-portal-post-login-400x250.png 400w, https://avada.com/wp-content/uploads/2024/10/my-avada-portal-post-login-600x375.png 600w, https://avada.com/wp-content/uploads/2024/10/my-avada-portal-post-login-800x500.png 800w, https://avada.com/wp-content/uploads/2024/10/my-avada-portal-post-login-1200x750.png 1200w, https://avada.com/wp-content/uploads/2024/10/my-avada-portal-post-login.png 1600w\" sizes=\"(max-width: 1024px) 100vw, (max-width: 640px) 100vw, 1600px\" /></span></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-3\"><p>The dashboard provides a snapshot of all your licenses and various options for managing them. The <a href=\"https://avada.com/documentation/how-to-use-my-avada/\" target=\"_blank\" rel=\"noopener noreferrer\">How to Use My Avada</a> video offers a complete overview of the portal&#8217;s features; however, in this article, we&#8217;ll focus on managing your licenses specifically.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-3 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">How To Manage Licenses</h2></div><div class=\"fusion-video fusion-youtube\" style=\"--awb-max-width:1280px;--awb-max-height:720px;--awb-align-self:center;--awb-width:100%;\"><div class=\"video-shortcode\"><priv-fac-lite-youtube class=\"fusion-hidden lty-load\" data-privacy-type=\"youtube\" videoid=\"lk_AlGCHJNs\" class=\"landscape\" params=\"wmode=transparent&autoplay=1&amp;enablejsapi=1\" title=\"YouTube video player 1\" data-button-label=\"Play Video\" width=\"1280\" height=\"720\" data-thumbnail-size=\"auto\" data-no-cookie=\"on\"></priv-fac-lite-youtube><div class=\"fusion-privacy-placeholder\" style=\"width:1280px; height:720px;\" data-privacy-type=\"youtube\"><div class=\"fusion-privacy-placeholder-content\"><div class=\"fusion-privacy-label\">For privacy reasons YouTube needs your permission to be loaded.</div><button data-privacy-type=\"youtube\" class=\"fusion-button button-default fusion-button-default-size button fusion-privacy-consent\">I Accept</button></div></div></div></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-4\"><p>Once inside the My Avada Dashboard, you can see a summary of all your licenses at the top. You&#8217;ll also notice a section providing a quick overview of the most recent licenses. To manage all your licenses, click the <strong>&#8220;Manage Licenses&#8221;</strong> link or select <strong>&#8220;Licenses&#8221;</strong> from the top menu.</p>\n</div><div class=\"fusion-image-element\" style=\"--awb-liftup-border-radius:0px;--awb-caption-title-font-family:var(--h2_typography-font-family);--awb-caption-title-font-weight:var(--h2_typography-font-weight);--awb-caption-title-font-style:var(--h2_typography-font-style);--awb-caption-title-size:var(--h2_typography-font-size);--awb-caption-title-transform:var(--h2_typography-text-transform);--awb-caption-title-line-height:var(--h2_typography-line-height);--awb-caption-title-letter-spacing:var(--h2_typography-letter-spacing);\"><div class=\"awb-image-frame awb-image-frame-2 imageframe-liftup\"><span class=\" fusion-imageframe imageframe-none imageframe-2\" style=\"border:1px solid var(--awb-color2);\"><a href=\"https://avada.com/wp-content/uploads/2024/10/my-avada-portal-post-dashboard.png\" class=\"fusion-lightbox\" data-rel=\"iLightbox[5c06cd08307185ddb0b]\" data-title=\"Avada Dashboard\" title=\"Avada Dashboard\"><img decoding=\"async\" width=\"2466\" height=\"2560\" alt=\"Avada Dashboard\" src=\"https://avada.com/wp-content/uploads/2024/10/my-avada-portal-post-dashboard.png\" class=\"img-responsive wp-image-895035\"/></a></span></div></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-5\"><p>The licenses management page contains helpful search and filtering options. You can search for a license by domain name or purchase code and use filters to sort licenses by their status: <strong>&#8220;Active,&#8221;</strong> <strong>&#8220;Locked,&#8221;</strong> or <strong>&#8220;All.&#8221;</strong> For example, if you search by the term <strong>&#8220;Avada,&#8221;</strong> you will quickly see all relevant licenses connected to that domain. Additionally, if any licenses are locked, you can contact support directly from this page to resolve the issue.</p>\n</div><div class=\"fusion-image-element\" style=\"--awb-liftup-border-radius:0px;--awb-caption-title-font-family:var(--h2_typography-font-family);--awb-caption-title-font-weight:var(--h2_typography-font-weight);--awb-caption-title-font-style:var(--h2_typography-font-style);--awb-caption-title-size:var(--h2_typography-font-size);--awb-caption-title-transform:var(--h2_typography-text-transform);--awb-caption-title-line-height:var(--h2_typography-line-height);--awb-caption-title-letter-spacing:var(--h2_typography-letter-spacing);\"><div class=\"awb-image-frame awb-image-frame-3 imageframe-liftup\"><span class=\" fusion-imageframe imageframe-none imageframe-3\" style=\"border:1px solid var(--awb-color2);\"><a href=\"https://avada.com/wp-content/uploads/2024/10/my-avada-portal-post-manage-licenses.png\" class=\"fusion-lightbox\" data-rel=\"iLightbox[509747b76b31fdccd6e]\" data-title=\"Manage Avada Licenses\" title=\"Manage Avada Licenses\"><img decoding=\"async\" width=\"2560\" height=\"2120\" alt=\"Manage Avada Licenses\" src=\"https://avada.com/wp-content/uploads/2024/10/my-avada-portal-post-manage-licenses.png\" class=\"img-responsive wp-image-895036\"/></a></span></div></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-6\"><p>To check your current license data information, a <strong>&#8220;Refresh All&#8221;</strong> button checks for any changes in license status, such as recently registered or unregistered licenses.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-4 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">Individual Licenses</h3></div><div class=\"fusion-text fusion-text-7\"><p>When viewing an individual license, you&#8217;ll see detailed information, including the purchase code, license status, and purchase date. You can also view the licenses&#8217; associated domains—both the live domain and the staging domain (if applicable). Each license allows one live domain and one staging domain, making managing your projects&#8217; development and production environment easy.</p>\n<p>One important feature is the ability to unregister a license from a domain. Under the terms of the Avada license, each license is valid for a single website project according to <a href=\"https://themeforest.net/licenses/terms/regular\" target=\"_blank\" rel=\"noopener noreferrer\">Envato&#8217;s licensing terms and conditions</a>. While not being a right granted by the license itself, we offer the additional flexibility to reuse the license on a new project if, and only if, the old site has completely been removed (no longer online). If you forgot to unregister the license before deleting the site, you can do so directly from the My Avada portal. Click the <strong>&#8220;Unlink&#8221;</strong> icon to unregister the license and make it available for a new domain.</p>\n<p>Suppose you&#8217;ve updated the website to which a license is linked. In that case, clicking the <strong>&#8220;Refresh All&#8221;</strong> button will update the domain information in the portal, reflecting the current license connection.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-5 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">License Deletion and Transfer</h3></div><div class=\"fusion-text fusion-text-8\"><p>The My Avada portal also allows you to delete a license from your account if needed. However, remember that deleting a license only removes it from your My Avada account. This feature is helpful if, for example, you need to transfer a license to a different account, such as when an agency passes the purchase code to an end user.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-6 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">Adding New Licenses</h3></div><div class=\"fusion-text fusion-text-9\"><p>If you have new licenses to add to your account, the &#8220;Add New License&#8221; button provides a simple process. You can manually enter a single purchase code or use the <strong>&#8220;Import from Envato&#8221;</strong> bulk import option. This allows you to import all licenses associated with <a href=\"https://1.envato.market/e4rPJ1\" target=\"_blank\" rel=\"noopener noreferrer\">your ThemeForest account</a>.</p>\n<p>After signing in to the Envato API with your ThemeForest credentials and authorizing the connection, any new licenses will be automatically added to your My Avada account.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-7 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">Resources</h2></div><div class=\"fusion-text fusion-text-10\"><p>For any additional questions, Avada provides a comprehensive <a href=\"https://avada.com/documentation/avada-registration-and-licensing-faq/\" target=\"_blank\" rel=\"noopener noreferrer\">Licensing and Registration FAQ</a> document that addresses many common inquiries.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-8 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">Summary</h2></div><div class=\"fusion-text fusion-text-11\"><p>Managing your Avada licenses has never been simpler! With the My Avada support and license management portal, you can easily view, organize, and control all your licenses in one place. Whether you&#8217;re managing a single project or multiple domains, the portal offers powerful tools like search, filtering, and quick license refreshes to keep everything up to date.</p>\n<p>Effortlessly unregister licenses, transfer them between accounts, and add new ones from your ThemeForest profile with just a few clicks. Plus, with detailed video guides and a comprehensive FAQ, you&#8217;ll have all the support you need at your fingertips.</p>\n</div></div></div></div></div>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:62:\"https://avada.com/blog/how-to-manage-your-avada-licenses/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:1;a:6:{s:4:\"data\";s:85:\"\n		\n		\n					\n		\n		\n		\n				\n		\n		\n		\n		\n		\n\n					\n										\n					\n					\n			\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:5:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:43:\"How To Manage Website Privacy &amp; Consent\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:61:\"https://avada.com/blog/how-to-manage-website-privacy-consent/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:69:\"https://avada.com/blog/how-to-manage-website-privacy-consent/#respond\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 22 Jun 2026 09:58:53 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:5:{i:0;a:5:{s:4:\"data\";s:5:\"Avada\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:15:\"Beginners Guide\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:2;a:5:{s:4:\"data\";s:8:\"Features\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:3;a:5:{s:4:\"data\";s:7:\"Privacy\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:4;a:5:{s:4:\"data\";s:9:\"WordPress\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:24:\"https://avada.com/blog//\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:313:\"Data privacy compliance is one of those website jobs nobody gets excited about; however, it is important to master. If you have visitors from the EU, California, or any region with data privacy laws, it\'s not optional — and the good news is that Avada has built a genuinely flexible system to handle it. One ...\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"michaelb\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:55749:\"<div class=\"fusion-fullwidth fullwidth-box fusion-builder-row-2 fusion-flex-container nonhundred-percent-fullwidth non-hundred-percent-height-scrolling\" style=\"--awb-border-radius-top-left:0px;--awb-border-radius-top-right:0px;--awb-border-radius-bottom-right:0px;--awb-border-radius-bottom-left:0px;--awb-flex-wrap:wrap;\" ><div class=\"fusion-builder-row fusion-row fusion-flex-align-items-flex-start fusion-flex-content-wrap\" style=\"max-width:1331.2px;margin-left: calc(-4% / 2 );margin-right: calc(-4% / 2 );\"><div class=\"fusion-layout-column fusion_builder_column fusion-builder-column-1 fusion_builder_column_1_1 1_1 fusion-flex-column\" style=\"--awb-bg-blend:overlay;--awb-bg-size:cover;--awb-width-large:100%;--awb-margin-top-large:20px;--awb-spacing-right-large:1.92%;--awb-margin-bottom-large:20px;--awb-spacing-left-large:1.92%;--awb-width-medium:100%;--awb-spacing-right-medium:1.92%;--awb-spacing-left-medium:1.92%;--awb-width-small:100%;--awb-spacing-right-small:1.92%;--awb-spacing-left-small:1.92%;\"><div class=\"fusion-column-wrapper fusion-flex-justify-content-flex-start fusion-content-layout-column\"><div class=\"fusion-text fusion-text-12\"><p>Data privacy compliance is one of those website jobs nobody gets excited about; however, it is important to master. If you have visitors from the EU, California, or any region with data privacy laws, it&#8217;s not optional — and the good news is that <a href=\"https://avada.com/\" target=\"_self\" rel=\"noopener noreferrer\">Avada</a> has built a genuinely flexible system to handle it. One place to set your options, and multiple ways to present them to your visitors.</p>\n<p>This post is the big-picture guide. We&#8217;ll cover the regulatory background, walk through every global privacy option in Avada, and configure the <a href=\"https://avada.com/documentation/avada-privacy-consent-bar/\" target=\"_self\" rel=\"noopener noreferrer\">Avada Privacy &amp; Consent Bar</a> from scratch. If you&#8217;re looking for the deep dives on the <a href=\"https://avada.com/element/privacy-consent/\" target=\"_self\" rel=\"noopener noreferrer\">Privacy and Consent Element</a> itself, we&#8217;ve covered those separately — see <a href=\"https://avada.com/blog/how-to-use-the-avada-privacy-consent-element/\" target=\"_self\" rel=\"noopener noreferrer\">How To Use The Avada Privacy &amp; Consent Element</a> and <a href=\"https://avada.com/blog/how-to-add-privacy-consent-options-to-an-avada-off-canvas/\" target=\"_self\" rel=\"noopener noreferrer\">How To Add Privacy &amp; Consent Options to an Avada Off-Canvas</a>. This guide provides an overview of the foundations of privacy, consent, and how the various tools can work together.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-9 fusion-sep-none fusion-title-text fusion-title-size-two awb-exclude-from-toc\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">Overview</h2></div><div class=\"awb-toc-el awb-toc-el--2\" data-awb-toc-id=\"2\" data-awb-toc-options=\"{&quot;allowed_heading_tags&quot;:{&quot;h2&quot;:0,&quot;h3&quot;:1},&quot;ignore_headings&quot;:&quot;.awb-toc-el__list.awb-toc-el__list--0 li:first-child&quot;,&quot;ignore_headings_words&quot;:&quot;&quot;,&quot;enable_cache&quot;:&quot;yes&quot;,&quot;highlight_current_heading&quot;:&quot;no&quot;,&quot;hide_hidden_titles&quot;:&quot;yes&quot;,&quot;limit_container&quot;:&quot;post_content&quot;,&quot;select_custom_headings&quot;:&quot;&quot;,&quot;icon&quot;:&quot;fa-angle-right far&quot;,&quot;counter_type&quot;:&quot;custom_icon&quot;}\" style=\"--awb-item-font-size:var(--awb-typography4-font-size);--awb-item-line-height:var(--awb-typography4-line-height);--awb-item-letter-spacing:var(--awb-typography4-letter-spacing);--awb-item-text-transform:var(--awb-typography4-text-transform);--awb-item-color:var(--awb-color8);--awb-item-color-hover:var(--awb-color5);--awb-item-bg-color-hover:rgba(101,189,125,0);--awb-counter-color:var(--awb-color6);--awb-hover-counter-color:var(--awb-color5);--awb-list-indent:15px;--awb-item-padding-top:3px;--awb-item-padding-right:0;--awb-item-padding-bottom:5px;--awb-item-padding-left:0;--awb-item-font-family:var(--awb-typography4-font-family);--awb-item-font-weight:var(--awb-typography4-font-weight);--awb-item-font-style:var(--awb-typography4-font-style);\"><div class=\"awb-toc-el__content\"></div></div>\n<div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:50px;width:100%;\"></div><div class=\"fusion-title title fusion-title-10 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">The Benefits of Practicing Data Privacy Compliance</h2></div><div class=\"fusion-image-element\" style=\"--awb-caption-title-font-family:var(--h2_typography-font-family);--awb-caption-title-font-weight:var(--h2_typography-font-weight);--awb-caption-title-font-style:var(--h2_typography-font-style);--awb-caption-title-size:var(--h2_typography-font-size);--awb-caption-title-transform:var(--h2_typography-text-transform);--awb-caption-title-line-height:var(--h2_typography-line-height);--awb-caption-title-letter-spacing:var(--h2_typography-letter-spacing);\"><span class=\" fusion-imageframe imageframe-none imageframe-4 hover-type-none\"><img decoding=\"async\" width=\"2000\" height=\"400\" alt=\"Data Privacy Icons\" title=\"Data Privacy Icons\" src=\"https://avada.com/wp-content/uploads/2026/06/manage-website-privacy-post-privacy-icons.png\" class=\"img-responsive wp-image-897725\" srcset=\"https://avada.com/wp-content/uploads/2026/06/manage-website-privacy-post-privacy-icons-200x40.png 200w, https://avada.com/wp-content/uploads/2026/06/manage-website-privacy-post-privacy-icons-400x80.png 400w, https://avada.com/wp-content/uploads/2026/06/manage-website-privacy-post-privacy-icons-600x120.png 600w, https://avada.com/wp-content/uploads/2026/06/manage-website-privacy-post-privacy-icons-800x160.png 800w, https://avada.com/wp-content/uploads/2026/06/manage-website-privacy-post-privacy-icons-1200x240.png 1200w, https://avada.com/wp-content/uploads/2026/06/manage-website-privacy-post-privacy-icons.png 2000w\" sizes=\"(max-width: 1024px) 100vw, (max-width: 640px) 100vw, 2000px\" /></span></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-13\"><p>Beyond just avoiding fines (which, fair enough, is the headline reason — GDPR penalties can reach 4% of global annual revenue), there are some genuinely practical benefits, especially for a website owner:</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-11 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">☇ Trust And Credibility</h3></div><div class=\"fusion-text fusion-text-14\"><p>Visitors are more privacy-aware than ever. A site that asks for consent clearly and respects the answer signals professionalism. People notice when a cookie banner gives them a real choice, versus when it&#8217;s a dark-pattern maze designed to wear them down — and that impression carries over to how much they trust your brand with things like their email address or credit card.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-12 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">☇ Better Data Quality</h3></div><div class=\"fusion-text fusion-text-15\"><p>This one&#8217;s counterintuitive. When you only collect data from people who&#8217;ve actually consented, you end up with smaller but cleaner datasets. Your analytics reflect engaged visitors rather than everyone plus bots plus people who&#8217;d opt out if they could. Decisions made on that data tend to be sounder.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-13 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">☇ Reduced Breach Exposure</h3></div><div class=\"fusion-text fusion-text-16\"><p>Compliance practices push you toward data minimization — collecting only what you need and keeping it only as long as necessary. The less personal data you hold, the less damage a breach can do, and the less attractive a target you are in the first place. You can&#8217;t leak what you never stored.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-14 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">☇ Market Access</h3></div><div class=\"fusion-text fusion-text-17\"><p>If you sell to EU customers, compliance isn&#8217;t a nice-to-have; it&#8217;s the price of entry. The same increasingly applies to California, Brazil (LGPD), and a growing list of jurisdictions. Getting your house in order once opens multiple markets, and many B2B clients now require proof of compliance from vendors before they&#8217;ll sign anything.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-15 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">☇ Operational Clarity</h3></div><div class=\"fusion-text fusion-text-18\"><p>The process of becoming compliant forces useful questions: what data are we actually collecting, why, where does it live, who has access? Plenty of businesses discover forgotten plugins, abandoned tracking scripts, or third-party services they didn&#8217;t realize were phoning home. That audit has value even setting the legal side aside.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-16 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">☇ Competitive Differentiation</h3></div><div class=\"fusion-text fusion-text-19\"><p>As privacy becomes a buying criterion — and it is, particularly for younger and more technical audiences — being able to say &#8220;we load fonts locally, we don&#8217;t track you without asking&#8221; becomes a feature rather than a legal footnote.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-17 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">What is the GDPR and the CCPA?</h2></div><div class=\"fusion-text fusion-text-20\"><p>GDPR stands for the <a href=\"https://gdpr.eu/\" target=\"_blank\" rel=\"noopener noreferrer\">General Data Protection Regulation</a>, a binding privacy framework that came into force in the European Union in 2018. And here&#8217;s the part people often miss: it doesn&#8217;t just apply to businesses in the EU. If you have customers in the EU, it applies to you too. Other jurisdictions have their own versions — the <a href=\"https://oag.ca.gov/privacy/ccpa\" target=\"_blank\" rel=\"noopener noreferrer\">CCPA</a> in California is the obvious one — so your actual obligations depend on where you&#8217;re based, where your customers are, and what third-party services your site uses.</p>\n</div><div class=\"fusion-image-element\" style=\"--awb-caption-title-font-family:var(--h2_typography-font-family);--awb-caption-title-font-weight:var(--h2_typography-font-weight);--awb-caption-title-font-style:var(--h2_typography-font-style);--awb-caption-title-size:var(--h2_typography-font-size);--awb-caption-title-transform:var(--h2_typography-text-transform);--awb-caption-title-line-height:var(--h2_typography-line-height);--awb-caption-title-letter-spacing:var(--h2_typography-letter-spacing);\"><span class=\" fusion-imageframe imageframe-none imageframe-5 hover-type-none\"><img decoding=\"async\" width=\"2000\" height=\"800\" alt=\"GDPR Logo\" title=\"GDPR Logo\" src=\"https://avada.com/wp-content/uploads/2026/06/manage-website-privacy-post-gdpr-logo.png\" class=\"img-responsive wp-image-897726\" srcset=\"https://avada.com/wp-content/uploads/2026/06/manage-website-privacy-post-gdpr-logo-200x80.png 200w, https://avada.com/wp-content/uploads/2026/06/manage-website-privacy-post-gdpr-logo-400x160.png 400w, https://avada.com/wp-content/uploads/2026/06/manage-website-privacy-post-gdpr-logo-600x240.png 600w, https://avada.com/wp-content/uploads/2026/06/manage-website-privacy-post-gdpr-logo-800x320.png 800w, https://avada.com/wp-content/uploads/2026/06/manage-website-privacy-post-gdpr-logo-1200x480.png 1200w, https://avada.com/wp-content/uploads/2026/06/manage-website-privacy-post-gdpr-logo.png 2000w\" sizes=\"(max-width: 1024px) 100vw, (max-width: 640px) 100vw, 2000px\" /></span></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-alert alert custom alert-custom fusion-alert-left awb-alert-inherit-link-color\" style=\"--awb-background-color:#ebfaff;--awb-accent-color:#005272;--awb-border-size:0px;--awb-border-top-left-radius:5px;--awb-border-top-right-radius:5px;--awb-border-bottom-left-radius:5px;--awb-border-bottom-right-radius:5px;\" role=\"alert\"><div class=\"fusion-alert-content-wrapper\"><span class=\"alert-icon\"><i class=\"fa-exclamation-circle fas\" aria-hidden=\"true\"></i></span><span class=\"fusion-alert-content\">If you&#8217;re unsure of your legal requirements, talk to a lawyer. This guide shows you the tools; it can&#8217;t tell you which boxes you legally need to tick.</span></div></div><div class=\"fusion-text fusion-text-21\"><p><strong>And a point worth noting:</strong> Avada itself doesn&#8217;t need to be GDPR-compliant because it doesn&#8217;t collect any data. The privacy tools exist to help you make your website compliant — because the moment you embed a YouTube video, load Google Fonts from a CDN, or run Google Analytics, you&#8217;re potentially sending visitor data to third parties.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-18 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">How the Whole System Fits Together in Avada</h2></div><div class=\"fusion-video fusion-youtube\" style=\"--awb-max-width:1280px;--awb-max-height:720px;--awb-align-self:center;--awb-width:100%;\"><div class=\"video-shortcode\"><priv-fac-lite-youtube class=\"fusion-hidden lty-load\" data-privacy-type=\"youtube\" videoid=\"20il92AFsFk\" class=\"landscape\" params=\"wmode=transparent&autoplay=1&amp;enablejsapi=1\" title=\"Website Privacy &amp; Consent in Avada\" data-button-label=\"Play Video\" width=\"1280\" height=\"720\" data-thumbnail-size=\"auto\" data-no-cookie=\"on\"></priv-fac-lite-youtube><div class=\"fusion-privacy-placeholder\" style=\"width:1280px; height:720px;\" data-privacy-type=\"youtube\"><div class=\"fusion-privacy-placeholder-content\"><div class=\"fusion-privacy-label\">For privacy reasons YouTube needs your permission to be loaded.</div><button data-privacy-type=\"youtube\" class=\"fusion-button button-default fusion-button-default-size button fusion-privacy-consent\">I Accept</button></div></div></div></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-22\"><p>Before we touch a single option, here&#8217;s the mental model. Avada&#8217;s Privacy System has two halves:</p>\n</div><ul style=\"--awb-iconcolor:var(--awb-custom_color_5);--awb-line-height:27.2px;--awb-icon-width:27.2px;--awb-icon-height:27.2px;--awb-icon-margin:11.2px;--awb-content-margin:38.4px;\" class=\"fusion-checklist fusion-checklist-1 fusion-checklist-default type-icons\"><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-cogs fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><strong>The Privacy Consent Tools (Global Options)</strong> – This is where you define your privacy setup: which embeds need consent, your cookie categories, expiration times, descriptions.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-cogs fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><strong>The Display Layer</strong> – The Privacy &amp; Consent Bar and/or the Privacy and Consent element. These are how visitors actually see and interact with the options you defined.</div></li></ul><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-23\"><p>Both halves are totally optional, and they work independently. You might configure the consent tools and present them through the Element on your privacy policy page (or any other page on your site). You might skip the tools entirely and just show a simple bar that tells visitors about the necessary cookies. Or you might use everything together. It all depends on what you need to inform your visitors of. Everything lives under <strong>Options &gt; Privacy &amp; Consent</strong> in the Avada Global Options. Let&#8217;s go through it.</p>\n</div><div class=\"fusion-alert alert custom alert-custom fusion-alert-left awb-alert-inherit-link-color\" style=\"--awb-background-color:#ebfaff;--awb-accent-color:#005272;--awb-border-size:0px;--awb-border-top-left-radius:5px;--awb-border-top-right-radius:5px;--awb-border-bottom-left-radius:5px;--awb-border-bottom-right-radius:5px;\" role=\"alert\"><div class=\"fusion-alert-content-wrapper\"><span class=\"alert-icon\"><i class=\"avada-elements-avada-logo\" aria-hidden=\"true\"></i></span><span class=\"fusion-alert-content\">Avada Dashboard → Options → Global Options → Privacy &amp; Consent</span></div></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-19 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\"><mark class=\"fusion-highlight light highlight1 awb-highlight-marker\" style=\"--awb-color:rgba(123,188,216,0.38);\">The Avada Global Privacy Options</mark></h2></div><div class=\"fusion-text fusion-text-24\"><p>By default, you&#8217;ll only see three options here, because both the Privacy Consent Tools and the Privacy &amp; Consent Bar are disabled out of the box. </p>\n</div><div class=\"fusion-image-element\" style=\"--awb-liftup-border-radius:0px;--awb-caption-title-font-family:var(--h2_typography-font-family);--awb-caption-title-font-weight:var(--h2_typography-font-weight);--awb-caption-title-font-style:var(--h2_typography-font-style);--awb-caption-title-size:var(--h2_typography-font-size);--awb-caption-title-transform:var(--h2_typography-text-transform);--awb-caption-title-line-height:var(--h2_typography-line-height);--awb-caption-title-letter-spacing:var(--h2_typography-letter-spacing);\"><div class=\"awb-image-frame awb-image-frame-6 imageframe-liftup\"><span class=\" fusion-imageframe imageframe-none imageframe-6\" style=\"border:1px solid var(--awb-color2);\"><a href=\"https://avada.com/wp-content/uploads/2026/06/manage-website-privacy-post-privacy-global-options.png\" class=\"fusion-lightbox\" data-rel=\"iLightbox[c0ba37103d45a514daf]\" data-title=\"Avada Privacy Global Options\" title=\"Avada Privacy Global Options\"><img decoding=\"async\" width=\"2000\" height=\"1650\" alt=\"Avada Privacy Global Options\" src=\"https://avada.com/wp-content/uploads/2026/06/manage-website-privacy-post-privacy-global-options.png\" class=\"img-responsive wp-image-897728\" srcset=\"https://avada.com/wp-content/uploads/2026/06/manage-website-privacy-post-privacy-global-options-200x165.png 200w, https://avada.com/wp-content/uploads/2026/06/manage-website-privacy-post-privacy-global-options-400x330.png 400w, https://avada.com/wp-content/uploads/2026/06/manage-website-privacy-post-privacy-global-options-600x495.png 600w, https://avada.com/wp-content/uploads/2026/06/manage-website-privacy-post-privacy-global-options-800x660.png 800w, https://avada.com/wp-content/uploads/2026/06/manage-website-privacy-post-privacy-global-options-1200x990.png 1200w, https://avada.com/wp-content/uploads/2026/06/manage-website-privacy-post-privacy-global-options.png 2000w\" sizes=\"(max-width: 1024px) 100vw, (max-width: 640px) 100vw, 2000px\" /></a></span></div></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-text fusion-text-25\"><p>There&#8217;s also an important note at the top explaining the cookie created when you use the privacy consent option — worth a read.</p>\n</div><div class=\"fusion-alert alert custom alert-custom fusion-alert-left awb-alert-inherit-link-color\" style=\"--awb-background-color:#ebfaff;--awb-accent-color:#005272;--awb-border-size:0px;--awb-border-top-left-radius:5px;--awb-border-top-right-radius:5px;--awb-border-bottom-left-radius:5px;--awb-border-bottom-right-radius:5px;\" role=\"alert\"><div class=\"fusion-alert-content-wrapper\"><span class=\"alert-icon\"><i class=\"avada-elements-avada-logo\" aria-hidden=\"true\"></i></span><span class=\"fusion-alert-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#005272;--awb-text-color:var(--awb-color1);\">Important Note</mark> &#8211; The options in this section help you comply more easily with data privacy regulations such as the GDPR. When the <strong>&#8220;Privacy Consent&#8221;</strong> option is enabled, Avada creates a cookie named <strong>&#8220;privacy_embeds&#8221;</strong> in visitors’ browsers to store and manage consent preferences for third-party embeds and tracking scripts. This also includes scripts added through <strong>&#8220;Custom Code Snippets&#8221;</strong> (Advanced &gt; Code Fields) that use a privacy category. You may want to include information about this cookie in your privacy policy.</p></span></div></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-20 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">↳ Google &amp; Font Awesome Fonts Mode</h3></div><div class=\"fusion-text fusion-text-26\"><p>This first option is small but genuinely useful. When set to <strong>&#8220;Local&#8221;</strong>, <a href=\"https://fonts.google.com/\" target=\"_blank\" rel=\"noopener noreferrer\">Google Fonts</a> and <a href=\"https://fontawesome.com/\" target=\"_blank\" rel=\"noopener noreferrer\">Font Awesome</a> fonts are downloaded to your own server, which satisfies GDPR criteria — no font requests pinging Google&#8217;s servers with your visitors&#8217; data. Alternatively, set it to <strong>&#8220;CDN&#8221;</strong> to load fonts from the Google and Font Awesome CDNs. If GDPR applies to you, <strong>&#8220;Local&#8221;</strong> is the safe choice.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-21 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">↳ Privacy Consent Tools</h3></div><div class=\"fusion-text fusion-text-27\"><p>Turn it on, and Avada will prevent scripts and embeds from loading until your visitor gives consent. Do you need it? Maybe not. If you only have necessary cookies and no third-party embeds, you can leave this disabled and just let users know about your cookies in the privacy bar.</p>\n<p>But if your site embeds YouTube videos, runs Google Analytics, or loads anything else from a third party, enable it — and a whole range of new options appear.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-22 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">↳ Privacy Consent Cookie Expiration</h3></div><div class=\"fusion-text fusion-text-28\"><p>How many days does the consent cookie last before visitors are asked again? The default is 30, and you can push it up to 366 days (for leap years).</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-23 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">↳ Privacy Consent Types</h3></div><div class=\"fusion-text fusion-text-29\"><p>Here you choose which embeds require consent. There are 12 in all, including a range of Google services. Only select what you actually use — there&#8217;s no point gating consent for services that never appear on your site. And note: custom code snippets with a privacy category are automatically included, so you don&#8217;t need to select those here.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-24 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">↳ Privacy Selected Consent Types</h3></div><div class=\"fusion-text fusion-text-30\"><p>This controls which of those embeds are selected by default when a visitor first sees the consent bar or Element. Selecting them all means visitors opt out rather than opt in — check whether that&#8217;s acceptable under your local regulations before mirroring that choice.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-25 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">↳ Third-Party Embed Description &amp; Placeholder Colors</h3></div><div class=\"fusion-text fusion-text-31\"><p>When a visitor hasn&#8217;t accepted a third-party embed, Avada shows a placeholder in its place — a box explaining that consent is needed, with a button to grant it. The description comes with a sensible default you can customize, and the two color options control the placeholder&#8217;s background and text. Tie these into your color palette (in the video, color 5 for the background and color 1 for the text) so the placeholders don&#8217;t look like an afterthought.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-26 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">↳ Google Consent Mode v2</h3></div><div class=\"fusion-text fusion-text-32\"><p>This section gives you a label and description for each of the four Google options: Google Analytics, Google Advertising cookies, Google Advertising user data, and Google Advertising personalization. Defaults are pre-filled, but everything is editable.</p>\n</div><div class=\"fusion-title title fusion-title-27 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">↳ Consent Categories</h3></div><div class=\"fusion-text fusion-text-33\"><p>This is where the system gets properly flexible. It&#8217;s a repeater row, so you can add as many categories as you need, each with a custom title and description. The available category types are custom content, necessary cookies, functional cookies (third-party embeds), statistics cookies (analytics), and marketing cookies (advertising and targeting).</p>\n<p>These categories define the grouped sections visitors see in both the Avada Privacy &amp; Consent Bar and the Avada Privacy and Consent Element when the group layout is used. A cluster of related options follows:</p>\n</div><ul style=\"--awb-iconcolor:var(--awb-color8);--awb-line-height:27.2px;--awb-icon-width:27.2px;--awb-icon-height:27.2px;--awb-icon-margin:11.2px;--awb-content-margin:38.4px;\" class=\"fusion-checklist fusion-checklist-2 fusion-checklist-default type-icons\"><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Group Master Toggle</mark> — Adds a master checkbox next to each group title, allowing visitors to enable or disable an entire category at once. If you want this on the bar, set it here. The Element has its own override, so you can leave it off globally and enable it per-element.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\">\n<mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">List WordPress Necessary Cookies</mark> &#8211; Only appears if you&#8217;ve added a category of type <strong>&#8220;necessary cookies&#8221;</strong>. Enable it, and an extra option appears to control the opacity of the necessary cookies, visually signaling that these can&#8217;t be toggled off.</p>\n</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Show Cookie Lifespan</mark> &#8211; Displays the expiration days you set earlier next to each cookie.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Show Cookie Description</mark> &#8211; Displays each cookie&#8217;s description below its consent item.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Cookie Description Toggle</mark> &#8211; Adds an expand/collapse button next to each consent item&#8217;s description. Like the master toggle, this can be overridden in the element, so you can leave it off globally if you only need it there.</div></li></ul><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-34\"><p>Save the Global Options, and the definition half of the system is done. Now for the display half.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-28 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\"><mark class=\"fusion-highlight light highlight1 awb-highlight-marker\" style=\"--awb-color:rgba(123,188,216,0.38);\">The Avada Privacy &amp; Consent Bar</mark></h2></div><div class=\"fusion-text fusion-text-35\"><p>Flip the Privacy &amp; Consent Bar option to <strong>“On”</strong>, and a bar appears along the bottom of your site, informing visitors of your Privacy and Consent details. A new batch of global options loads with it.</p>\n</div><div class=\"fusion-image-element\" style=\"--awb-caption-title-font-family:var(--h2_typography-font-family);--awb-caption-title-font-weight:var(--h2_typography-font-weight);--awb-caption-title-font-style:var(--h2_typography-font-style);--awb-caption-title-size:var(--h2_typography-font-size);--awb-caption-title-transform:var(--h2_typography-text-transform);--awb-caption-title-line-height:var(--h2_typography-line-height);--awb-caption-title-letter-spacing:var(--h2_typography-letter-spacing);\"><span class=\" fusion-imageframe imageframe-none imageframe-7 hover-type-none\" style=\"border:1px solid var(--awb-color2);\"><a href=\"https://avada.com/wp-content/uploads/2026/06/manage-website-privacy-post-privacy-bar-options.jpg\" class=\"fusion-lightbox\" data-rel=\"iLightbox[3ecd20e55ca8029299e]\" data-title=\"Avada Privacy Bar Options\" title=\"Avada Privacy Bar Options\"><img decoding=\"async\" width=\"2000\" height=\"1650\" alt=\"Avada Privacy Bar Options\" src=\"https://avada.com/wp-content/uploads/2026/06/manage-website-privacy-post-privacy-bar-options.jpg\" class=\"img-responsive wp-image-897729\" srcset=\"https://avada.com/wp-content/uploads/2026/06/manage-website-privacy-post-privacy-bar-options-200x165.jpg 200w, https://avada.com/wp-content/uploads/2026/06/manage-website-privacy-post-privacy-bar-options-400x330.jpg 400w, https://avada.com/wp-content/uploads/2026/06/manage-website-privacy-post-privacy-bar-options-600x495.jpg 600w, https://avada.com/wp-content/uploads/2026/06/manage-website-privacy-post-privacy-bar-options-800x660.jpg 800w, https://avada.com/wp-content/uploads/2026/06/manage-website-privacy-post-privacy-bar-options-1200x990.jpg 1200w, https://avada.com/wp-content/uploads/2026/06/manage-website-privacy-post-privacy-bar-options.jpg 2000w\" sizes=\"(max-width: 1024px) 100vw, (max-width: 640px) 100vw, 2000px\" /></a></span></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-36\"><p>The bar has two modes. If you enable it without the Privacy Consent Tools, you get just eight or nine options — enough for a simple bar that tells users about necessary cookies and nothing more. Perfectly valid. But with the consent tools enabled, you can also switch on the Privacy Bar Settings, which turns the bar into something far more capable — close to the full Privacy and Consent Element, living in a bar.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-29 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">↳ Styling the Privacy Bar</h3></div><div class=\"fusion-text fusion-text-37\"><p>The first options control the general styling and appearance:</p>\n</div><ul style=\"--awb-iconcolor:var(--awb-color8);--awb-line-height:27.2px;--awb-icon-width:27.2px;--awb-icon-height:27.2px;--awb-icon-margin:11.2px;--awb-content-margin:38.4px;\" class=\"fusion-checklist fusion-checklist-3 fusion-checklist-default type-icons\"><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Privacy Bar Expanded Padding</mark> — The padding around your content (the content itself determines the overall size). The video example uses 30px all around.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Background Color, Font Size, Text Color, Link Color, &amp; Link Hover Color</mark> &#8211; Standard styling. The example uses color 7 for the background and color 1 for the text.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Privacy Bar Text</mark> &#8211; The actual message. This can be as short or as long as your privacy situation demands. There&#8217;s no template that fits everyone here; it depends entirely on what you need to disclose.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Privacy Bar Button Text</mark> &#8211; &#8220;Okay&#8221; by default, and that&#8217;s fine for most use cases.</div></li></ul><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-title title fusion-title-30 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">↳ Privacy Bar Settings: The Advanced Mode</h3></div><div class=\"fusion-text fusion-text-38\"><p><strong>“Privacy Bar Button Save On Click”</strong> changes what your consent flow actually means. Set to <strong>“No”</strong>, the button is just an acknowledgment. The bar dismisses, and visitors grant consents individually via the placeholder buttons on the details panel.</p>\n<p>Set to <strong>“Yes”</strong>, clicking the button grants all the consent types you selected under Privacy Selected Consent Types. Either way, once the details panel is open, clicking the button always saves the current checkbox selection.</p>\n<p>That&#8217;s a meaningful difference. <strong>&#8220;No&#8221;</strong> means dismissing the bar grants nothing; <strong>&#8220;Yes&#8221;</strong> means one click consents to your defaults. Choose based on your regulatory requirements, not convenience.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-31 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">↳ The Button Behavior Option</h3></div><div class=\"fusion-text fusion-text-39\"><p>Enable <strong>“Privacy Bar Settings”</strong>, and a settings link is added to the bar that opens a full details panel with checkboxes for tracking and third-party embeds. A stack of new options arrives with it:</p>\n</div><ul style=\"--awb-iconcolor:var(--awb-color8);--awb-line-height:27.2px;--awb-icon-width:27.2px;--awb-icon-height:27.2px;--awb-icon-margin:11.2px;--awb-content-margin:38.4px;\" class=\"fusion-checklist fusion-checklist-4 fusion-checklist-default type-icons\"><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Settings Style</mark> — The settings control can be a plain link or a button.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Settings Text</mark> &#8211; &#8220;Settings&#8221; by default, changeable to anything.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\">\n<mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Update Button Text</mark> &#8211; When a visitor changes a selection in the settings panel, the main button text switches from your normal label (<strong>&#8220;Okay&#8221;</strong>) to this one (<strong>&#8220;Update Settings&#8221;</strong> by default). Deselect everything back to how it was, and the button reverts. This is a small detail, but it gives visitors clear feedback that there&#8217;s something to save.</p>\n</div></li></ul><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-title title fusion-title-32 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">↳ Layout Options</h3></div><div class=\"fusion-text fusion-text-40\"><p>The settings content can display as Columns (sections spread across the screen) or tabs. Tabs come with their own extras — content height, border size, border and background colors, and content padding. Columns are the default and work well for most setups. Either way, Privacy Bar Content Max Width controls how much horizontal room the panel gets — bumping it to 90% gives the categories space to breathe.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-33 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">↳ Typography and Detail Styling</h3></div><div class=\"fusion-text fusion-text-41\"><p>There are options for the heading font size and color, a column gap (30px by default), plus colors for the cookie lifespan and description text. The lifespan and description colors inherit the bar&#8217;s text color when left empty, but setting them separately (color 4 and color 3 in the example) helps visually distinguish the metadata from the main labels. The cookie description font size is 0.85em by default, which is easy to read.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-34 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">↳ Consent Item Style</h3></div><div class=\"fusion-text fusion-text-42\"><p>Choose between standard checkboxes or slide toggles for the consent items. Toggles feel more modern, and if you pick them, you also get options for the inactive, active, and thumb colors.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-35 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">↳ Accept All and Reject All Buttons</h3></div><div class=\"fusion-text fusion-text-43\"><p>Both are optional, and each includes editable button text when enabled. Whether you want them depends on your setup — if your defaults already reflect what most visitors would choose and the save-on-click behavior handles it, you may not need them at all.</p>\n<p>Once configured, the flow works like this: a visitor changes a selection in the tracking cookies or third-party embeds, the button switches to <strong>&#8220;Update Settings,&#8221;</strong> they click it, their preferences are saved, and the bar disappears for as long as your cookie expiration allows.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-36 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">Test It Out First</h2></div><div class=\"fusion-text fusion-text-44\"><p>With everything configured, visit a page with an embedded YouTube video — if YouTube consent hasn&#8217;t been granted, the video simply won&#8217;t load. In its place sits your styled placeholder asking for permission. Grant it, and the choice is stored in a cookie for the duration you set.</p>\n<p>One testing tip from the video that&#8217;ll save you some confusion: once you&#8217;ve saved your own consent preferences, the cookie is valid for the full expiration period — meaning the privacy bar won&#8217;t show for you anymore, even though you&#8217;re trying to test it. To reset, open Chrome DevTools (right-click and select Inspect), go to the <strong>“Application”</strong> tab, and clear the site data. That wipes the consent cookie (and logs you out, so keep your password handy), and you&#8217;re back to a fresh-visitor view.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-37 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">Other Avada Privacy Tools Worth Knowing</h2></div><div class=\"fusion-text fusion-text-45\"><p>The Privacy Bar and the Privacy Element get the spotlight, but Avada offers a few more privacy options.</p>\n<p><a href=\"https://avada.com/element/consent-field/\" target=\"_self\" rel=\"noopener noreferrer\">Avada Consent Field Element</a> — If you&#8217;re using the <a href=\"https://avada.com/feature/form-builder/\" target=\"_self\" rel=\"noopener noreferrer\">Avada Form Builder</a>, just add the Element into your form and write your consent text. Done. There&#8217;s also a legacy method for sites using the contact page template — under the Contact Template tab in global options, enable Display Data Privacy Confirmation Box, and a further option appears to customize the message. But that only applies to the contact page template, and Avada Forms is the far more flexible route.</p>\n<p><a href=\"https://avada.com/element/user-register/\" target=\"_self\" rel=\"noopener noreferrer\">The Avada User Register Element</a> — If people register on your site, this element includes a Registration Notice field near the bottom of its options. It displays custom text before the submit button — a natural spot to inform new users about your GDPR compliance or data handling.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-38 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">Summary</h2></div><div class=\"fusion-text fusion-text-46\"><p>So that&#8217;s the full privacy and consent system in Avada: Global Options, where you define everything once; a configurable bar for site-wide notices; an Element for pages and Avada Off-Canvas pop-ups; and consent fields for your forms and registrations.</p>\n<p>The practical path forward looks like this. Work out your legal requirements first (lawyer, if in doubt). Set your fonts to Local if GDPR applies. Then decide how much of the system you need — a simple bar for a cookies-only site, or the full consent tools if you&#8217;re running third-party embeds and analytics. Define your consent types and categories in the global options, and pick your display method: the bar, the element, or both.</p>\n<p>And when you&#8217;re ready to build out the Element side — whether on a privacy policy page or as a polished Avada Off-Canvas pop-up — the two companion guides linked at the top walk through those builds step by step.</p>\n</div></div></div></div></div>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:66:\"https://avada.com/blog/how-to-manage-website-privacy-consent/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:2;a:6:{s:4:\"data\";s:82:\"\n		\n		\n					\n		\n		\n		\n				\n		\n		\n		\n		\n\n					\n										\n					\n					\n			\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:5:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:63:\"How To Add Privacy &amp; Consent Options to an Avada Off-Canvas\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:81:\"https://avada.com/blog/how-to-add-privacy-consent-options-to-an-avada-off-canvas/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:89:\"https://avada.com/blog/how-to-add-privacy-consent-options-to-an-avada-off-canvas/#respond\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 17 Jun 2026 09:04:30 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:4:{i:0;a:5:{s:4:\"data\";s:5:\"Avada\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:15:\"Beginners Guide\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:2;a:5:{s:4:\"data\";s:8:\"Features\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:3;a:5:{s:4:\"data\";s:9:\"WordPress\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:24:\"https://avada.com/blog//\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:332:\"Here\'s a fact about privacy policy pages: almost nobody visits them. You can place the Avada Privacy and Consent Element on this page (the privacy policy page), but if that\'s your only consent touchpoint, most visitors will never see it. That\'s the problem this setup solves. By placing the Privacy and Consent Element inside an ...\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"michaelb\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:33136:\"<div class=\"fusion-fullwidth fullwidth-box fusion-builder-row-3 fusion-flex-container nonhundred-percent-fullwidth non-hundred-percent-height-scrolling\" style=\"--awb-border-radius-top-left:0px;--awb-border-radius-top-right:0px;--awb-border-radius-bottom-right:0px;--awb-border-radius-bottom-left:0px;--awb-flex-wrap:wrap;\" ><div class=\"fusion-builder-row fusion-row fusion-flex-align-items-flex-start fusion-flex-content-wrap\" style=\"max-width:1331.2px;margin-left: calc(-4% / 2 );margin-right: calc(-4% / 2 );\"><div class=\"fusion-layout-column fusion_builder_column fusion-builder-column-2 fusion_builder_column_1_1 1_1 fusion-flex-column\" style=\"--awb-bg-blend:overlay;--awb-bg-size:cover;--awb-width-large:100%;--awb-margin-top-large:20px;--awb-spacing-right-large:1.92%;--awb-margin-bottom-large:20px;--awb-spacing-left-large:1.92%;--awb-width-medium:100%;--awb-spacing-right-medium:1.92%;--awb-spacing-left-medium:1.92%;--awb-width-small:100%;--awb-spacing-right-small:1.92%;--awb-spacing-left-small:1.92%;\"><div class=\"fusion-column-wrapper fusion-flex-justify-content-flex-start fusion-content-layout-column\"><div class=\"fusion-text fusion-text-47\"><p>Here&#8217;s a fact about privacy policy pages: almost nobody visits them. You can place the <a href=\"https://avada.com/element/privacy-consent/\" target=\"_self\" rel=\"noopener noreferrer\">Avada Privacy and Consent Element</a> on this page (the privacy policy page), but if that&#8217;s your only consent touchpoint, most visitors will never see it.</p>\n<p>That&#8217;s the problem this setup solves. By placing the <a href=\"https://avada.com/documentation/privacy-consent-element/\" target=\"_self\" rel=\"noopener noreferrer\">Privacy and Consent Element</a> inside an Avada Off-Canvas, you bring the consent choice directly to your visitors as soon as they arrive. It&#8217;s flexible, it follows current best practice, and honestly, it&#8217;s one of the cleaner consent implementations you can build with <a href=\"https://avada.com/\" target=\"_self\" rel=\"noopener noreferrer\">Avada</a> and <a href=\"https://wordpress.org/\" target=\"_blank\" rel=\"noopener noreferrer\">WordPress</a>.</p>\n<p>In our previous post, we covered the <a href=\"https://avada.com/blog/how-to-use-the-avada-privacy-consent-element/\" target=\"_self\" rel=\"noopener noreferrer\">general use of the Privacy Element</a>. In this post, we&#8217;ll explore how to build a setup that uses two Avada Off-Canvases working together to manage the Privacy and Consent options. The first is a small pop-up with <strong>&#8220;Accept All&#8221;</strong> and <strong>&#8220;Manage Cookies&#8221;</strong> buttons. The second includes the full Privacy and Consent options for visitors who want to manually choose their cookies (regulations such as the <a href=\"https://gdpr.eu/\" target=\"_blank\" rel=\"noopener noreferrer\">EU&#8217;s GDPR</a> require sites to give you clear choices). Let&#8217;s take a closer look.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-39 fusion-sep-none fusion-title-text fusion-title-size-two awb-exclude-from-toc\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">Overview</h2></div><div class=\"awb-toc-el awb-toc-el--3\" data-awb-toc-id=\"3\" data-awb-toc-options=\"{&quot;allowed_heading_tags&quot;:{&quot;h2&quot;:0,&quot;h3&quot;:1},&quot;ignore_headings&quot;:&quot;.awb-toc-el__list.awb-toc-el__list--0 li:first-child&quot;,&quot;ignore_headings_words&quot;:&quot;&quot;,&quot;enable_cache&quot;:&quot;yes&quot;,&quot;highlight_current_heading&quot;:&quot;no&quot;,&quot;hide_hidden_titles&quot;:&quot;yes&quot;,&quot;limit_container&quot;:&quot;post_content&quot;,&quot;select_custom_headings&quot;:&quot;&quot;,&quot;icon&quot;:&quot;fa-angle-right far&quot;,&quot;counter_type&quot;:&quot;custom_icon&quot;}\" style=\"--awb-item-font-size:var(--awb-typography4-font-size);--awb-item-line-height:var(--awb-typography4-line-height);--awb-item-letter-spacing:var(--awb-typography4-letter-spacing);--awb-item-text-transform:var(--awb-typography4-text-transform);--awb-item-color:var(--awb-color8);--awb-item-color-hover:var(--awb-color5);--awb-item-bg-color-hover:rgba(101,189,125,0);--awb-counter-color:var(--awb-color6);--awb-hover-counter-color:var(--awb-color5);--awb-list-indent:15px;--awb-item-padding-top:3px;--awb-item-padding-right:0;--awb-item-padding-bottom:5px;--awb-item-padding-left:0;--awb-item-font-family:var(--awb-typography4-font-family);--awb-item-font-weight:var(--awb-typography4-font-weight);--awb-item-font-style:var(--awb-typography4-font-style);\"><div class=\"awb-toc-el__content\"></div></div>\n<div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:50px;width:100%;\"></div><div class=\"fusion-title title fusion-title-40 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">Preliminary: Configure The Consent Options</h2></div><div class=\"fusion-text fusion-text-48\"><p>Everything begins in the <a href=\"https://avada.com/documentation/avada-global-options/\" target=\"_self\" rel=\"noopener noreferrer\">Avada Global Options</a>. Head to the <strong>Privacy Consent Tool</strong> section in Avada&#8217;s Privacy and Consent Global Options to set up your consent types and cookie categories. These settings apply to both the <a href=\"https://avada.com/documentation/avada-privacy-consent-bar/\" target=\"_self\" rel=\"noopener noreferrer\">Avada Privacy and Consent Bar</a> and the Privacy and Consent Element, so you only need to configure them once. For this setup, leave the Privacy and Consent Bar turned <strong>“Off”</strong>.</p>\n</div><div class=\"fusion-alert alert custom alert-custom fusion-alert-left awb-alert-inherit-link-color\" style=\"--awb-background-color:#ebfaff;--awb-accent-color:#005272;--awb-border-size:0px;--awb-border-top-left-radius:5px;--awb-border-top-right-radius:5px;--awb-border-bottom-left-radius:5px;--awb-border-bottom-right-radius:5px;\" role=\"alert\"><div class=\"fusion-alert-content-wrapper\"><span class=\"alert-icon\"><i class=\"avada-elements-avada-logo\" aria-hidden=\"true\"></i></span><span class=\"fusion-alert-content\">Avada Dashboard → Options → Global Options → Privacy &amp; Consent</span></div></div><div class=\"fusion-video fusion-youtube\" style=\"--awb-max-width:1280px;--awb-max-height:720px;--awb-align-self:center;--awb-width:100%;\"><div class=\"video-shortcode\"><priv-fac-lite-youtube class=\"fusion-hidden lty-load\" data-privacy-type=\"youtube\" videoid=\"85s0VU46fyc\" class=\"landscape\" params=\"wmode=transparent&autoplay=1&amp;enablejsapi=1\" title=\"How To Use the Avada Privacy &amp; Consent Element in an Off-Canvas\" data-button-label=\"Play Video\" width=\"1280\" height=\"720\" data-thumbnail-size=\"auto\" data-no-cookie=\"on\"></priv-fac-lite-youtube><div class=\"fusion-privacy-placeholder\" style=\"width:1280px; height:720px;\" data-privacy-type=\"youtube\"><div class=\"fusion-privacy-placeholder-content\"><div class=\"fusion-privacy-label\">For privacy reasons YouTube needs your permission to be loaded.</div><button data-privacy-type=\"youtube\" class=\"fusion-button button-default fusion-button-default-size button fusion-privacy-consent\">I Accept</button></div></div></div></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-49\"><p><strong>One quick note on approach:</strong> there&#8217;s no single correct way to implement consent. You could use the bar, the Element on a page, an <a href=\"https://avada.com/documentation/how-to-use-the-off-canvas-builder/\" target=\"_self\" rel=\"noopener noreferrer\">Avada Off-Canvas</a>, or a combination of all three. Best practice simply says visitors need an obvious way to accept the defaults and a real way to make their own selections. This two-pop-up setup delivers both.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-41 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:var(--awb-custom_color_1);--awb-text-color:var(--awb-color8);\">Step 1:</mark> Create the Trigger Off-Canvas</h2></div><div class=\"fusion-text fusion-text-50\"><p>Create a new <a href=\"https://1.envato.market/e4rPJ1\" target=\"_self\" rel=\"noopener noreferrer\">Avada</a> Off-Canvas — we&#8217;ll call it <strong>“Privacy Trigger”</strong>. This is the pop-up every visitor sees first.</p>\n</div><div class=\"fusion-image-element\" style=\"--awb-liftup-border-radius:0px;--awb-caption-title-font-family:var(--h2_typography-font-family);--awb-caption-title-font-weight:var(--h2_typography-font-weight);--awb-caption-title-font-style:var(--h2_typography-font-style);--awb-caption-title-size:var(--h2_typography-font-size);--awb-caption-title-transform:var(--h2_typography-text-transform);--awb-caption-title-line-height:var(--h2_typography-line-height);--awb-caption-title-letter-spacing:var(--h2_typography-letter-spacing);\"><div class=\"awb-image-frame awb-image-frame-8 imageframe-liftup\"><span class=\" fusion-imageframe imageframe-none imageframe-8\" style=\"border:1px solid var(--awb-color2);\"><a href=\"https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-off-canvas-post-manage.jpg\" class=\"fusion-lightbox\" data-rel=\"iLightbox[c0cc2d73088718f9922]\" data-title=\"Avada Privacy Consent Manage Off-Canvas\" title=\"Avada Privacy Consent Manage Off-Canvas\"><img decoding=\"async\" width=\"2000\" height=\"1175\" alt=\"Avada Privacy Consent Manage Off-Canvas\" src=\"https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-off-canvas-post-manage.jpg\" class=\"img-responsive wp-image-897718\" srcset=\"https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-off-canvas-post-manage-200x118.jpg 200w, https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-off-canvas-post-manage-400x235.jpg 400w, https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-off-canvas-post-manage-600x353.jpg 600w, https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-off-canvas-post-manage-800x470.jpg 800w, https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-off-canvas-post-manage-1200x705.jpg 1200w, https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-off-canvas-post-manage.jpg 2000w\" sizes=\"(max-width: 1024px) 100vw, (max-width: 640px) 100vw, 2000px\" /></a></span></div></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-51\"><p>Your Off-Canvas can be a sliding bar or a pop-up, any size and position you like. For this example, use these settings:</p>\n</div><ul style=\"--awb-iconcolor:var(--awb-color8);--awb-line-height:27.2px;--awb-icon-width:27.2px;--awb-icon-height:27.2px;--awb-icon-margin:11.2px;--awb-content-margin:38.4px;\" class=\"fusion-checklist fusion-checklist-5 fusion-checklist-default type-icons\"><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Type</mark> — Pop-up</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Width</mark> &#8211; 600px</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Position</mark> — Centered horizontally, top vertically, with a 100px margin to push it down from the edge</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Conditions</mark> — Entire site</div></li></ul><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-42 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">Configure the Close, Conditions, &amp; Triggers Tabs</h3></div><div class=\"fusion-text fusion-text-52\"><p>In the <strong>Close</strong> tab, turn the close button <strong>“Off”</strong>. This nudges visitors to actually address the cookie question rather than dismiss it. They can still click the overlay to close (which can be disabled), but since that&#8217;s not obvious, most people will use one of the buttons instead.</p>\n<p>In the <strong>Conditions</strong> tab, enable conditions and keep the default of displaying on the <strong>“Entire site”</strong>. On any page, the pop-up appears.</p>\n<p>In the <strong>Triggers</strong> tab, set the trigger to “<strong>Time on Page”</strong> with a duration of 2 seconds. The page loads, the visitor gets a moment to orient themselves, then the pop-up appears.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-43 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">Set the Interaction Behavior</h3></div><div class=\"fusion-text fusion-text-53\"><p>In the <strong>Rules</strong> tab, you&#8217;ll find the <strong>Privacy and Consent Interaction Behavior</strong> option. It has three settings:</p>\n</div><ul style=\"--awb-iconcolor:var(--awb-color8);--awb-line-height:27.2px;--awb-icon-width:27.2px;--awb-icon-height:27.2px;--awb-icon-margin:11.2px;--awb-content-margin:38.4px;\" class=\"fusion-checklist fusion-checklist-6 fusion-checklist-default type-icons\"><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">None</mark> — No special behavior.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Display Until Consented</mark> &#8211; The Off-Canvas opens for visitors who haven&#8217;t saved their consent choices yet. Once they save, it stops appearing.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Display Until Consented &amp; Close Off-Canvas</mark> — Same as above, but it also automatically closes the Off-Canvas once the visitor saves their choices.</div></li></ul><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-54\"><p>Choose <strong>“Display Until Consented and Close Off-Canvas”</strong>. Keep in mind the auto-close part requires a Privacy element on the page with its save action set to Ajax — we&#8217;ll set that in <mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:var(--awb-custom_color_1);--awb-text-color:var(--awb-color8);\">Step 2</mark>.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-44 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">Add The Content</h3></div><div class=\"fusion-text fusion-text-55\"><p>The content here is deliberately simple: a title, a short line of text with a link to more information, and two buttons that do the real work.</p>\n<p><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#276e85;--awb-text-color:var(--awb-color1);\">Button 1</mark>​ — <strong>&#8220;Accept All&#8221;</strong>. Edit the button and set the <strong>Button URL</strong> to <strong>Dynamic Data</strong>, then choose the <strong>Privacy Consent Action of Accept All</strong>. One click, all cookies accepted, visitor moves on. You could instead choose <strong>Save/Update</strong> (which saves the defaults from your global options) or <strong>&#8220;Reject All&#8221;</strong> if you want to offer that.</p>\n<p><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#276e85;--awb-text-color:var(--awb-color1);\">Button 2</mark> — <strong>&#8220;Manage Cookies&#8221;</strong>. This button also uses Avada Dynamic Data, but with the <strong>Open Off-Canvas</strong> option — pointed at the second Off-Canvas we&#8217;re about to build.</p>\n<p><strong>One important detail:</strong> these buttons only work if the Privacy and Consent Element exists somewhere on the page. In this setup, the Element lives in the second Off-Canvas, which means it&#8217;s in the DOM and the buttons function correctly. Skip the second Off-Canvas, and the <strong>“Accept All”</strong> button does nothing.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-45 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:var(--awb-custom_color_1);--awb-text-color:var(--awb-color8);\">Step 2:</mark> Create the Privacy Off-Canvas</h2></div><div class=\"fusion-text fusion-text-56\"><p>Now create the second Avada Off-Canvas — call it <strong>“Privacy”</strong>. This one holds the Privacy and Consent Element content and options.</p>\n</div><div class=\"fusion-image-element\" style=\"--awb-liftup-border-radius:0px;--awb-caption-title-font-family:var(--h2_typography-font-family);--awb-caption-title-font-weight:var(--h2_typography-font-weight);--awb-caption-title-font-style:var(--h2_typography-font-style);--awb-caption-title-size:var(--h2_typography-font-size);--awb-caption-title-transform:var(--h2_typography-text-transform);--awb-caption-title-line-height:var(--h2_typography-line-height);--awb-caption-title-letter-spacing:var(--h2_typography-letter-spacing);\"><div class=\"awb-image-frame awb-image-frame-9 imageframe-liftup\"><span class=\" fusion-imageframe imageframe-none imageframe-9\" style=\"border:1px solid var(--awb-color2);\"><a href=\"https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-off-canvas-post-options.jpg\" class=\"fusion-lightbox\" data-rel=\"iLightbox[3ec1b84e195696e9957]\" data-title=\"Avada Privacy Consent Options Off-Canvas\" title=\"Avada Privacy Consent Options Off-Canvas\"><img decoding=\"async\" width=\"2000\" height=\"1175\" alt=\"Avada Privacy Consent Options Off-Canvas\" src=\"https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-off-canvas-post-options.jpg\" class=\"img-responsive wp-image-897717\" srcset=\"https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-off-canvas-post-options-200x118.jpg 200w, https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-off-canvas-post-options-400x235.jpg 400w, https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-off-canvas-post-options-600x353.jpg 600w, https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-off-canvas-post-options-800x470.jpg 800w, https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-off-canvas-post-options-1200x705.jpg 1200w, https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-off-canvas-post-options.jpg 2000w\" sizes=\"(max-width: 1024px) 100vw, (max-width: 640px) 100vw, 2000px\" /></a></span></div></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-57\"><p>The settings largely mirror the first:</p>\n</div><ul style=\"--awb-iconcolor:var(--awb-color8);--awb-line-height:27.2px;--awb-icon-width:27.2px;--awb-icon-height:27.2px;--awb-icon-margin:11.2px;--awb-content-margin:38.4px;\" class=\"fusion-checklist fusion-checklist-7 fusion-checklist-default type-icons\"><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Width</mark> &#8211; 600px</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Close Tab</mark> — Same settings as the trigger pop-up</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Conditions</mark> — Entire site</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\">\n<mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Triggers</mark> — None — this pop-up only opens when someone clicks <strong>&#8220;Manage Cookies&#8221;</strong> in the first Off-Canvas pop-up</p>\n</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\">\n<mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Rules</mark> — Set the Privacy and Consent Interaction Behavior to <strong>“Display Until Consented and Close Off-Canvas”</strong>, same as before</p>\n</div></li></ul><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-46 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">Add Content to the Privacy Off-Canvas</h3></div><div class=\"fusion-text fusion-text-58\"><p>Add some privacy text at the top, then add the <strong>Privacy and Consent Element</strong>. This is where the configuration differs from that of a privacy policy page, where you&#8217;d typically let the Element spread out. In a <strong>600px</strong> pop-up, you want to be compact. Use these options:</p>\n</div><ul style=\"--awb-iconcolor:var(--awb-color8);--awb-line-height:27.2px;--awb-icon-width:27.2px;--awb-icon-height:27.2px;--awb-icon-margin:11.2px;--awb-content-margin:38.4px;\" class=\"fusion-checklist fusion-checklist-8 fusion-checklist-default type-icons\"><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Layout</mark> — Grouped — Set to <strong>“Stacked”</strong></div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Collapsible Groups</mark> — <strong>“Accordion”</strong> — So only one group can be open at a time</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Collapsed on Load</mark> — <strong>“Enabled”</strong> — Visitors see a tidy list of categories, not a wall of toggles</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\">\n<mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Group Master Toggle</mark> — <strong>“On”</strong> — Each cookie category gets one switch that controls everything inside it</p>\n</div></li></ul><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-59\"><p>The master toggle is smarter than it first appears. It has three positions: <strong>“On”</strong> when all consent types in the category are selected, <strong>“Off”</strong> when none are selected, and “Intermediate” when only some are selected. So if a visitor opens <strong>&#8220;Functional Cookies&#8221;</strong> and deselects YouTube, then opens Statistics and deselects <strong>&#8220;Google Analytics&#8221;</strong>, they&#8217;ll see all three toggle states reflected at a glance.</p>\n<p>Visitors who want detail can expand a group, view individual options, and even read the descriptions. Visitors who don&#8217;t can flip a category switch and be done. Both get served.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-47 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">Set the Save Action to Ajax</h3></div><div class=\"fusion-text fusion-text-60\"><p>Enable all three buttons on the element, and set the <strong>“Save Action”</strong> to <strong>“Ajax”</strong>. As the option description explains, <strong>Ajax</strong> saves the consent client-side, immediately replaces visible consent-gated placeholders, and fires an event — no full-page reload. It&#8217;s also what makes the auto-close behavior from the Rules tab actually work.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-48 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:var(--awb-custom_color_1);--awb-text-color:var(--awb-color8);\">Step 3:</mark> Test It on the Front End</h2></div><div class=\"fusion-text fusion-text-61\"><p>Load any page on your site. After two seconds, the trigger pop-up appears. Click <strong>&#8220;Accept All&#8221;</strong>, and the pop-up closes — consent is saved with every content type enabled. Click <strong>&#8220;Manage Cookies&#8221;</strong> instead, and the second pop-up opens with your accordion of cookie categories.</p>\n<p>Toggle a whole category, or expand groups to decide on individual cookies. Save your choices (or <strong>&#8220;Accept All&#8221;</strong>), and both Off-Canvases close automatically. That&#8217;s the whole flow. Two seconds in, two clicks maximum, and the visitor never sees the pop-up again. It works just as well on mobile, too.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-49 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">Summary</h2></div><div class=\"fusion-text fusion-text-62\"><p>You don&#8217;t strictly need both Off-Canvases. If you&#8217;d rather skip the intro pop-up, you can run the second Off-Canvas on its own — just add a trigger to it (<strong>Time on Page</strong> works well) and let visitors land directly in the full consent panel.</p>\n<p>The two-step version is worth the extra few minutes, though. It gives agreeable visitors a one-click exit while keeping full control one click away for everyone else. And with Avada&#8217;s Privacy and Consent options, you&#8217;ve got the flexibility to build whichever version fits your site.</p>\n</div></div></div></div></div>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:86:\"https://avada.com/blog/how-to-add-privacy-consent-options-to-an-avada-off-canvas/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:3;a:6:{s:4:\"data\";s:79:\"\n		\n		\n					\n		\n		\n		\n				\n		\n		\n		\n\n					\n										\n					\n					\n			\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:5:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:30:\"Version 7.15.5 Security Update\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:54:\"https://avada.com/blog/version-7-15-5-security-update/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:62:\"https://avada.com/blog/version-7-15-5-security-update/#respond\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 15 Jun 2026 14:20:07 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:3:{i:0;a:5:{s:4:\"data\";s:5:\"Avada\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:8:\"Security\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:2;a:5:{s:4:\"data\";s:19:\"Website Maintenance\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:24:\"https://avada.com/blog//\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:358:\"We have released Avada 7.15.5, delivering an array of exciting new features, improvements, and fixing three security issues:  SECURITY: Fixed a possible PHP object injection via post meta. SECURITY: Fixed a possible arbitrary file deletion when deleting custom icon sets. SECURITY: Fixed a possible privilege escalation via post meta using Avada Forms.   ...\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"michaelb\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:6501:\"<div class=\"fusion-fullwidth fullwidth-box fusion-builder-row-4 fusion-flex-container nonhundred-percent-fullwidth non-hundred-percent-height-scrolling\" style=\"--awb-border-radius-top-left:0px;--awb-border-radius-top-right:0px;--awb-border-radius-bottom-right:0px;--awb-border-radius-bottom-left:0px;--awb-flex-wrap:wrap;\" ><div class=\"fusion-builder-row fusion-row fusion-flex-align-items-flex-start fusion-flex-content-wrap\" style=\"max-width:calc( 1280px + 0px );margin-left: calc(-0px / 2 );margin-right: calc(-0px / 2 );\"><div class=\"fusion-layout-column fusion_builder_column fusion-builder-column-3 fusion_builder_column_1_1 1_1 fusion-flex-column\" style=\"--awb-bg-blend:overlay;--awb-bg-size:cover;--awb-width-large:100%;--awb-margin-top-large:20px;--awb-spacing-right-large:0px;--awb-margin-bottom-large:10px;--awb-spacing-left-large:0px;--awb-width-medium:100%;--awb-spacing-right-medium:0px;--awb-spacing-left-medium:0px;--awb-width-small:100%;--awb-spacing-right-small:0px;--awb-spacing-left-small:0px;\"><div class=\"fusion-column-wrapper fusion-flex-justify-content-flex-start fusion-content-layout-column\"><div class=\"fusion-text fusion-text-63\" style=\"--awb-text-transform:none;\"><p>We have released <a href=\"https://avada.com/whats-new/\" target=\"_blank\" rel=\"noopener noreferrer\">Avada 7.15.5</a>, delivering an array of exciting new features, improvements, and fixing three security issues:</p>\n</div><ul style=\"--awb-line-height:27.2px;--awb-icon-width:27.2px;--awb-icon-height:27.2px;--awb-icon-margin:11.2px;--awb-content-margin:38.4px;\" class=\"fusion-checklist fusion-checklist-9 fusion-checklist-default type-icons\"><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-shield-alt fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\">\n<p>SECURITY: Fixed a possible PHP object injection via post meta.</p>\n</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-shield-alt fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\">SECURITY: Fixed a possible arbitrary file deletion when deleting custom icon sets.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-shield-alt fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\">SECURITY: Fixed a possible privilege escalation via post meta using Avada Forms.</div></li></ul><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-64\" style=\"--awb-text-transform:none;\"><p>This is disclosed in our <a href=\"https://avada.com/documentation/avada-changelog\" target=\" _self\" rel=\"noopener noreferrer\">Changelog</a> and our <a href=\"https://avada.com/documentation/important-update-information\" target=\" _self\" rel=\"noopener noreferrer\">Important Update Info</a> help file.</p>\n<p>Like WordPress and any entity that develops software, we understand that security is not absolute and is a continuous process managed as such. We do our best to prevent security issues as proactively as possible, as we do not assume they’ll never come up. Our responsibility is to quickly take care of them and work to get our customers notified and prepared. This is why we recommend keeping your website and plugins up-to-date and maintained at all times.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-50 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">What Should I Do Next?</h2></div><div class=\"fusion-text fusion-text-65\"><p>We cannot stress enough the importance of ensuring that your website is kept up to date and maintained at all times. Please update to ensure that your installation is issue-free and the fix detailed above is applied. These are our detailed update instructions:</p>\n</div><ul style=\"--awb-line-height:27.2px;--awb-icon-width:27.2px;--awb-icon-height:27.2px;--awb-icon-margin:11.2px;--awb-content-margin:38.4px;\" class=\"fusion-checklist fusion-checklist-10 fusion-checklist-default type-icons\"><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-external-link-alt fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><a href=\"https://avada.com/documentation/updating-avada-older-versions/\" target=\"_blank\" rel=\"noopener noreferrer\">Updating from an old version of Avada?</a></div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-external-link-alt fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><a href=\"https://avada.com/documentation/important-update-information/\" target=\"_blank\" rel=\"noopener noreferrer\">Important Update Info</a></div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-external-link-alt fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><a href=\"https://avada.com/documentation/how-to-update-the-avada-website-builder/\" target=\"_blank\" rel=\"noopener noreferrer\">How to Update</a></div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-external-link-alt fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><a href=\"https://avada.com/documentation/avada-patcher/\" target=\"_blank\" rel=\"noopener noreferrer\">Avada Patcher</a></div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-external-link-alt fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><a href=\"https://avada.com/documentation/avada-changelog/\" target=\"_blank\" rel=\"noopener noreferrer\">Avada Changelog</a></div></li></ul>\n<div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-text fusion-text-66\"><p>We would like to extend our gratitude and thanks to Patchstack.</p>\n</div></div></div></div></div>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:59:\"https://avada.com/blog/version-7-15-5-security-update/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:4;a:6:{s:4:\"data\";s:82:\"\n		\n		\n					\n		\n		\n		\n				\n		\n		\n		\n		\n\n					\n										\n					\n					\n			\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:5:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:50:\"How to Use the Avada Privacy &amp; Consent Element\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:68:\"https://avada.com/blog/how-to-use-the-avada-privacy-consent-element/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:76:\"https://avada.com/blog/how-to-use-the-avada-privacy-consent-element/#respond\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 08 Jun 2026 13:43:30 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:4:{i:0;a:5:{s:4:\"data\";s:5:\"Avada\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:15:\"Beginners Guide\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:2;a:5:{s:4:\"data\";s:8:\"Features\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:3;a:5:{s:4:\"data\";s:9:\"WordPress\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:24:\"https://avada.com/blog//\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:353:\"Cookie consent (the permission a website needs to store or access small tracking files (cookies) on your device) is one of those things you have to get right, but nobody actually enjoys setting it up. Regulations like the EU\'s GDPR require sites to give you clear choices—like \"Accept All,\" \"Reject,\" or \"Manage Preferences\"—before tracking your ...\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"michaelb\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:36300:\"<div class=\"fusion-fullwidth fullwidth-box fusion-builder-row-5 fusion-flex-container nonhundred-percent-fullwidth non-hundred-percent-height-scrolling\" style=\"--awb-border-radius-top-left:0px;--awb-border-radius-top-right:0px;--awb-border-radius-bottom-right:0px;--awb-border-radius-bottom-left:0px;--awb-flex-wrap:wrap;\" ><div class=\"fusion-builder-row fusion-row fusion-flex-align-items-flex-start fusion-flex-content-wrap\" style=\"max-width:1331.2px;margin-left: calc(-4% / 2 );margin-right: calc(-4% / 2 );\"><div class=\"fusion-layout-column fusion_builder_column fusion-builder-column-4 fusion_builder_column_1_1 1_1 fusion-flex-column\" style=\"--awb-bg-blend:overlay;--awb-bg-size:cover;--awb-width-large:100%;--awb-margin-top-large:20px;--awb-spacing-right-large:1.92%;--awb-margin-bottom-large:20px;--awb-spacing-left-large:1.92%;--awb-width-medium:100%;--awb-spacing-right-medium:1.92%;--awb-spacing-left-medium:1.92%;--awb-width-small:100%;--awb-spacing-right-small:1.92%;--awb-spacing-left-small:1.92%;\"><div class=\"fusion-column-wrapper fusion-flex-justify-content-flex-start fusion-content-layout-column\"><div class=\"fusion-text fusion-text-67\"><p>Cookie consent (the permission a website needs to store or access small tracking files (cookies) on your device) is one of those things you have to get right, but nobody actually enjoys setting it up. Regulations like the <a href=\"https://gdpr.eu/\" target=\"_blank\" rel=\"noopener noreferrer\">EU&#8217;s GDPR</a> require sites to give you clear choices—like <strong>&#8220;Accept All,&#8221;</strong> <strong>&#8220;Reject,&#8221;</strong> or <strong>&#8220;Manage Preferences&#8221;</strong>—before tracking your online activity or showing personalized ads.</p>\n<p>The good news? If you&#8217;re running <a href=\"https://avada.com/\" target=\"_self\" rel=\"noopener noreferrer\">Avada</a> and <a href=\"https://wordpress.org/\" target=\"_blank\" rel=\"noopener noreferrer\">WordPress</a>, you&#8217;ve already got a proper tool for it baked in. The <a href=\"https://avada.com/element/privacy-consent/\" target=\"_self\" rel=\"noopener noreferrer\">Avada Privacy and Consent Element</a> lets your visitors decide for themselves which embeds and cookies they&#8217;ll allow, right on the page, no third-party plugin required. Here&#8217;s how to set it up and tune it to fit your site.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-51 fusion-sep-none fusion-title-text fusion-title-size-two awb-exclude-from-toc\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">Overview</h2></div><div class=\"awb-toc-el awb-toc-el--4\" data-awb-toc-id=\"4\" data-awb-toc-options=\"{&quot;allowed_heading_tags&quot;:{&quot;h2&quot;:0,&quot;h3&quot;:1},&quot;ignore_headings&quot;:&quot;.awb-toc-el__list.awb-toc-el__list--0 li:first-child&quot;,&quot;ignore_headings_words&quot;:&quot;&quot;,&quot;enable_cache&quot;:&quot;yes&quot;,&quot;highlight_current_heading&quot;:&quot;no&quot;,&quot;hide_hidden_titles&quot;:&quot;yes&quot;,&quot;limit_container&quot;:&quot;post_content&quot;,&quot;select_custom_headings&quot;:&quot;&quot;,&quot;icon&quot;:&quot;fa-angle-right far&quot;,&quot;counter_type&quot;:&quot;custom_icon&quot;}\" style=\"--awb-item-font-size:var(--awb-typography4-font-size);--awb-item-line-height:var(--awb-typography4-line-height);--awb-item-letter-spacing:var(--awb-typography4-letter-spacing);--awb-item-text-transform:var(--awb-typography4-text-transform);--awb-item-color:var(--awb-color8);--awb-item-color-hover:var(--awb-color5);--awb-item-bg-color-hover:rgba(101,189,125,0);--awb-counter-color:var(--awb-color6);--awb-hover-counter-color:var(--awb-color5);--awb-list-indent:15px;--awb-item-padding-top:3px;--awb-item-padding-right:0;--awb-item-padding-bottom:5px;--awb-item-padding-left:0;--awb-item-font-family:var(--awb-typography4-font-family);--awb-item-font-weight:var(--awb-typography4-font-weight);--awb-item-font-style:var(--awb-typography4-font-style);\"><div class=\"awb-toc-el__content\"></div></div>\n<div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:50px;width:100%;\"></div><div class=\"fusion-title title fusion-title-52 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">What This Element Actually Does</h2></div><div class=\"fusion-text fusion-text-68\"><p>The <a href=\"https://avada.com/documentation/privacy-consent-element/\" target=\"_self\" rel=\"noopener noreferrer\">Avada Privacy and Consent Element</a> gives your visitors a list of the cookies your site uses, sorted into the familiar categories: necessary, functional, statistical, and marketing. They tick the ones they&#8217;re happy with, save their choice, and your <a href=\"https://1.envato.market/e4rPJ1\" target=\"_self\" rel=\"noopener noreferrer\">Avada</a> website remembers it.</p>\n</div><div class=\"fusion-video fusion-youtube\" style=\"--awb-max-width:1280px;--awb-max-height:720px;--awb-align-self:center;--awb-width:100%;\"><div class=\"video-shortcode\"><priv-fac-lite-youtube class=\"fusion-hidden lty-load\" data-privacy-type=\"youtube\" videoid=\"1EC4w9sTtT8\" class=\"landscape\" params=\"wmode=transparent&autoplay=1&amp;enablejsapi=1\" title=\"How to Use the Avada Privacy &amp; Consent Element\" data-button-label=\"Play Video\" width=\"1280\" height=\"720\" data-thumbnail-size=\"auto\" data-no-cookie=\"on\"></priv-fac-lite-youtube><div class=\"fusion-privacy-placeholder\" style=\"width:1280px; height:720px;\" data-privacy-type=\"youtube\"><div class=\"fusion-privacy-placeholder-content\"><div class=\"fusion-privacy-label\">For privacy reasons YouTube needs your permission to be loaded.</div><button data-privacy-type=\"youtube\" class=\"fusion-button button-default fusion-button-default-size button fusion-privacy-consent\">I Accept</button></div></div></div></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-69\"><p>It&#8217;s one piece of Avada&#8217;s wider <a href=\"https://avada.com/documentation/how-to-use-the-avada-privacy-consent-tools/\" target=\"_self\" rel=\"noopener noreferrer\">privacy management toolkit</a>, so it works hand in hand with your Avada Global Privacy Settings rather than replacing them.</p>\n<p>Here&#8217;s the gotcha that trips people up: the Element won&#8217;t even show in your Elements list until you enable it.</p>\n<p>Head to <strong>Global Options → Privacy and Consent</strong> and switch on the Privacy Consent option. Save your options, then refresh the page; the Element will now be available to configure in the Avada Builder.</p>\n</div><div class=\"fusion-image-element\" style=\"--awb-liftup-border-radius:0px;--awb-caption-title-font-family:var(--h2_typography-font-family);--awb-caption-title-font-weight:var(--h2_typography-font-weight);--awb-caption-title-font-style:var(--h2_typography-font-style);--awb-caption-title-size:var(--h2_typography-font-size);--awb-caption-title-transform:var(--h2_typography-text-transform);--awb-caption-title-line-height:var(--h2_typography-line-height);--awb-caption-title-letter-spacing:var(--h2_typography-letter-spacing);\"><div class=\"awb-image-frame awb-image-frame-10 imageframe-liftup\"><span class=\" fusion-imageframe imageframe-none imageframe-10\"><a href=\"https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-post-element.png\" class=\"fusion-lightbox\" data-rel=\"iLightbox[a7c5e8869ef74d0386f]\" data-title=\"Avada Privacy &#038; Consent Element\" title=\"Avada Privacy &#038; Consent Element\"><img decoding=\"async\" width=\"1800\" height=\"1065\" alt=\"Avada Privacy &amp; Consent Element\" src=\"https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-post-element.png\" class=\"img-responsive wp-image-897702\" srcset=\"https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-post-element-200x118.png 200w, https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-post-element-400x237.png 400w, https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-post-element-600x355.png 600w, https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-post-element-800x473.png 800w, https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-post-element-1200x710.png 1200w, https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-post-element.png 1800w\" sizes=\"(max-width: 1024px) 100vw, (max-width: 640px) 100vw, 1800px\" /></a></span></div></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-70\"><p>Everything the Element displays — your consent types, which categories are active, descriptions, lifespans — pulls from those <a href=\"https://avada.com/documentation/avada-global-options/\" target=\"_self\" rel=\"noopener noreferrer\">Avada Global Options</a>. So set those up the way you want first, then the Element just reflects them. You can place the Element anywhere on your site, including:</p>\n</div><ul style=\"--awb-iconcolor:var(--awb-custom_color_5);--awb-line-height:27.2px;--awb-icon-width:27.2px;--awb-icon-height:27.2px;--awb-icon-margin:11.2px;--awb-content-margin:38.4px;\" class=\"fusion-checklist fusion-checklist-11 fusion-checklist-default type-icons\"><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-cogs fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><strong>On your website’s privacy policy page</strong> – WordPress even gives you a draft privacy policy page out of the box, which makes a tidy spot for it.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-cogs fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\">\n<p><strong>Inside an Avada Off-Canvas</strong> – More on this below, but this is great if you want a slide-out consent panel instead of a static section.</p>\n</div></li></ul><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-71\"><p>Either way, once it&#8217;s placed, visitors can manage their preferences from there.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-53 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">The Element Options Overview</h2></div><div class=\"fusion-text fusion-text-72\"><p>Add the Element to your website, and you&#8217;ll see it already populated with the global settings you set. Now let&#8217;s go ahead and configure it:</p>\n</div><div class=\"fusion-image-element\" style=\"--awb-liftup-border-radius:0px;--awb-caption-title-font-family:var(--h2_typography-font-family);--awb-caption-title-font-weight:var(--h2_typography-font-weight);--awb-caption-title-font-style:var(--h2_typography-font-style);--awb-caption-title-size:var(--h2_typography-font-size);--awb-caption-title-transform:var(--h2_typography-text-transform);--awb-caption-title-line-height:var(--h2_typography-line-height);--awb-caption-title-letter-spacing:var(--h2_typography-letter-spacing);\"><div class=\"awb-image-frame awb-image-frame-11 imageframe-liftup\"><span class=\" fusion-imageframe imageframe-none imageframe-11\" style=\"border:1px solid var(--awb-color2);\"><a href=\"https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-post-element-options.png\" class=\"fusion-lightbox\" data-rel=\"iLightbox[fdf10eee77c6ea3c89a]\" data-title=\"Avada Privacy &#038; Consent Element Options\" title=\"Avada Privacy &#038; Consent Element Options\"><img decoding=\"async\" width=\"2000\" height=\"1872\" alt=\"Avada Privacy &amp; Consent Element Options\" src=\"https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-post-element-options.png\" class=\"img-responsive wp-image-897703\" srcset=\"https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-post-element-options-200x187.png 200w, https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-post-element-options-400x374.png 400w, https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-post-element-options-600x562.png 600w, https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-post-element-options-800x749.png 800w, https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-post-element-options-1200x1123.png 1200w, https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-post-element-options.png 2000w\" sizes=\"(max-width: 1024px) 100vw, (max-width: 640px) 100vw, 2000px\" /></a></span></div></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-54 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">↳ Privacy text</h3></div><div class=\"fusion-text fusion-text-73\"><p>This is your intro blurb. Write whatever you want here to explain how you handle third-party embeds and cookies. A short, plain sentence does the job.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-55 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">↳ Cookie grouping layout</h3></div><div class=\"fusion-text fusion-text-74\"><p>You can keep a flat list (the default) or switch to <strong>&#8220;Grouped,&#8221;</strong> which sorts cookies by category. After selecting <strong>“Grouped,”</strong> five more controls appear:</p>\n</div><ul style=\"--awb-iconcolor:var(--awb-color8);--awb-line-height:27.2px;--awb-icon-width:27.2px;--awb-icon-height:27.2px;--awb-icon-margin:11.2px;--awb-content-margin:38.4px;\" class=\"fusion-checklist fusion-checklist-12 fusion-checklist-default type-icons\"><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\">\n<mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Group Display</mark> — Stack the groups vertically or lay them out as <strong>Columns</strong>. Choose <strong>Columns</strong>, and you also get a group minimum width and a <strong>Column</strong> gap to fine-tune spacing.</p>\n</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\">\n<mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Visible Cookie Groups</mark> &#8211; This pulls straight from your consent categories. Toggle any group <strong>on</strong> or <strong>off</strong> here. Got custom groups you don&#8217;t want showing? Switch them <strong>off</strong>.</p>\n</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\">\n<mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Show Group Titles</mark> — <strong>“On”</strong> by default. You can also set the HTML tag for the title, so if your page structure needs the group headings to be <strong>H3</strong>, you can make that happen.</p>\n</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Show Group Description</mark> — This displays the category description you wrote in the consent categories area. Only applies to the grouped layout.</div></li></ul><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-56 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">↳ Form field layout</h3></div><div class=\"fusion-text fusion-text-75\"><p>Choose <strong>“Stacked”</strong> or <strong>“Floated”</strong>. You won&#8217;t notice much with the grouped layout, but on a flat list, floated lets shorter items (like your necessary cookies) sit neatly side by side instead of stacking.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-57 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">↳ List WordPress necessary cookies</h3></div><div class=\"fusion-text fusion-text-76\"><p><strong>“On”</strong> by default. You can override it to <strong>“Off”</strong> here if you want.</p>\n</div><div class=\"fusion-alert alert custom alert-custom fusion-alert-left awb-alert-inherit-link-color\" style=\"--awb-background-color:#EBFAFF;--awb-accent-color:#2b4575;--awb-border-size:0px;--awb-border-top-left-radius:5px;--awb-border-top-right-radius:5px;--awb-border-bottom-left-radius:5px;--awb-border-bottom-right-radius:5px;\" role=\"alert\"><div class=\"fusion-alert-content-wrapper\"><span class=\"alert-icon\"><i class=\"fa-plug fal\" aria-hidden=\"true\"></i></span><span class=\"fusion-alert-content\">If the <strong>WooCommerce</strong> or <strong>The Events Calendar</strong> plugins are active, their required cookies are automatically pulled in. Handy, and one less thing to manage manually.</span></div></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-title title fusion-title-58 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">↳ Lifespan and description toggles</h3></div><div class=\"fusion-text fusion-text-77\"><p>If you&#8217;ve enabled cookie lifespan and cookie description in your website’s Avada Global Options, the Element displays them as well. But you can turn either off right here if you&#8217;d rather keep the consent area clean and simple.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-59 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">↳ The buttons</h3></div><div class=\"fusion-text fusion-text-78\"><p>This is where you control the action buttons at the bottom:</p>\n</div><ul style=\"--awb-iconcolor:var(--awb-color8);--awb-line-height:27.2px;--awb-icon-width:27.2px;--awb-icon-height:27.2px;--awb-icon-margin:11.2px;--awb-content-margin:38.4px;\" class=\"fusion-checklist fusion-checklist-13 fusion-checklist-default type-icons\"><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\">\n<mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Show Update Button</mark> — <strong>“On”</strong> by default, with editable button text.</p>\n</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Show Accept All Button</mark> &#8211; Turn it on and you can set its label.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Show Reject All Button</mark> &#8211; Turn it on and you can set its label.</div></li></ul><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-79\"><p>Then there&#8217;s the <strong>Save Action</strong>:</p>\n</div><ul style=\"--awb-iconcolor:var(--awb-color8);--awb-line-height:27.2px;--awb-icon-width:27.2px;--awb-icon-height:27.2px;--awb-icon-margin:11.2px;--awb-content-margin:38.4px;\" class=\"fusion-checklist fusion-checklist-14 fusion-checklist-default type-icons\"><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Reload Page</mark> — Submits the form and reloads so consent-gated content re-renders.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Ajax</mark> &#8211; Saves client-side, swaps placeholders instantly, and fires an event. Use this one when the element lives inside an Avada Off-Canvas.</div></li></ul><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-60 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">↳ Visibility and CSS</h3></div><div class=\"fusion-text fusion-text-80\"><p>Here you&#8217;ll find the usual visibility controls (show or hide by screen size), plus CSS Class and CSS ID fields for further styling customization.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-61 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">The Design Tab</h2></div><div class=\"fusion-text fusion-text-81\"><p>This tab lets you style the Element to best suit your website’s aesthetic. Here you can:</p>\n</div><ul style=\"--awb-iconcolor:var(--awb-custom_color_5);--awb-line-height:27.2px;--awb-icon-width:27.2px;--awb-icon-height:27.2px;--awb-icon-margin:11.2px;--awb-content-margin:38.4px;\" class=\"fusion-checklist fusion-checklist-15 fusion-checklist-default type-icons\"><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-fill-drip fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\">Set margins and padding for the Element.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-fill-drip fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\">Control typography for the group title and main text.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-fill-drip fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\">Adjust the opacity of the necessary cookies — a nice touch that visually signals they can&#8217;t be toggled off.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-fill-drip fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\">Set colors for the cookie lifespan and cookie description, plus a description font size.</div></li></ul><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-82\"><p>A small example: set a bit of bottom margin, point the group title at your subheading typography set, nudge the font back to 18px, and color the lifespan text to match your brand. Little things, but they make the consent area feel like part of your site rather than a bolt-on.</p>\n<p>And don&#8217;t forget the <strong>Extras Tab</strong> for conditional rendering and animation — you can fade the whole thing in from the side if you want a bit of polish.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-62 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">What Visitors Actually See</h2></div><div class=\"fusion-text fusion-text-83\"><p>On the website&#8217;s front end, a visitor chooses the cookies they&#8217;re comfortable with:</p>\n</div><ul style=\"--awb-iconcolor:var(--awb-custom_color_5);--awb-line-height:27.2px;--awb-icon-width:27.2px;--awb-icon-height:27.2px;--awb-icon-margin:11.2px;--awb-content-margin:38.4px;\" class=\"fusion-checklist fusion-checklist-16 fusion-checklist-default type-icons\"><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-cookie fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\">Choose <strong>“Accept All”</strong> or <strong>“Update”</strong>, and their choices are saved to a cookie. Third-party embeds load by default.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-cookie fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\">\n<p>Choose <strong>“Reject All”</strong>, and every checkbox clears, saving the privacy cookie with no consents.</p>\n</div></li></ul><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-84\"><p>Say a visitor deselects YouTube and clicks <strong>“Update”</strong>. The page reloads, they get an update notice, and now any page with a YouTube embed won&#8217;t automatically load that video. Instead, the visitor gets full control over whether to load it, with a link back to your website privacy policy page (set under <strong>Settings → Privacy</strong> in the WordPress Dashboard).</p>\n</div><div class=\"fusion-image-element\" style=\"--awb-caption-title-font-family:var(--h2_typography-font-family);--awb-caption-title-font-weight:var(--h2_typography-font-weight);--awb-caption-title-font-style:var(--h2_typography-font-style);--awb-caption-title-size:var(--h2_typography-font-size);--awb-caption-title-transform:var(--h2_typography-text-transform);--awb-caption-title-line-height:var(--h2_typography-line-height);--awb-caption-title-letter-spacing:var(--h2_typography-letter-spacing);\"><span class=\" fusion-imageframe imageframe-none imageframe-12 hover-type-none\" style=\"border:1px solid var(--awb-color2);\"><a href=\"https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-post-cookie-selection.png\" class=\"fusion-lightbox\" data-rel=\"iLightbox[85ab9cb93c5d521e761]\" data-title=\"Cookie Consent\" title=\"Cookie Consent\"><img decoding=\"async\" width=\"2000\" height=\"1340\" alt=\"Cookie Consent\" src=\"https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-post-cookie-selection.png\" class=\"img-responsive wp-image-897706\" srcset=\"https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-post-cookie-selection-200x134.png 200w, https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-post-cookie-selection-400x268.png 400w, https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-post-cookie-selection-600x402.png 600w, https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-post-cookie-selection-800x536.png 800w, https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-post-cookie-selection-1200x804.png 1200w, https://avada.com/wp-content/uploads/2026/06/avada-privacy-consent-post-cookie-selection.png 2000w\" sizes=\"(max-width: 1024px) 100vw, (max-width: 640px) 100vw, 2000px\" /></a></span></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-85\"><p>Meanwhile, an embed they did approve — a Google Map, say — loads normally, because permission&#8217;s already on file. It&#8217;s granular, and it respects exactly what each person chose.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-63 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">Using it in an Avada Off-Canvas</h2></div><div class=\"fusion-text fusion-text-86\"><p>If you&#8217;d rather have a slide-out consent panel than a section on a page, you can turn off the Privacy and Consent bar and put the Element inside an <a href=\"https://avada.com/feature/off-canvas-builder/\" target=\"_self\" rel=\"noopener noreferrer\">Avada Off-Canvas</a> instead. Set it to load a few seconds after the page does, and it&#8217;ll show the same information in a panel.</p>\n<p>The Avada Off-Canvas options have a Privacy and Consent interaction behavior setting in the rules section, with three choices:</p>\n</div><ul style=\"--awb-iconcolor:var(--awb-color8);--awb-line-height:27.2px;--awb-icon-width:27.2px;--awb-icon-height:27.2px;--awb-icon-margin:11.2px;--awb-content-margin:38.4px;\" class=\"fusion-checklist fusion-checklist-17 fusion-checklist-default type-icons\"><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">None</mark> — No special behavior.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Display Until Consented</mark> &#8211; Opens the Avada Off-Canvas for visitors who haven&#8217;t saved their choices yet. Once they have, it stops opening.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-long-arrow-alt-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Display Until Consent &amp; Close the Off-Canvas</mark> &#8211; Same as above, but auto-closes the panel the moment they save. This one needs your save action set to <strong>“Ajax”</strong>.</p>\n</div></li></ul><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-87\"><p>That last option is the smoothest experience: the visitor consents, the panel quietly slides away, and they get on with their day.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-64 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">Summary</h2></div><div class=\"fusion-text fusion-text-88\"><p>The Privacy and Consent Element is one of those features that looks fiddly until you&#8217;ve clicked through it once; then it just makes sense. Set up your website’s Global Options, drop the Element where it fits, tune the layout, and you&#8217;ve got a consent system that actually respects your visitors&#8217; choices instead of forcing them into clicking <strong>&#8220;Accept.&#8221;</strong></p>\n</div></div></div></div></div>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:73:\"https://avada.com/blog/how-to-use-the-avada-privacy-consent-element/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:5;a:6:{s:4:\"data\";s:82:\"\n		\n		\n					\n		\n		\n		\n				\n		\n		\n		\n		\n\n					\n										\n					\n					\n			\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:5:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:40:\"Your Questions About Avada One, Answered\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:63:\"https://avada.com/blog/your-questions-about-avada-one-answered/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:72:\"https://avada.com/blog/your-questions-about-avada-one-answered/#comments\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 03 Jun 2026 14:37:19 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:4:{i:0;a:5:{s:4:\"data\";s:5:\"Avada\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:9:\"Avada One\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:2;a:5:{s:4:\"data\";s:9:\"Community\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:3;a:5:{s:4:\"data\";s:9:\"WordPress\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:24:\"https://avada.com/blog//\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:319:\"We recently shared the A New Chapter for Avada blog post, introducing Avada One and explaining why our plans changed along the way. Since the announcement, we have spent time reading everything you sent back to us and posted to the Facebook group, etc. The comments, the messages, the long posts, the short ones. We ...\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"michaelb\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:32462:\"<div class=\"fusion-fullwidth fullwidth-box fusion-builder-row-6 fusion-flex-container nonhundred-percent-fullwidth non-hundred-percent-height-scrolling\" style=\"--awb-border-radius-top-left:0px;--awb-border-radius-top-right:0px;--awb-border-radius-bottom-right:0px;--awb-border-radius-bottom-left:0px;--awb-flex-wrap:wrap;\" ><div class=\"fusion-builder-row fusion-row fusion-flex-align-items-flex-start fusion-flex-content-wrap\" style=\"max-width:1331.2px;margin-left: calc(-4% / 2 );margin-right: calc(-4% / 2 );\"><div class=\"fusion-layout-column fusion_builder_column fusion-builder-column-5 fusion_builder_column_1_1 1_1 fusion-flex-column\" style=\"--awb-bg-blend:overlay;--awb-bg-size:cover;--awb-width-large:100%;--awb-margin-top-large:20px;--awb-spacing-right-large:1.92%;--awb-margin-bottom-large:20px;--awb-spacing-left-large:1.92%;--awb-width-medium:100%;--awb-spacing-right-medium:1.92%;--awb-spacing-left-medium:1.92%;--awb-width-small:100%;--awb-spacing-right-small:1.92%;--awb-spacing-left-small:1.92%;\"><div class=\"fusion-column-wrapper fusion-flex-justify-content-flex-start fusion-content-layout-column\"><div class=\"fusion-text fusion-text-89\"><p>We recently shared the <a href=\"https://avada.com/blog/a-new-chapter-for-avada/\" target=\"_self\" rel=\"noopener noreferrer\">A New Chapter for Avada</a> blog post, introducing Avada One and explaining why our plans changed along the way. Since the announcement, we have spent time reading everything you sent back to us and posted to the Facebook group, etc. The comments, the messages, the long posts, the short ones. We have read all of it.</p>\n</div><div class=\"fusion-image-element\" style=\"--awb-caption-title-font-family:var(--h2_typography-font-family);--awb-caption-title-font-weight:var(--h2_typography-font-weight);--awb-caption-title-font-style:var(--h2_typography-font-style);--awb-caption-title-size:var(--h2_typography-font-size);--awb-caption-title-transform:var(--h2_typography-text-transform);--awb-caption-title-line-height:var(--h2_typography-line-height);--awb-caption-title-letter-spacing:var(--h2_typography-letter-spacing);\"><span class=\" fusion-imageframe imageframe-none imageframe-13 hover-type-none\"><img decoding=\"async\" width=\"2000\" height=\"500\" alt=\"Avada One Logo\" title=\"Avada One Logo\" src=\"https://avada.com/wp-content/uploads/2026/05/avada-one-post-logo.png\" class=\"img-responsive wp-image-897682\" srcset=\"https://avada.com/wp-content/uploads/2026/05/avada-one-post-logo-200x50.png 200w, https://avada.com/wp-content/uploads/2026/05/avada-one-post-logo-400x100.png 400w, https://avada.com/wp-content/uploads/2026/05/avada-one-post-logo-600x150.png 600w, https://avada.com/wp-content/uploads/2026/05/avada-one-post-logo-800x200.png 800w, https://avada.com/wp-content/uploads/2026/05/avada-one-post-logo-1200x300.png 1200w, https://avada.com/wp-content/uploads/2026/05/avada-one-post-logo.png 2000w\" sizes=\"(max-width: 1024px) 100vw, (max-width: 640px) 100vw, 2000px\" /></span></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-90\"><p>Some of you are excited. Some of you are worried. Some of you are frustrated, and a few of you are angry. All of those reactions are fair, and we are glad you voiced them. Rather than replying to everyone one by one, we have compiled the most frequently asked questions and concerns and answered them here as plainly as we can. If your question is not covered, it does not mean we missed it, and more answers are coming as things firm up.</p>\n<p>We have created a shortened version with just the quick answers and a longer one, if you want the full reasoning behind them.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-65 fusion-sep-none fusion-title-text fusion-title-size-two awb-exclude-from-toc\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">Overview</h2></div><div class=\"awb-toc-el awb-toc-el--5\" data-awb-toc-id=\"5\" data-awb-toc-options=\"{&quot;allowed_heading_tags&quot;:{&quot;h2&quot;:0,&quot;h3&quot;:1},&quot;ignore_headings&quot;:&quot;.awb-toc-el__list.awb-toc-el__list--0 li:first-child&quot;,&quot;ignore_headings_words&quot;:&quot;&quot;,&quot;enable_cache&quot;:&quot;yes&quot;,&quot;highlight_current_heading&quot;:&quot;no&quot;,&quot;hide_hidden_titles&quot;:&quot;yes&quot;,&quot;limit_container&quot;:&quot;post_content&quot;,&quot;select_custom_headings&quot;:&quot;&quot;,&quot;icon&quot;:&quot;fa-angle-right far&quot;,&quot;counter_type&quot;:&quot;custom_icon&quot;}\" style=\"--awb-item-font-size:var(--awb-typography4-font-size);--awb-item-line-height:var(--awb-typography4-line-height);--awb-item-letter-spacing:var(--awb-typography4-letter-spacing);--awb-item-text-transform:var(--awb-typography4-text-transform);--awb-item-color:var(--awb-color8);--awb-item-color-hover:var(--awb-color5);--awb-item-bg-color-hover:rgba(101,189,125,0);--awb-counter-color:var(--awb-color6);--awb-hover-counter-color:var(--awb-color5);--awb-list-indent:15px;--awb-item-padding-top:3px;--awb-item-padding-right:0;--awb-item-padding-bottom:5px;--awb-item-padding-left:0;--awb-item-font-family:var(--awb-typography4-font-family);--awb-item-font-weight:var(--awb-typography4-font-weight);--awb-item-font-style:var(--awb-typography4-font-style);\"><div class=\"awb-toc-el__content\"></div></div>\n<div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:50px;width:100%;\"></div><div class=\"fusion-title title fusion-title-66 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">The short version</h2></div><ul style=\"--awb-iconcolor:var(--awb-custom_color_5);--awb-line-height:27.2px;--awb-icon-width:27.2px;--awb-icon-height:27.2px;--awb-icon-margin:11.2px;--awb-content-margin:38.4px;\" class=\"fusion-checklist fusion-checklist-18 fusion-checklist-default type-icons\"><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-comment-dots fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><strong>Why a subscription at all?</strong> – Because development never stops, and a one-time payment only funds it once. Product support, ongoing development, and servers that deliver prebuilt content all carry real, continuous costs. A subscription lets us keep building steadily rather than in bursts, and with AI features for customers in the mix, it is genuinely the only model that works. It helps both products last.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-comment-dots fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\">\n<p><strong>If a subscription lapses, does the website break?</strong> – No. The site continues to run exactly as it does today. You stop receiving updates, support, and prebuilt content, but nothing on the live site breaks or gets locked. This is the same thing that happens when you deactivate a purchase code in Avada today.</p>\n</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-comment-dots fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\">\n<p><strong>How does licensing work for agencies and clients?</strong> – One subscription covers a set number of sites, and whoever buys it holds it. No more juggling many separate licenses or the old ThemeForest support extension model. The bundles are designed so that the more sites you cover, the lower the effective cost per site becomes, making the larger tiers very economical for agencies. Everything is managed from one account in My Avada.</p>\n</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-comment-dots fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\">\n<p><strong>Will Avada Classic continue to be developed, or quietly be abandoned?</strong> – It keeps being developed. We are still shipping updates, including a release this week. Classic continues to receive security fixes, bug fixes, and smaller new features, exactly as it has while we have been building the new foundation, which will now be included in Avada One. Avada Classic will receive updated features from Avada One when feasible, and features that are not tied to the new framework we are building. That also makes sure there won’t be breaking changes. It is supported and not going away. If you want the lifetime, one-time option, you still have it.</p>\n</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-comment-dots fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\">\n<p><strong>Is Avada One still WordPress, or a separate platform?</strong> – It is still WordPress. You install it on your own WordPress site, as you always do. At the start, it will feel very close to the Avada you know, and it will diverge over time, but it stays a WordPress product. The word platform refers to the account and management layer on top.</p>\n</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-comment-dots fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\">\n<p><strong>Will existing Avada sites still work, and will my setup carry over?</strong> – Avada Classic remains fully compatible with your current sites, custom CSS, custom scripts, and child themes. If you move a current, up-to-date site to Avada One, it will migrate, though some legacy features will not carry over (to start, the legacy layouts from Global Options). We are building tools to help with that migration.</p>\n</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-comment-dots fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\">\n<p><strong>We voted for performance &amp; mobile, not AI &amp; marketing. What happened?</strong> – Performance is a real priority, and it is a core reason Avada One exists. To be straight with you, fully achieving it requires major foundational changes that couldn&#8217;t be added to the old architecture, which is why we built the new one. You will see improvement in the initial release, but the larger gains come over time as we keep building on that foundation. This is ongoing work, not a finished result on day one. AI and marketing tools are additions on top, not a replacement for the core builder and performance work.</p>\n</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-comment-dots fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\">\n<p><strong>Why not just sell Classic directly on avada.com and skip the subscription?</strong> – ThemeForest has been Avada Classic&#8217;s home for 14 years, and we&#8217;ll keep everything about Avada Classic as you are used to, keeping it right where you have always found it. There is no downside to you either way: Avada Classic remains a one-time purchase, fully supported, exactly as it always has been.</p>\n</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-comment-dots fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\">\n<p><strong>Will existing customers be recognized?</strong> – Yes. Every existing Avada customer gets 50% off the standard single-site plan, with no conditions. If you own more licenses, that same 50% applies to a larger version of the plan covering more sites, matched to how many you own. Prefer the AI-enabled plan instead? You can apply the same recognition there at 25% off. More details below.</p>\n</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-comment-dots fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\">\n<p><strong>What about pricing and timing?</strong> – Full pricing lands closer to launch, once it is final, rather than as numbers; we might still change them. The recognition commitment above is what we are making now. We aim to launch during the summer (August &#8211; September).</p>\n</div></li></ul><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:50px;width:100%;\"></div><div class=\"fusion-title title fusion-title-67 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">Now the longer version</h2></div><div class=\"fusion-title title fusion-title-68 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">&#8220;Why subscription at all? Avada was a one-time purchase.&#8221;</h3></div><div class=\"fusion-text fusion-text-91\"><p>We understand this completely, and we won’t frame a subscription somehow as a gift. It is a change, and for some of you, it might be unwelcome. Nevertheless, there are profound reasons for the change that will also benefit you.</p>\n<p>A one-time purchase pays the team once. Maintaining and improving a platform is never-ending work, and in practice, nobody buys <a href=\"https://avada.com/\" target=\"_self\" rel=\"noopener noreferrer\">Avada</a> once and expects it to stand still. You expect ongoing development, and rightly so. But that creates a mismatch: the money comes in once while the work has to continue for years. A subscription ties the money coming in to the pace of work going out. That is the actual reason, not a marketing line.</p>\n<p>It also helps to be clear that none of this is static or free to run. AI features carry real per-use costs. The servers that deliver prebuilt content cost money to run. Support costs money. Development costs money. Those costs continue every month regardless of when someone bought their license. A subscription aligns with that ongoing reality, and, in particular, AI features are simply not sustainable under a one-time model.</p>\n<p>It is also worth remembering that support was never actually free under the old model. On ThemeForest, ongoing support is a separate paid extension available after purchase. So a subscription that already includes updates and support is not adding a cost that did not exist before. For many people, it bundles together things they were already paying for piece by piece, and once full pricing is public, we think the comparison will look a good deal more reasonable than it might feel in the abstract right now.</p>\n<p>There is a second point worth sitting with. A lifetime updates promise is only as good as the company&#8217;s ability to keep funding them. If we cannot afford to keep building, you still own your lifetime license, but the updates stop anyway. A one-time model quietly carries that risk for everyone. A subscription lets us keep the promise rather than slowly run out of room to keep it, and in the end, that protects both products.</p>\n<p>And to be very clear about what is not happening: nothing is being taken away from you. Classic stays a one-time purchase on ThemeForest. Your existing licenses still work. Your client sites are untouched. Nothing is billed to you retroactively. Avada One is a new, separate product, not your existing Avada placed behind a paywall.</p>\n<p>For the agencies among you, there is a parallel worth pointing out. Many of you have already moved your own clients away from one-off project fees and onto maintenance retainers, for exactly the same reason we are describing here: a living website is ongoing work, and ongoing work is best matched by ongoing, predictable income on both sides. It is the same principle you already apply in your own businesses. And because a subscription is a clean, recurring line item, it slots naturally into the maintenance plans and quotes you already build for clients, much like hosting or a premium plugin, rather than being a cost you have to absorb yourself.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-69 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">&#8220;What actually happens to a client site if the subscription lapses?&#8221;</h3></div><div class=\"fusion-text fusion-text-92\"><p>We saw this fear spreading, sometimes phrased as <em><strong>&#8216;stop paying or your site dies.&#8217;</strong></em> Plain and simple: this is not true. If an Avada One subscription lapses, the live website continues to work. Visitors see it exactly as before.</p>\n<p>What you lose access to is the same set of things you would lose in Avada Classic today if you deactivated a purchase code: product updates, support, and prebuilt content imports. The site itself is not locked or broken. You have a website; it runs, end of story.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-70 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">&#8220;How does licensing actually work for agencies and clients?&#8221;</h3></div><div class=\"fusion-text fusion-text-93\"><p>This came up a lot from those of you managing many sites. Here is how it works:</p>\n<p>The whole idea behind Avada One is a single subscription, not a pile of separate licenses to juggle, and not the old ThemeForest support extension model. If you are an agency, one subscription covers all the site allowances you need. Whoever buys the subscription owns it and holds the account. If you build a site for a client and you want the client to own the subscription, the client buys it and holds the account. If you would rather manage it yourself across all your client work, buy the bundle that fits your number of sites. This is the same way most subscriptions work, including the hosting and premium plugins many of you already pass through to clients.</p>\n<p>The bundles are built so that the cost per site drops steeply as you scale. A larger agency bundle costs only a few dollars per site per year, far less than buying and maintaining individual licenses ever did. So no single client site becomes a burden, and the overall value at scale is greater than before.</p>\n<p>Licenses are not permanently attached to a single site. If you remove Avada One from one website, you can use that slot on another, as long as your total active installs stay within your subscription&#8217;s limit. So moving, retiring, or handing off a site is straightforward.</p>\n<p>For agencies, the new OAuth-based registration and the central Dashboard in My Avada are a real practical gain. You connect a site to your account with a login instead of juggling purchase codes, and you see and manage everything in one place. Updates and site management across many projects become simpler than before. Clean handovers, clear ownership, one screen for many sites.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-71 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">&#8220;Classic is going to die. You will say it won&#8217;t, but it will.&#8221;</h3></div><div class=\"fusion-text fusion-text-94\"><p>This was one of the deepest concerns we saw, and we take it seriously.  Since simple reassurance alone is worth very little, consider our track record with updates. We have always kept Avada up to date, frequently,  and have continued to do so over the past several months, during which we have also been working on Avada One. Another release is going out this week. That is not a goodbye tour. Classic continues to get security fixes, bug fixes, and new features. What is true is that the larger new capabilities, the ones built on the new architecture, will live in Avada One. Classic will receive fewer, smaller feature additions than Avada One. We are not going to pretend otherwise.</p>\n<p>But there is an important difference between smaller and abandoned. Avada Classic has always been a stable, dependable product, and it will continue to be just that. It will keep working with the sites you have already built. So, we won’t let Avada Classic just silently die. There is no reason to be afraid of that. If the lifetime, one-time model is what you want, you still have it, and we will keep supporting it just as we have throughout the time we have been building Avada One.</p>\n<p>There is another angle to consider here. The reason Avada Classic can stay stable is the same reason we built Avada One separately in the first place. Avada One introduces changes deep enough that we cannot guarantee they will leave your existing sites, custom CSS, scripts, and child themes untouched. If we had forced those changes into the product you already use, we would have broken sites. Lots of them. Keeping Classic as its own product is what protects you from that.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-72 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">&#8220;Will existing customers actually be recognized, or is that just a nice sentence?&#8221;</h3></div><div class=\"fusion-text fusion-text-95\"><p>We hinted at this in the first post, and many of you, rightly, wanted something concrete. So here is a real commitment, not a hint. The full plans and pricing come closer to launch, but we wanted you to know the shape of it now.</p>\n<p>Every existing Avada customer gets <strong>50% off the standard single-site plan</strong>: no exceptions, and no conditions on when or how much you bought. If you own Avada, this applies to you.</p>\n<p>If you own more than one license, the same 50% applies to all of them. It unlocks a larger version of that plan, one that covers more sites and is matched to the number of licenses you currently own. The more you have built on Avada over the years, the further your recognition scales. So whether you run a single site or manage hundreds, the offer reflects what you have actually invested in Avada.</p>\n<p>Or, if you would prefer an AI-enabled plan, you can apply the same recognition there instead, at 25% off, matched to your licenses the same way. The discount is smaller only because that plan includes AI credits, which carry a real ongoing cost on our side.</p>\n</div><div class=\"fusion-alert alert custom alert-custom fusion-alert-left awb-alert-inherit-link-color\" style=\"--awb-background-color:#ebfaff;--awb-accent-color:#005272;--awb-border-size:0px;--awb-border-top-left-radius:5px;--awb-border-top-right-radius:5px;--awb-border-bottom-left-radius:5px;--awb-border-bottom-right-radius:5px;\" role=\"alert\"><div class=\"fusion-alert-content-wrapper\"><span class=\"alert-icon\"><i class=\"fa-long-arrow-right fas\" aria-hidden=\"true\"></i></span><span class=\"fusion-alert-content\">You have a choice: <strong>50%</strong> off the standard plan, or <strong>25%</strong> off the AI-enabled plan.</span></div></div><div class=\"fusion-text fusion-text-96\"><p>We will determine your license count using your existing account, so there is nothing for you to dig up or prove manually.</p>\n</div><div class=\"fusion-alert alert custom alert-custom fusion-alert-left awb-alert-inherit-link-color\" style=\"--awb-background-color:#fee2e1;--awb-accent-color:#a02323;--awb-border-size:0px;--awb-border-top-left-radius:5px;--awb-border-top-right-radius:5px;--awb-border-bottom-left-radius:5px;--awb-border-bottom-right-radius:5px;\" role=\"alert\"><div class=\"fusion-alert-content-wrapper\"><span class=\"alert-icon\"><i class=\"fa-exclamation-circle fas\" aria-hidden=\"true\"></i></span><span class=\"fusion-alert-content\">You will have three months from launch day to claim it.</span></div></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-title title fusion-title-73 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">&#8220;We voted for performance and mobile, not AI and marketing.&#8221;</h3></div><div class=\"fusion-text fusion-text-97\"><p>Another fair critique that we want to answer properly. Some of you pointed out that when we asked what mattered most, speed and mobile ranked high, while AI and marketing tools ranked a bit lower, and yet those were part of the headlines.</p>\n<p>Two things. First, performance absolutely is a priority for us, and it is a core reason Avada One exists at all. But here we want to be realistic rather than oversell. Fully achieving the performance we want requires major, foundational changes, the kind that simply could not be bolted onto the old architecture. That is exactly what the new foundation is built to enable. You will see improvement in the initial release, but the bigger gains come progressively as we keep building on that foundation. We would rather tell you plainly that this is ongoing work than have you expect a finished, maximally fast product on day one and feel let down. The point of the new architecture is that the ceiling is much higher, and we can keep pushing toward it over time, rather than hitting the wall the old structure imposed. </p>\n<p>Second, AI and marketing tools are visible headlines because they are new and easy to point at, but they are additions, not a substitute for the core work. They also sit on top of the platform rather than relying on deeper performance changes, so we can ship them without waiting for that foundational work to be fully complete. The core experience, the builder, the performance, and the workflows are still the center of the product. </p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-74 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">&#8220;If I want to move a site to Avada One, will it actually carry over?&#8221;</h3></div><div class=\"fusion-text fusion-text-98\"><p>For sites that are current and using Avada&#8217;s recent tools, yes, you can migrate to Avada One rather than rebuild from scratch. We want to be straight about the limits, though. Because Avada One is built on a new foundation, some legacy features will not carry across. To begin with, that means the legacy layouts from Global Options. It is worth saying that these are not arbitrary removals. Leaving behind older, heavier legacy approaches is part of how the new foundation achieves the performance gains we discussed above. Carrying every old method forward indefinitely is one of the things that held back the previous architecture.</p>\n<p>We are not leaving you to sort this out alone. We are actively building migration tools to help move those pieces across as smoothly as possible. At release, we will provide a definitive list of exactly what does and does not carry over, so there are no surprises, and you can plan with full clarity.</p>\n<p>This is also why keeping your sites up to date matters. The closer a site is to Avada&#8217;s latest building techniques, the smoother any future move will be. That is worth doing for its own sake today, not only as preparation for Avada One.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-75 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">&#8220;Why not just sell Classic directly on avada.com and skip subscription?&#8221;</h3></div><div class=\"fusion-text fusion-text-99\"><p>A few of you asked why we do not sell the one-time Avada Classic directly on our site rather than through ThemeForest. ThemeForest has been Avada Classic&#8217;s home for 14 years, and we are going to keep everything about Avada Classic as you are used to it, right where you have always found it.</p>\n<p>More to the point, this is mostly a question that answers itself: nothing about Avada Classic changes. There is no downside to you either way. It remains the one-time purchase it has always been, in the same place, fully supported, exactly as you know it. The thing that matters to you- that Avada Classic stays available one time and keeps working- is unchanged. </p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-76 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">One last thing</h2></div><div class=\"fusion-text fusion-text-100\"><p>To those of you weighing whether to stay: we hear you, including those who tell us plainly that a subscription is not for you. We are not going to argue you out of how you feel about it. What we will do is make sure Classic remains a genuine, supported home for the work you have already built, and make sure that if you do try Avada One, the terms are fair and the door back is always open.</p>\n<p>Pricing details, launch timing, and more answers will be provided as they become available. Thanks for your feedback. Thanks for your patience.</p>\n</div></div></div></div></div>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:68:\"https://avada.com/blog/your-questions-about-avada-one-answered/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"2\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:6;a:6:{s:4:\"data\";s:79:\"\n		\n		\n					\n		\n		\n		\n				\n		\n		\n		\n\n					\n										\n					\n					\n			\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:5:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:30:\"Version 7.15.4 Security Update\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:54:\"https://avada.com/blog/version-7-15-4-security-update/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:62:\"https://avada.com/blog/version-7-15-4-security-update/#respond\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 02 Jun 2026 13:50:04 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:3:{i:0;a:5:{s:4:\"data\";s:5:\"Avada\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:8:\"Security\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:2;a:5:{s:4:\"data\";s:19:\"Website Maintenance\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:24:\"https://avada.com/blog//\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:379:\"We have released Avada 7.15.4, delivering an array of exciting new features, improvements, and fixing four security issues: SECURITY: Fixed a possible arbitrary file deletion via a form entry value in Avada Forms. SECURITY: Fixed a possible privilege escalation via invalid role assignment in the register action of Avada Forms. SECURITY: Fixed possible PHP object injection ...\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"michaelb\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:6623:\"<div class=\"fusion-fullwidth fullwidth-box fusion-builder-row-7 fusion-flex-container nonhundred-percent-fullwidth non-hundred-percent-height-scrolling\" style=\"--awb-border-radius-top-left:0px;--awb-border-radius-top-right:0px;--awb-border-radius-bottom-right:0px;--awb-border-radius-bottom-left:0px;--awb-flex-wrap:wrap;\" ><div class=\"fusion-builder-row fusion-row fusion-flex-align-items-flex-start fusion-flex-content-wrap\" style=\"max-width:calc( 1280px + 0px );margin-left: calc(-0px / 2 );margin-right: calc(-0px / 2 );\"><div class=\"fusion-layout-column fusion_builder_column fusion-builder-column-6 fusion_builder_column_1_1 1_1 fusion-flex-column\" style=\"--awb-bg-blend:overlay;--awb-bg-size:cover;--awb-width-large:100%;--awb-margin-top-large:20px;--awb-spacing-right-large:0px;--awb-margin-bottom-large:10px;--awb-spacing-left-large:0px;--awb-width-medium:100%;--awb-spacing-right-medium:0px;--awb-spacing-left-medium:0px;--awb-width-small:100%;--awb-spacing-right-small:0px;--awb-spacing-left-small:0px;\"><div class=\"fusion-column-wrapper fusion-flex-justify-content-flex-start fusion-content-layout-column\"><div class=\"fusion-text fusion-text-101\" style=\"--awb-text-transform:none;\"><p>We have released <a href=\"https://avada.com/whats-new/\" target=\"_blank\" rel=\"noopener noreferrer\">Avada 7.15.4</a>, delivering an array of exciting new features, improvements, and&nbsp;fixing four security issues:</p>\n</div><ul style=\"--awb-line-height:27.2px;--awb-icon-width:27.2px;--awb-icon-height:27.2px;--awb-icon-margin:11.2px;--awb-content-margin:38.4px;\" class=\"fusion-checklist fusion-checklist-19 fusion-checklist-default type-icons\"><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-shield-alt fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\">SECURITY: Fixed a possible arbitrary file deletion via a form entry value in Avada Forms.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-shield-alt fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\">SECURITY: Fixed a possible privilege escalation via invalid role assignment in the register action of Avada Forms.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-shield-alt fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\">SECURITY: Fixed possible PHP object injection via live editor preview meta and unrestricted render callback in partial refreshes.</div></li></ul><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-102\" style=\"--awb-text-transform:none;\"><p>This is disclosed in our <a href=\"https://avada.com/documentation/avada-changelog\" target=\" _self\" rel=\"noopener noreferrer\">Changelog</a> and our <a href=\"https://avada.com/documentation/important-update-information\" target=\" _self\" rel=\"noopener noreferrer\">Important Update Info</a> help file.</p>\n<p>Like WordPress and any entity that develops software, we understand that security is not absolute and is a continuous process managed as such. We do our best to prevent security issues as proactively as possible, as we do not assume they’ll never come up. Our responsibility is to quickly take care of them and work to get our customers notified and prepared. This is why we recommend keeping your website and plugins up-to-date and maintained at all times.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-77 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">What Should I Do Next?</h2></div><div class=\"fusion-text fusion-text-103\"><p>We cannot stress enough the importance of ensuring that your website is kept up to date and maintained at all times. Please update to ensure that your installation is issue-free and the fix detailed above is applied. These are our detailed update instructions:</p>\n</div><ul style=\"--awb-line-height:27.2px;--awb-icon-width:27.2px;--awb-icon-height:27.2px;--awb-icon-margin:11.2px;--awb-content-margin:38.4px;\" class=\"fusion-checklist fusion-checklist-20 fusion-checklist-default type-icons\"><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-external-link-alt fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><a href=\"https://avada.com/documentation/updating-avada-older-versions/\" target=\"_blank\" rel=\"noopener noreferrer\">Updating from an old version of Avada?</a></div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-external-link-alt fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><a href=\"https://avada.com/documentation/important-update-information/\" target=\"_blank\" rel=\"noopener noreferrer\">Important Update Info</a></div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-external-link-alt fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><a href=\"https://avada.com/documentation/how-to-update-the-avada-website-builder/\" target=\"_blank\" rel=\"noopener noreferrer\">How to Update</a></div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-external-link-alt fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><a href=\"https://avada.com/documentation/avada-patcher/\" target=\"_blank\" rel=\"noopener noreferrer\">Avada Patcher</a></div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-external-link-alt fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><a href=\"https://avada.com/documentation/avada-changelog/\" target=\"_blank\" rel=\"noopener noreferrer\">Avada Changelog</a></div></li></ul>\n<div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-text fusion-text-104\"><p>We would like to extend our gratitude and thanks to Patchstack and Wordfence.</p>\n</div></div></div></div></div>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:59:\"https://avada.com/blog/version-7-15-4-security-update/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:7;a:6:{s:4:\"data\";s:82:\"\n		\n		\n					\n		\n		\n		\n				\n		\n		\n		\n		\n\n					\n										\n					\n					\n			\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:5:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"A New Chapter for Avada\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:47:\"https://avada.com/blog/a-new-chapter-for-avada/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:55:\"https://avada.com/blog/a-new-chapter-for-avada/#respond\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 28 May 2026 09:26:48 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:4:{i:0;a:5:{s:4:\"data\";s:5:\"Avada\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:9:\"Avada One\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:2;a:5:{s:4:\"data\";s:9:\"Community\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:3;a:5:{s:4:\"data\";s:9:\"WordPress\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:24:\"https://avada.com/blog//\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:316:\"It\'s been a while since our last roadmap update in October 2025, and we know many of you have been wondering what\'s next. Before anything else, we want to acknowledge that directly. The gap in communication has been longer than we would have liked, and longer than you deserved. We understand that silence can be ...\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"michaelb\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:45030:\"<div class=\"fusion-fullwidth fullwidth-box fusion-builder-row-8 fusion-flex-container nonhundred-percent-fullwidth non-hundred-percent-height-scrolling\" style=\"--awb-border-radius-top-left:0px;--awb-border-radius-top-right:0px;--awb-border-radius-bottom-right:0px;--awb-border-radius-bottom-left:0px;--awb-flex-wrap:wrap;\" ><div class=\"fusion-builder-row fusion-row fusion-flex-align-items-flex-start fusion-flex-content-wrap\" style=\"max-width:1331.2px;margin-left: calc(-4% / 2 );margin-right: calc(-4% / 2 );\"><div class=\"fusion-layout-column fusion_builder_column fusion-builder-column-7 fusion_builder_column_1_1 1_1 fusion-flex-column\" style=\"--awb-bg-blend:overlay;--awb-bg-size:cover;--awb-width-large:100%;--awb-margin-top-large:20px;--awb-spacing-right-large:1.92%;--awb-margin-bottom-large:20px;--awb-spacing-left-large:1.92%;--awb-width-medium:100%;--awb-spacing-right-medium:1.92%;--awb-spacing-left-medium:1.92%;--awb-width-small:100%;--awb-spacing-right-small:1.92%;--awb-spacing-left-small:1.92%;\"><div class=\"fusion-column-wrapper fusion-flex-justify-content-flex-start fusion-content-layout-column\"><div class=\"fusion-text fusion-text-105\"><p>It&#8217;s been a while since our last <a href=\"https://avada.com/blog/avada-roadmap-october-2025-progress-update/\" target=\"_self\" rel=\"noopener noreferrer\">roadmap update</a> in October 2025, and we know many of you have been wondering what&#8217;s next. Before anything else, we want to acknowledge that directly. The gap in communication has been longer than we would have liked, and longer than you deserved.</p>\n<p>We understand that silence can be unsettling, especially when you&#8217;re relying on a product for your day-to-day work or waiting on news that matters to your plans. That was not the experience we wanted to give you, and we take responsibility for it.</p>\n<p>While we’ll go into more detail throughout this post, the short version is that we’ve spent the past few months carefully evaluating the future direction of the <a href=\"https://avada.com/\" target=\"_self\" rel=\"noopener noreferrer\">Avada</a> ecosystem and ensuring we take the right long-term path for both our products and our users.</p>\n<p>Part of that process also coincided with significant <a href=\"https://hub.author.envato.com/changes-to-envato-market-revenue-share-and-exclusivity-what-you-need-to-know/\" target=\"_blank\" rel=\"noopener noreferrer\">platform and business-model changes</a> introduced by Envato that directly impact authors and long-term product sustainability. As those changes unfolded, it became increasingly important for us to take the time to evaluate not just the technical roadmap ahead but also how we can continue to deliver the level of innovation, support, and long-term commitment that Avada users expect from us. Because of that, we felt it was important not to rush into further roadmap updates or announcements until we had a clear, confident direction for the platform and the ecosystem as a whole.</p>\n<p>Throughout that time, we know many of you have been eagerly following the progress of what we previously introduced as Avada 8, looking forward to its release and the improvements we&#8217;ve been previewing along the way. We understand this news will land differently depending on what you&#8217;ve been waiting for, and we want to acknowledge that. Whether you&#8217;re excited about what&#8217;s next or you simply rely on Avada every day and want to know it&#8217;s in good hands, we hear you. This post is our honest account of where things stand and where we&#8217;re headed.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-78 fusion-sep-none fusion-title-text fusion-title-size-two awb-exclude-from-toc\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">Overview</h2></div><div class=\"awb-toc-el awb-toc-el--6\" data-awb-toc-id=\"6\" data-awb-toc-options=\"{&quot;allowed_heading_tags&quot;:{&quot;h2&quot;:0,&quot;h3&quot;:1},&quot;ignore_headings&quot;:&quot;.awb-toc-el__list.awb-toc-el__list--0 li:first-child&quot;,&quot;ignore_headings_words&quot;:&quot;&quot;,&quot;enable_cache&quot;:&quot;yes&quot;,&quot;highlight_current_heading&quot;:&quot;no&quot;,&quot;hide_hidden_titles&quot;:&quot;yes&quot;,&quot;limit_container&quot;:&quot;post_content&quot;,&quot;select_custom_headings&quot;:&quot;&quot;,&quot;icon&quot;:&quot;fa-angle-right far&quot;,&quot;counter_type&quot;:&quot;custom_icon&quot;}\" style=\"--awb-item-font-size:var(--awb-typography4-font-size);--awb-item-line-height:var(--awb-typography4-line-height);--awb-item-letter-spacing:var(--awb-typography4-letter-spacing);--awb-item-text-transform:var(--awb-typography4-text-transform);--awb-item-color:var(--awb-color8);--awb-item-color-hover:var(--awb-color5);--awb-item-bg-color-hover:rgba(101,189,125,0);--awb-counter-color:var(--awb-color6);--awb-hover-counter-color:var(--awb-color5);--awb-list-indent:15px;--awb-item-padding-top:3px;--awb-item-padding-right:0;--awb-item-padding-bottom:5px;--awb-item-padding-left:0;--awb-item-font-family:var(--awb-typography4-font-family);--awb-item-font-weight:var(--awb-typography4-font-weight);--awb-item-font-style:var(--awb-typography4-font-style);\"><div class=\"awb-toc-el__content\"></div></div>\n<div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:50px;width:100%;\"></div><div class=\"fusion-title title fusion-title-79 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">The Journey So Far</h2></div><div class=\"fusion-text fusion-text-106\"><p>What started as a new framework steadily evolved into something much broader in scope, and the story of how that happened is worth telling properly.</p>\n</div><div class=\"fusion-image-element\" style=\"--awb-caption-title-font-family:var(--h2_typography-font-family);--awb-caption-title-font-weight:var(--h2_typography-font-weight);--awb-caption-title-font-style:var(--h2_typography-font-style);--awb-caption-title-size:var(--h2_typography-font-size);--awb-caption-title-transform:var(--h2_typography-text-transform);--awb-caption-title-line-height:var(--h2_typography-line-height);--awb-caption-title-letter-spacing:var(--h2_typography-letter-spacing);\"><span class=\" fusion-imageframe imageframe-none imageframe-14 hover-type-none\"><img decoding=\"async\" width=\"2000\" height=\"480\" alt=\"The Avada Journey\" title=\"The Avada Journey\" src=\"https://avada.com/wp-content/uploads/2026/05/avada-one-post-journey-narrow.png\" class=\"img-responsive wp-image-897681\" srcset=\"https://avada.com/wp-content/uploads/2026/05/avada-one-post-journey-narrow-200x48.png 200w, https://avada.com/wp-content/uploads/2026/05/avada-one-post-journey-narrow-400x96.png 400w, https://avada.com/wp-content/uploads/2026/05/avada-one-post-journey-narrow-600x144.png 600w, https://avada.com/wp-content/uploads/2026/05/avada-one-post-journey-narrow-800x192.png 800w, https://avada.com/wp-content/uploads/2026/05/avada-one-post-journey-narrow-1200x288.png 1200w, https://avada.com/wp-content/uploads/2026/05/avada-one-post-journey-narrow.png 2000w\" sizes=\"(max-width: 1024px) 100vw, (max-width: 640px) 100vw, 2000px\" /></span></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-107\"><p>Over the past two years, we&#8217;ve been working intensively on what we initially introduced as Avada 8, a completely reimagined experience with a new UI, improved UX, enhanced performance, and a modernized data structure. Along the way, we&#8217;ve shared glimpses of that journey through our roadmap updates.</p>\n<p>As the project matured, we saw how modern design and development patterns were evolving across the industry. New ways of building, structuring content, and creating workflows were emerging, and the possibilities in web creation were expanding in directions that opened up genuinely exciting opportunities. Rather than lock ourselves into an earlier approach, we deliberately raised the bar.</p>\n<p>That meant revisiting parts of the foundation we had already built, not because the original direction was wrong, but because we saw a better path and wanted to take it. We didn&#8217;t just want to follow those trends. We wanted to implement them in a way that meets the level of quality and refinement you expect from Avada. Doing that properly took time.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-80 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">Scope, Foundation, &amp; the Limits of Backward Compatibility</h2></div><div class=\"fusion-text fusion-text-108\"><p>And as the scope grew, so did the depth of the decisions in front of us. Each time we pushed further into what Avada 8 was becoming, it became clearer that the changes we were making were not just additive. They were foundational. The kind of changes that, if done right, would allow us to build things in the future that would simply not be possible on the architecture we had been working within before. And if done hastily, it would result in exactly the kind of fragmented, patchwork system that creates more problems than it solves.</p>\n<p>At the same time, we made a conscious decision: we didn&#8217;t want to rush out a major release built on partially adapted foundations, only to spend the following months or even years refining, restructuring, or correcting underlying systems. Many of the improvements we had been working on require bigger changes to the core framework and codebase. Without taking the time to implement them properly from the ground up, the result could easily have become a system that limits what we can build on top of it for years to come. Instead, we chose to invest more time upfront to ensure a solid, future-proof foundation.</p>\n<p>As that scope grew, another challenge became increasingly clear. The depth of architectural change we were pursuing pushed hard against the constraints of backward compatibility. Supporting the full weight of the existing Avada structure while simultaneously building something genuinely new created a tension that could not simply be engineered away. At a certain point, trying to do both well meant doing neither well. The more we tried to preserve full compatibility with everything that came before, the more it constrained what we could build for the future.</p>\n<p>Over time, it became clear that the scale of what we were building could not be realistically integrated into the existing Avada product structure without fundamentally altering the experience that many users know, love, and rely on today.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-81 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">Introducing Avada One</h2></div><div class=\"fusion-text fusion-text-109\"><p>With that in mind, as the scope and long-term vision evolved, we recognized that a different approach would ultimately yield the best result for everyone.</p>\n<p>To be direct: Avada 8, as it was originally conceived and communicated, will not be released. What began as Avada 8 grew so significantly in scope and ambition that it outgrew the boundaries of a traditional major version update. Trying to ship it as one would have meant compromising on the very things that made it worth building. We&#8217;re not willing to do that, and we don&#8217;t think you would want us to either.</p>\n<p>Instead, that vision has evolved into something broader: a new, dedicated platform built around a modernized interface, reimagined workflows, improved performance, deeper flexibility, AI-powered capabilities, and an entirely new architectural foundation designed for long-term evolution.</p>\n<p>Rather than trying to force all those changes into the existing Avada product structure, we decided to allow that vision to grow into its own dedicated platform: <strong>Avada One</strong>.</p>\n</div><div class=\"fusion-image-element\" style=\"--awb-caption-title-font-family:var(--h2_typography-font-family);--awb-caption-title-font-weight:var(--h2_typography-font-weight);--awb-caption-title-font-style:var(--h2_typography-font-style);--awb-caption-title-size:var(--h2_typography-font-size);--awb-caption-title-transform:var(--h2_typography-text-transform);--awb-caption-title-line-height:var(--h2_typography-line-height);--awb-caption-title-letter-spacing:var(--h2_typography-letter-spacing);\"><span class=\" fusion-imageframe imageframe-none imageframe-15 hover-type-none\"><img decoding=\"async\" width=\"2000\" height=\"500\" alt=\"Avada One Logo\" title=\"Avada One Logo\" src=\"https://avada.com/wp-content/uploads/2026/05/avada-one-post-logo.png\" class=\"img-responsive wp-image-897682\" srcset=\"https://avada.com/wp-content/uploads/2026/05/avada-one-post-logo-200x50.png 200w, https://avada.com/wp-content/uploads/2026/05/avada-one-post-logo-400x100.png 400w, https://avada.com/wp-content/uploads/2026/05/avada-one-post-logo-600x150.png 600w, https://avada.com/wp-content/uploads/2026/05/avada-one-post-logo-800x200.png 800w, https://avada.com/wp-content/uploads/2026/05/avada-one-post-logo-1200x300.png 1200w, https://avada.com/wp-content/uploads/2026/05/avada-one-post-logo.png 2000w\" sizes=\"(max-width: 1024px) 100vw, (max-width: 640px) 100vw, 2000px\" /></span></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-110\"><p>The name is deliberate. Avada has always been built around the idea of giving website creators everything they need in one place. With <strong>Avada One</strong>, that idea takes on a whole new meaning. One product. One account to connect and manage all your sites. One platform that, over time, will bring together design, content, AI, and marketing capabilities in a way never before possible. Built for everything modern web creation requires, and built to make managing it all significantly simpler.</p>\n<p>That is the foundation we are building toward. And with <strong>Avada One</strong>, we are building it from the ground up.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-82 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">Setting the Stage</h3></div><div class=\"fusion-text fusion-text-111\"><p>Avada One represents the next generation of the Avada experience, built from the ground up on a new architectural foundation and designed around the workflows, expectations, and possibilities of modern web creation. And here we want to set expectations clearly from the start, because we think that matters more than building anticipation.</p>\n<p>Avada One will not arrive as the full product we have been previewing over time. The initial release is a foundation. From that foundation, the experience will grow into something that simply would not have been possible within the current Avada framework. It establishes the new architecture, core systems, and ways of working that everything else will be built on. Much of what you know from Avada will still feel familiar in that first version, and that is intentional. But what is different under the surface matters enormously for where Avada One can go from here, even if not all of that is immediately visible in the early experience.</p>\n<p>From launch, our plan is to move at pace. Regular feature updates will build progressively and bring Avada One closer to the full vision we have been working toward. The destination remains the same as what we have been previewing. The path there is incremental and deliberate, because we believe that is the right way to build something that will genuinely last.</p>\n<p>At the same time, this approach allows us to protect and preserve what many users already love about Avada today. And that distinction is important.</p>\n</div><div class=\"fusion-alert alert custom alert-custom fusion-alert-left awb-alert-inherit-link-color\" style=\"--awb-background-color:#ebfaff;--awb-accent-color:#005272;--awb-border-size:0px;--awb-border-top-left-radius:5px;--awb-border-top-right-radius:5px;--awb-border-bottom-left-radius:5px;--awb-border-bottom-right-radius:5px;\" role=\"alert\"><div class=\"fusion-alert-content-wrapper\"><span class=\"alert-icon\"><i class=\"fa-bullhorn fas\" aria-hidden=\"true\"></i></span><span class=\"fusion-alert-content\">Avada One is a completely separate product from the original Avada. It is not a replacement, and it does not change how existing Avada customers use, manage, or build websites with Avada and WordPress.</span></div></div><div class=\"fusion-text fusion-text-112\"><p>The original Avada will continue to be sold on ThemeForest with the same licensing model, ongoing updates, support, fixes, and continued development. Nothing about your current setup has changed.</p>\n<p>For users who are excited about the future-facing vision we&#8217;ve been building toward, Avada One will open the door to that next-generation experience. For users who love the current Avada experience exactly as it is, that path remains fully supported. You do not need both; each is designed for a different direction, and the choice is entirely yours.</p>\n<p>Avada One will be sold directly through avada.com and will follow a subscription-based model designed to support the long-term sustainability, infrastructure, and ongoing innovation behind the platform.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-83 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">What the Initial Release Includes</h3></div><div class=\"fusion-text fusion-text-113\"><p>While the full scope of the initial release will be shaped by what we can deliver to the standard Avada One deserves, some things are already certain.​</p>\n<p>Starting with something that will make a noticeable difference from day one: Avada One ships as a single, unified package. No more separate Avada Core and Avada Builder plugins to install, manage, or keep in sync. One product, one update, one place to manage everything.</p>\n<p>Product registration is also getting a meaningful overhaul. Instead of managing purchase codes, you will connect your website directly to your My Avada account using a simple OAuth login. From there, you can see and manage all connected sites in one place, making it significantly easier to keep track of your projects and licenses.</p>\n<p>On the design side, Avada One introduces a completely new dashboard experience and a comprehensive overhaul of global color handling across your projects. On the AI side, the platform will include practical, integrated tools for image creation, image adjustment, and text generation, as well as an AI-powered help center to support you as you work.</p>\n<p>These are the starting points. Beyond everything we have already been building toward and previewing as part of the Avada vision, we are also excited to share that marketing and sales tools will be coming to Avada One as a dedicated addition. Bringing those capabilities directly into the platform has been part of our planning alongside the core product, and it is one of the things we are most looking forward to introducing as Avada One grows. <strong>More on that soon.</strong></p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-84 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">Two Products, Two Experiences</h2></div><div class=\"fusion-text fusion-text-114\"><p>The original Avada and Avada One are designed to coexist long-term, serving different needs and different directions:</p>\n</div><ul style=\"--awb-iconcolor:var(--awb-custom_color_5);--awb-line-height:27.2px;--awb-icon-width:27.2px;--awb-icon-height:27.2px;--awb-icon-margin:11.2px;--awb-content-margin:38.4px;\" class=\"fusion-checklist fusion-checklist-21 fusion-checklist-default type-icons\"><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon icon-avada-free-updates\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><strong>Avada Classic</strong> – Focuses on stability, continuity, and the proven experience that existing users know and rely on. That means updates, with new features, maintenance improvements, and security fixes, will be ongoing as usual. There is no plan to change that. </div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon icon-avada-free-updates\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><strong>Avada One</strong> – Focuses on new architecture, modern workflows, and future-facing capabilities, free to evolve without the constraints of maintaining full backward compatibility.</div></li></ul><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-115\"><p>The naming distinction and separation allows both products to grow as intended, without one limiting the other. And it allows you to choose the experience that best fits your workflow, projects, and future needs.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-85 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">What About Compatibility?</h2></div><div class=\"fusion-text fusion-text-116\"><p>We know that one of the first questions many of you will have is how the original Avada and Avada One will work together in practice, especially regarding existing websites, workflows, and long-term compatibility.</p>\n</div><div class=\"fusion-image-element\" style=\"--awb-caption-title-font-family:var(--h2_typography-font-family);--awb-caption-title-font-weight:var(--h2_typography-font-weight);--awb-caption-title-font-style:var(--h2_typography-font-style);--awb-caption-title-size:var(--h2_typography-font-size);--awb-caption-title-transform:var(--h2_typography-text-transform);--awb-caption-title-line-height:var(--h2_typography-line-height);--awb-caption-title-letter-spacing:var(--h2_typography-letter-spacing);\"><span class=\" fusion-imageframe imageframe-none imageframe-16 hover-type-none\"><img decoding=\"async\" width=\"2000\" height=\"500\" alt=\"Avada Compatibility\" title=\"Avada Compatibility\" src=\"https://avada.com/wp-content/uploads/2026/05/avada-one-post-compatibility.png\" class=\"img-responsive wp-image-897677\" srcset=\"https://avada.com/wp-content/uploads/2026/05/avada-one-post-compatibility-200x50.png 200w, https://avada.com/wp-content/uploads/2026/05/avada-one-post-compatibility-400x100.png 400w, https://avada.com/wp-content/uploads/2026/05/avada-one-post-compatibility-600x150.png 600w, https://avada.com/wp-content/uploads/2026/05/avada-one-post-compatibility-800x200.png 800w, https://avada.com/wp-content/uploads/2026/05/avada-one-post-compatibility-1200x300.png 1200w, https://avada.com/wp-content/uploads/2026/05/avada-one-post-compatibility.png 2000w\" sizes=\"(max-width: 1024px) 100vw, (max-width: 640px) 100vw, 2000px\" /></span></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-117\"><p>At the beginning of this journey, Avada One will offer compatibility with current Avada content and workflows, for sites that have kept up with Avada&#8217;s recent updates and are using its current set of tools. If you&#8217;ve been keeping pace with Avada&#8217;s evolution, you&#8217;ll be able to explore and transition smoothly, without having to rebuild or change everything you already have in place.</p>\n<p>If your site relies on older approaches or has not been updated in some time, some content may not carry over directly. This is a good moment to review and modernise your setup, not only to take advantage of what current Avada already offers, but to make any future move to Avada One as straightforward as possible.</p>\n</p>\n<p>At the same time, it&#8217;s important to understand that Avada and Avada One are built on different foundations and will evolve as separate products over time. As Avada One continues to develop independently, a fully seamless long-term upgrade path between the two may become less practical. But that&#8217;s a bridge for the future; there is no requirement or deadline to move, and you can continue using Avada exactly as you do today for as long as you choose.</p>\n<p>And that&#8217;s also what makes this exciting. Avada One is not just a continuation, it&#8217;s the beginning of a new chapter. A platform where we can explore new ideas, introduce new workflows, and build the future of web creation in a more flexible and modern way.</p>\n<p>We want to invite you to be part of that journey from the very beginning. Your feedback, your use cases, and your experience will play a key role in shaping where Avada One goes next.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-86 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">Why Avada One Is Subscription-Based</h2></div><div class=\"fusion-text fusion-text-118\"><p>Avada One will be offered as a subscription-based product, and this decision was not made lightly. It also reflects the realities of recent changes to Envato&#8217;s author ecosystem, as outlined earlier in this post, further reinforcing the need for a sustainable, long-term platform.</p>\n<p>The scale of innovation, infrastructure, AI-powered capabilities, long-term maintenance, and continuous development behind Avada One requires a model different from the traditional one-time licensing structure. Most importantly, this model allows us to build Avada One for the long term and continue investing heavily in development, support, and the platform&#8217;s future.</p>\n</div><div class=\"fusion-image-element\" style=\"--awb-caption-title-font-family:var(--h2_typography-font-family);--awb-caption-title-font-weight:var(--h2_typography-font-weight);--awb-caption-title-font-style:var(--h2_typography-font-style);--awb-caption-title-size:var(--h2_typography-font-size);--awb-caption-title-transform:var(--h2_typography-text-transform);--awb-caption-title-line-height:var(--h2_typography-line-height);--awb-caption-title-letter-spacing:var(--h2_typography-letter-spacing);\"><span class=\" fusion-imageframe imageframe-none imageframe-17 hover-type-none\"><img decoding=\"async\" width=\"2000\" height=\"600\" alt=\"Avada Subscription\" title=\"Avada Subscription\" src=\"https://avada.com/wp-content/uploads/2026/05/avada-one-post-subscription.png\" class=\"img-responsive wp-image-897678\" srcset=\"https://avada.com/wp-content/uploads/2026/05/avada-one-post-subscription-200x60.png 200w, https://avada.com/wp-content/uploads/2026/05/avada-one-post-subscription-400x120.png 400w, https://avada.com/wp-content/uploads/2026/05/avada-one-post-subscription-600x180.png 600w, https://avada.com/wp-content/uploads/2026/05/avada-one-post-subscription-800x240.png 800w, https://avada.com/wp-content/uploads/2026/05/avada-one-post-subscription-1200x360.png 1200w, https://avada.com/wp-content/uploads/2026/05/avada-one-post-subscription.png 2000w\" sizes=\"(max-width: 1024px) 100vw, (max-width: 640px) 100vw, 2000px\" /></span></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-119\"><p>It also gives us the flexibility to offer more scalable, cost-efficient options for agencies, freelancers, and multi-site users, including bundled licensing that makes managing multiple projects significantly easier and more economical.</p>\n<p>In addition, Avada One will be available in different subscription tiers, including options both with and without built-in AI credits, allowing users to choose the setup that best fits their workflow and needs.</p>\n<p>We know pricing and subscription tiers will be top of mind for many of you, along with questions around how access and licensing will work between Avada and Avada One, and whether existing Avada customers will be recognized in some way. What we can say is that we&#8217;re aiming for pricing that reflects the value Avada One delivers while remaining accessible, and structured to feel like a familiar, reasonable step for users who are already part of the Avada ecosystem. Everything is currently being worked through in detail, and we will share full information as soon as we get closer to launch and everything is ready to be communicated properly.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-87 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">When Will Avada One Launch?</h2></div><div class=\"fusion-text fusion-text-120\"><p>Alongside pricing and subscription details, another question we know many of you will have is timing. At this stage, we cannot share a specific release date yet. We can say we aim to launch this summer. Avada One is well underway, with a significant portion of the underlying work and core architecture in place.</p>\n</div><div class=\"fusion-image-element\" style=\"--awb-caption-title-font-family:var(--h2_typography-font-family);--awb-caption-title-font-weight:var(--h2_typography-font-weight);--awb-caption-title-font-style:var(--h2_typography-font-style);--awb-caption-title-size:var(--h2_typography-font-size);--awb-caption-title-transform:var(--h2_typography-text-transform);--awb-caption-title-line-height:var(--h2_typography-line-height);--awb-caption-title-letter-spacing:var(--h2_typography-letter-spacing);\"><span class=\" fusion-imageframe imageframe-none imageframe-18 hover-type-none\"><img decoding=\"async\" width=\"2000\" height=\"500\" alt=\"Avada One Launch\" title=\"Avada One Launch\" src=\"https://avada.com/wp-content/uploads/2026/05/avada-one-post-launch.png\" class=\"img-responsive wp-image-897679\" srcset=\"https://avada.com/wp-content/uploads/2026/05/avada-one-post-launch-200x50.png 200w, https://avada.com/wp-content/uploads/2026/05/avada-one-post-launch-400x100.png 400w, https://avada.com/wp-content/uploads/2026/05/avada-one-post-launch-600x150.png 600w, https://avada.com/wp-content/uploads/2026/05/avada-one-post-launch-800x200.png 800w, https://avada.com/wp-content/uploads/2026/05/avada-one-post-launch-1200x300.png 1200w, https://avada.com/wp-content/uploads/2026/05/avada-one-post-launch.png 2000w\" sizes=\"(max-width: 1024px) 100vw, (max-width: 640px) 100vw, 2000px\" /></span></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-121\"><p>Rather than being an early-stage concept, Avada One is now transitioning into its first release phase. Many parts are already complete, and the current focus is on refining, stabilizing, and bringing everything together into a cohesive first version. From launch, the plan is to move at pace, with regular feature updates that build progressively toward the full experience we have been working toward.</p>\n<p>We are intentionally avoiding committing to a firm date too early to ensure what we announce is something we can fully stand behind. As soon as we are in a position to share a clear launch timeline, we will communicate it directly.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-88 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">Key Takeaways</h2></div><div class=\"fusion-text fusion-text-122\"><p>To help summarize everything covered in this update, here are the most important points:</p>\n</div><ul style=\"--awb-iconcolor:var(--awb-custom_color_5);--awb-line-height:27.2px;--awb-icon-width:27.2px;--awb-icon-height:27.2px;--awb-icon-margin:11.2px;--awb-content-margin:38.4px;\" class=\"fusion-checklist fusion-checklist-22 fusion-checklist-default type-icons\"><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon icon-avada-free-updates\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><strong><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-marker\" style=\"--awb-color:#DAEEFB;--awb-text-color:var(--awb-color8);\">Avada will continue as a core product:</mark></strong> It will remain available on ThemeForest (Envato), fully supported, and continuously updated as part of its established evolution. Nothing changes for existing users.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon icon-avada-free-updates\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><strong><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-marker\" style=\"--awb-color:#DAEEFB;--awb-text-color:var(--awb-color8);\">A new direction has emerged for next-generation development:</mark></strong> What was previously referred to as “Avada 8” grew beyond the scope of a traditional major release. Rather than compromise the foundation, we decided to build something new from the ground up.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon icon-avada-free-updates\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><strong><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-marker\" style=\"--awb-color:#DAEEFB;--awb-text-color:var(--awb-color8);\">Avada One introduces a new, separate product path:</mark></strong> Avada One is a standalone product designed to deliver the next-generation Avada experience, including a new Dashboard foundation, a Global Colors overhaul, and integrated AI tools for image creation, image adjustment, text generation, and in-product help. It ships as a single unified package, with no separate plugins to install or manage, and a new OAuth-based registration system that lets you connect to and monitor all your sites from one account. Marketing and sales tools are also being added as a dedicated feature. Avada One will be sold directly through <a href=\"https://avada.com/\">avada.com</a></div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon icon-avada-free-updates\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><strong><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-marker\" style=\"--awb-color:#DAEEFB;--awb-text-color:var(--awb-color8);\">The initial release is a foundation, not the finished vision:</mark></strong> Avada One will launch as a solid, working platform with a clear direction. From there, regular feature updates will build progressively toward the full experience we have been previewing.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon icon-avada-free-updates\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><strong><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-marker\" style=\"--awb-color:#DAEEFB;--awb-text-color:var(--awb-color8);\">Both products will coexist with different purposes:</mark></strong> Avada Classic focuses on stability, continuity, and familiarity, while Avada One focuses on new architecture, workflows, and future-facing capabilities.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon icon-avada-free-updates\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><strong><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-marker\" style=\"--awb-color:#DAEEFB;--awb-text-color:var(--awb-color8);\">Avada One is not a replacement for Avada Classic:</mark></strong> You do not need both products. Each is designed for a different use case and direction.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon icon-avada-free-updates\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><strong><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-marker\" style=\"--awb-color:#DAEEFB;--awb-text-color:var(--awb-color8);\">Avada One will evolve through incremental releases:</mark></strong> Instead of a single major launch, its full vision will be delivered in steps.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon icon-avada-free-updates\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><strong><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-marker\" style=\"--awb-color:#DAEEFB;--awb-text-color:var(--awb-color8);\">Compatibility will exist initially, but may evolve over time:</mark></strong> Early compatibility will help with transition, but the two platforms may diverge as they develop independently. </div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon icon-avada-free-updates\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><strong><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-marker\" style=\"--awb-color:#DAEEFB;--awb-text-color:var(--awb-color8);\">Avada One will be subscription-based, with flexible tiers:</mark></strong> This enables continued investment in infrastructure and innovation—with options including bundled agency and multi-site licensing, and tiers with and without built-in AI credits. </div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon icon-avada-free-updates\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><strong><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-marker\" style=\"--awb-color:#DAEEFB;--awb-text-color:var(--awb-color8);\">Avada One pricing and tiers are currently being defined:</mark></strong> Designed to reflect its value while remaining accessible and feeling like a natural step for existing Avada users. Full details will be shared closer to launch. </div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon icon-avada-free-updates\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><strong><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-marker\" style=\"--awb-color:#DAEEFB;--awb-text-color:var(--awb-color8);\">A release is targeted for this summer, &amp; development is underway:</mark></strong> Avada One is actively progressing toward its initial release phase, with the current focus on stabilizing and bringing everything together into a cohesive first version. </div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon icon-avada-free-updates\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><strong><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-marker\" style=\"--awb-color:#DAEEFB;--awb-text-color:var(--awb-color8);\">You&#8217;re invited to help shape Avada One:</mark></strong> Early users will play a meaningful role in shaping the platform through real-world use, feedback, and experience. </div></li></ul><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-89 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">The Journey Starts Now</h2></div><div class=\"fusion-text fusion-text-123\"><p>What we are building with Avada One marks the beginning of a new chapter for the Avada ecosystem, not a single release moment, but an ongoing evolution of ideas, workflows, and capabilities that will continue to grow over time.</p>\n<p>We also want to say plainly: we know this journey has asked for a lot of patience from you. The wait has been longer than any of us planned for, and the road has taken turns we didn&#8217;t anticipate. We don&#8217;t take that lightly, and we are committed to showing through our actions going forward that the decisions we&#8217;ve made were made with your long-term experience in mind.</p>\n<p>Avada Classic itself remains exactly as you know it today: a stable, trusted product that continues to receive updates, improvements, and long-term support throughout its lifecycle. And Avada One represents the next generation of thinking, a platform you can grow into at your own pace, when and if it makes sense for you.</p>\n<p>If you choose to explore Avada One when it becomes available, you will be joining us at the very start of that journey, helping shape it through real-world use, feedback, and experience. And if you continue working with Avada Classic as it is today, nothing changes for you.</p>\n<p>Either way, this is not a replacement for what came before. It is an expansion of what is possible. We are looking forward to building this next phase together with you.</p>\n</div></div></div></div></div>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:52:\"https://avada.com/blog/a-new-chapter-for-avada/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:8;a:6:{s:4:\"data\";s:82:\"\n		\n		\n					\n		\n		\n		\n				\n		\n		\n		\n		\n\n					\n										\n					\n					\n			\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:5:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:50:\"How to Use the Avada Live Visual Builder Shortcuts\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:74:\"https://avada.com/blog/how-to-use-the-avada-live-visual-builder-shortcuts/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:82:\"https://avada.com/blog/how-to-use-the-avada-live-visual-builder-shortcuts/#respond\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 25 May 2026 14:46:46 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:4:{i:0;a:5:{s:4:\"data\";s:5:\"Avada\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:15:\"Beginners Guide\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:2;a:5:{s:4:\"data\";s:8:\"Features\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:3;a:5:{s:4:\"data\";s:9:\"WordPress\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:24:\"https://avada.com/blog//\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:304:\"If you\'re building pages using the Avada Live Visual Builder and still reaching for your mouse every time you want to save, preview, or undo something, you\'re leaving real time on the table. Not a huge amount per click, sure. But multiplied across a build? It adds up fast. The good news: Avada has a ...\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"michaelb\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:27858:\"<div class=\"fusion-fullwidth fullwidth-box fusion-builder-row-9 fusion-flex-container nonhundred-percent-fullwidth non-hundred-percent-height-scrolling\" style=\"--awb-border-radius-top-left:0px;--awb-border-radius-top-right:0px;--awb-border-radius-bottom-right:0px;--awb-border-radius-bottom-left:0px;--awb-flex-wrap:wrap;\" ><div class=\"fusion-builder-row fusion-row fusion-flex-align-items-flex-start fusion-flex-content-wrap\" style=\"max-width:1331.2px;margin-left: calc(-4% / 2 );margin-right: calc(-4% / 2 );\"><div class=\"fusion-layout-column fusion_builder_column fusion-builder-column-8 fusion_builder_column_1_1 1_1 fusion-flex-column\" style=\"--awb-bg-blend:overlay;--awb-bg-size:cover;--awb-width-large:100%;--awb-margin-top-large:20px;--awb-spacing-right-large:1.92%;--awb-margin-bottom-large:20px;--awb-spacing-left-large:1.92%;--awb-width-medium:100%;--awb-spacing-right-medium:1.92%;--awb-spacing-left-medium:1.92%;--awb-width-small:100%;--awb-spacing-right-small:1.92%;--awb-spacing-left-small:1.92%;\"><div class=\"fusion-column-wrapper fusion-flex-justify-content-flex-start fusion-content-layout-column\"><div class=\"fusion-text fusion-text-124\"><p>If you&#8217;re building pages using the <a href=\"https://avada.com/feature/live-visual-builder/\" target=\"_self\" rel=\"noopener noreferrer\">Avada Live Visual Builder</a> and still reaching for your mouse every time you want to save, preview, or undo something, you&#8217;re leaving real time on the table. Not a huge amount per click, sure. But multiplied across a build? It adds up fast.</p>\n<p>The good news: <a href=\"https://avada.com/\" target=\"_self\" rel=\"noopener noreferrer\">Avada</a> has a solid set of keyboard shortcuts baked right into the Live Visual Builder. Most people never touch them. You&#8217;re about to be one of the ones who does.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-90 fusion-sep-none fusion-title-text fusion-title-size-two awb-exclude-from-toc\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">Overview</h2></div><div class=\"awb-toc-el awb-toc-el--7\" data-awb-toc-id=\"7\" data-awb-toc-options=\"{&quot;allowed_heading_tags&quot;:{&quot;h2&quot;:0,&quot;h3&quot;:1},&quot;ignore_headings&quot;:&quot;.awb-toc-el__list.awb-toc-el__list--0 li:first-child&quot;,&quot;ignore_headings_words&quot;:&quot;&quot;,&quot;enable_cache&quot;:&quot;yes&quot;,&quot;highlight_current_heading&quot;:&quot;no&quot;,&quot;hide_hidden_titles&quot;:&quot;yes&quot;,&quot;limit_container&quot;:&quot;post_content&quot;,&quot;select_custom_headings&quot;:&quot;&quot;,&quot;icon&quot;:&quot;fa-angle-right far&quot;,&quot;counter_type&quot;:&quot;custom_icon&quot;}\" style=\"--awb-item-font-size:var(--awb-typography4-font-size);--awb-item-line-height:var(--awb-typography4-line-height);--awb-item-letter-spacing:var(--awb-typography4-letter-spacing);--awb-item-text-transform:var(--awb-typography4-text-transform);--awb-item-color:var(--awb-color8);--awb-item-color-hover:var(--awb-color5);--awb-item-bg-color-hover:rgba(101,189,125,0);--awb-counter-color:var(--awb-color6);--awb-hover-counter-color:var(--awb-color5);--awb-list-indent:15px;--awb-item-padding-top:3px;--awb-item-padding-right:0;--awb-item-padding-bottom:5px;--awb-item-padding-left:0;--awb-item-font-family:var(--awb-typography4-font-family);--awb-item-font-weight:var(--awb-typography4-font-weight);--awb-item-font-style:var(--awb-typography4-font-style);\"><div class=\"awb-toc-el__content\"></div></div>\n<div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:50px;width:100%;\"></div><div class=\"fusion-title title fusion-title-91 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">Where to Find the Full List</h2></div><div class=\"fusion-text fusion-text-125\"><p>Before we get into the shortcuts themselves, here&#8217;s the move to use when you inevitably blank on one: In the <a href=\"https://avada.com/documentation/the-avada-live-workspace/\" target=\"_self\" rel=\"noopener noreferrer\">Avada Live Visual Builder</a>, open the toolbar, go to <strong>&#8220;Support&#8221;</strong>, then click <strong>&#8220;Shortcuts&#8221;</strong>. The whole list lives there. Bookmark that in your brain. It&#8217;s the cheat sheet you don&#8217;t have to print.</p>\n</div><div class=\"fusion-video fusion-youtube\" style=\"--awb-max-width:1280px;--awb-max-height:720px;--awb-align-self:center;--awb-width:100%;\"><div class=\"video-shortcode\"><priv-fac-lite-youtube class=\"fusion-hidden lty-load\" data-privacy-type=\"youtube\" videoid=\"EDT3roF-tOY\" class=\"landscape\" params=\"wmode=transparent&autoplay=1&amp;enablejsapi=1\" title=\"How to Use the Avada Live Builder Shortcuts\" data-button-label=\"Play Video\" width=\"1280\" height=\"720\" data-thumbnail-size=\"auto\" data-no-cookie=\"on\"></priv-fac-lite-youtube><div class=\"fusion-privacy-placeholder\" style=\"width:1280px; height:720px;\" data-privacy-type=\"youtube\"><div class=\"fusion-privacy-placeholder-content\"><div class=\"fusion-privacy-label\">For privacy reasons YouTube needs your permission to be loaded.</div><button data-privacy-type=\"youtube\" class=\"fusion-button button-default fusion-button-default-size button fusion-privacy-consent\">I Accept</button></div></div></div></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-alert alert custom alert-custom fusion-alert-left awb-alert-inherit-link-color\" style=\"--awb-background-color:#ebfaff;--awb-accent-color:#005272;--awb-border-size:0px;--awb-border-top-left-radius:5px;--awb-border-top-right-radius:5px;--awb-border-bottom-left-radius:5px;--awb-border-bottom-right-radius:5px;\" role=\"alert\"><div class=\"fusion-alert-content-wrapper\"><span class=\"alert-icon\"><i class=\"avada-elements-avada-logo\" aria-hidden=\"true\"></i></span><span class=\"fusion-alert-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#005272;--awb-text-color:var(--awb-color1);\">Avada Tip:</mark> &#8211; Throughout this post, when you see <strong>Cmd/Ctrl</strong>, use <strong>Cmd</strong> on a Mac and <strong>Ctrl</strong> on Windows. That&#8217;s it. No other translation needed.</p></span></div></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-92 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">The Toggle Shortcuts</h2></div><div class=\"fusion-text fusion-text-126\"><p>These are the shortcuts that change what&#8217;s on your screen, fast. They&#8217;re the gateway to keyboard-driven editing.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-93 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">Open the Command Palette — <mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:var(--awb-custom_color_5);--awb-text-color:var(--awb-color1);\">Cmd/Ctrl + K</mark>​</h3></div><div class=\"fusion-text fusion-text-127\"><p>If you&#8217;re on Avada 7.15.3 or later, you&#8217;ve got the <a href=\"https://avada.com/documentation/how-to-use-the-avada-builder-command-palette/\" target=\"_self\" rel=\"noopener noreferrer\">Avada Command Palette</a>. And honestly, this one shortcut might be the most powerful tool in the builder. <mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#63b8ed;--awb-text-color:var(--awb-color1);\">Cmd/Ctrl + K</mark> opens it instantly. If that combo is already taken by something else on your machine, <strong>F1</strong> also works.</p>\n<p>If you haven&#8217;t already, check out our dedicated <a href=\"https://avada.com/feature/live-visual-builder/\" target=\"_self\" rel=\"noopener noreferrer\">Avada Command Palette post</a>. For now, just know: this is the one to memorize first.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-94 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">Toggle the sidebar — <mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:var(--awb-custom_color_5);--awb-text-color:var(--awb-color1);\">Shift + T</mark>​</h3></div><div class=\"fusion-text fusion-text-128\"><p>Need more breathing room on your canvas? Hit <mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#63b8ed;--awb-text-color:var(--awb-color1);\">Shift + T</mark> and the sidebar gets out of your way. Hit it again, and it&#8217;s back. Great for when you&#8217;re zoomed in on a complex layout and want to see the whole thing.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-95 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">Enter preview mode — <mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:var(--awb-custom_color_5);--awb-text-color:var(--awb-color1);\">Shift + P</mark>​</h3></div><div class=\"fusion-text fusion-text-129\"><p><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#63b8ed;--awb-text-color:var(--awb-color1);\">Shift + P</mark> flips you into preview mode so you can see what the page actually looks like without all the builder chrome. Hit it again to come back to editing.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-96 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">The Action Shortcuts</h2></div><div class=\"fusion-text fusion-text-130\"><p>These are the ones that do things, save, undo, delete, that kind of stuff.</p>\n</div><div class=\"fusion-alert alert custom alert-custom fusion-alert-left awb-alert-inherit-link-color\" style=\"--awb-background-color:#ebfaff;--awb-accent-color:#005272;--awb-border-size:0px;--awb-border-top-left-radius:5px;--awb-border-top-right-radius:5px;--awb-border-bottom-left-radius:5px;--awb-border-bottom-right-radius:5px;\" role=\"alert\"><div class=\"fusion-alert-content-wrapper\"><span class=\"alert-icon\"><i class=\"avada-elements-avada-logo\" aria-hidden=\"true\"></i></span><span class=\"fusion-alert-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#005272;--awb-text-color:var(--awb-color1);\">Avada Tip:</mark> &#8211; If any of these shortcuts aren&#8217;t working, check whether another app on your computer is using the same combo. Clipboard managers, screenshot tools, and browser extensions are usually the culprits. More on that in a sec.</span></div></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-97 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">Save your work — <mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:var(--awb-custom_color_5);--awb-text-color:var(--awb-color1);\">Cmd/Ctrl + S</mark></h3></div><div class=\"fusion-text fusion-text-131\"><p>The single most important shortcut on this list. Use it constantly. Use it after every meaningful change. Your future self will thank you the next time your browser refreshes at the worst possible moment.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-98 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">Save as template — <mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:var(--awb-custom_color_5);--awb-text-color:var(--awb-color1);\">Cmd/Ctrl + Shift + S</mark>​</h3></div><div class=\"fusion-text fusion-text-132\"><p>Built something you want to reuse on another page? <mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#63b8ed;--awb-text-color:var(--awb-color1);\">Cmd/Ctrl + Shift + S</mark> saves your current content as a template. Way faster than digging through menus.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-99 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">Undo and redo — <mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:var(--awb-custom_color_5);--awb-text-color:var(--awb-color1);\">Cmd/Ctrl + Z</mark>​ and <mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:var(--awb-custom_color_5);--awb-text-color:var(--awb-color1);\">Cmd/Ctrl + Y</mark>​</h3></div><div class=\"fusion-text fusion-text-133\"><p>The classics. Undo with <mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#63b8ed;--awb-text-color:var(--awb-color1);\">Cmd/Ctrl + Z</mark>​. Redo with <mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#63b8ed;--awb-text-color:var(--awb-color1);\">Cmd/Ctrl + Y</mark>. If you&#8217;ve ever used a computer, your fingers already know these. Avada just respects what your muscle memory expects.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-100 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">Clear the layout — <mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:var(--awb-custom_color_5);--awb-text-color:var(--awb-color1);\">Cmd/Ctrl + D</mark>​</h3></div><div class=\"fusion-text fusion-text-134\"><p>This one nukes everything on the current layout. Don&#8217;t worry, a confirmation dialog pops up first, so you can&#8217;t accidentally torch an hour of work. But still: handle with respect.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-101 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">Close any open modal — <mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:var(--awb-custom_color_5);--awb-text-color:var(--awb-color1);\">Cmd/Ctrl + Enter</mark></h3></div><div class=\"fusion-text fusion-text-135\"><p>If you&#8217;ve got the Preferences, Shortcuts, or any other modal open, <mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#63b8ed;--awb-text-color:var(--awb-color1);\">Cmd/Ctrl + Enter</mark> closes it. No mouse needed.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-102 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">Open the custom CSS panel — <mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:var(--awb-custom_color_5);--awb-text-color:var(--awb-color1);\">Cmd/Ctrl + Shift + C</mark></h3></div><div class=\"fusion-text fusion-text-136\"><p>If you live in custom CSS, this one will be your best friend. <mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#63b8ed;--awb-text-color:var(--awb-color1);\">Cmd/Ctrl + Shift + C</mark> pops open the page&#8217;s CSS panel directly.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-title title fusion-title-103 fusion-sep-none fusion-title-text fusion-title-size-three\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h3 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:24;line-height:1.33;\">Open the page in the backend builder — <mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:var(--awb-custom_color_5);--awb-text-color:var(--awb-color1);\">Cmd/Ctrl + Q</mark></h3></div><div class=\"fusion-text fusion-text-137\"><p>Need to jump from Live Visual Builder to the Backend Builder (Wireframe mode) for the same page? <mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#63b8ed;--awb-text-color:var(--awb-color1);\">Cmd/Ctrl + Q</mark> opens it in a new tab. Both views, same page, side by side. Useful when you want to compare or work in whichever mode fits the task.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-104 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">The Responsive Preview Shortcuts</h2></div><div class=\"fusion-text fusion-text-138\"><p>This is the section that, once you start using it, you&#8217;ll wonder how you ever worked without.</p>\n</div><ul style=\"--awb-iconcolor:var(--awb-color8);--awb-line-height:27.2px;--awb-icon-width:27.2px;--awb-icon-height:27.2px;--awb-icon-margin:11.2px;--awb-content-margin:38.4px;\" class=\"fusion-checklist fusion-checklist-23 fusion-checklist-default type-icons\"><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-keyboard fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Cmd/Ctrl + 1</mark> → Desktop view</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-keyboard fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Cmd/Ctrl + 2</mark> → Mobile view</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-keyboard fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#282828;--awb-text-color:var(--awb-color1);\">Cmd/Ctrl + 3</mark> → Tablet view</div></li></ul><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-139\"><p>Designing responsive layouts means constantly flipping between screen sizes. Instead of clicking those tiny device icons every single time, just tap a number. You&#8217;ll cycle through views fast enough to actually catch the bugs you&#8217;d otherwise miss.</p>\n</div><div class=\"fusion-alert alert custom alert-custom fusion-alert-left awb-alert-inherit-link-color\" style=\"--awb-background-color:#ebfaff;--awb-accent-color:#005272;--awb-border-size:0px;--awb-border-top-left-radius:5px;--awb-border-top-right-radius:5px;--awb-border-bottom-left-radius:5px;--awb-border-bottom-right-radius:5px;\" role=\"alert\"><div class=\"fusion-alert-content-wrapper\"><span class=\"alert-icon\"><i class=\"avada-elements-avada-logo\" aria-hidden=\"true\"></i></span><span class=\"fusion-alert-content\"><mark class=\"fusion-highlight custom-textcolor highlight1 awb-highlight-background rounded\" style=\"--awb-color:#005272;--awb-text-color:var(--awb-color1);\">Avada Tip:</mark> &#8211; These specific combos (<strong>Cmd/Ctrl + 1/2/3</strong>) are popular with clipboard managers and browser tab-switching tools. If yours are hijacked, try adding Alt to the combo. So <strong>Cmd/Ctrl + Alt + 1</strong>, and so on. Annoying, but the alt-modified version usually slips past whatever&#8217;s intercepting them.</p></span></div></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-105 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">The Gotchas Worth Knowing</h2></div><div class=\"fusion-text fusion-text-140\"><p>A few things that&#8217;ll save you a frustrated Google search later:</p>\n</div><ul style=\"--awb-iconcolor:var(--awb-color6);--awb-line-height:27.2px;--awb-icon-width:27.2px;--awb-icon-height:27.2px;--awb-icon-margin:11.2px;--awb-content-margin:38.4px;\" class=\"fusion-checklist fusion-checklist-24 fusion-checklist-default type-icons\"><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-info-circle far\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\">\n<p><strong>Shortcut conflicts are the #1 reason these &#8220;don&#8217;t work.&#8221;</strong> – Before assuming Avada is broken, check your other apps. Clipboard managers (Raycast, Alfred, Paste), screenshot tools, and even your browser extensions love claiming these key combos.</p>\n</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-info-circle far\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\">\n<p><strong>Mac vs Windows isn&#8217;t just Cmd vs Ctrl</strong>. – On some Windows setups, certain Function keys (like <strong>F1</strong>) are mapped to system actions by default. You may need to hit <strong>Fn + F1</strong> or change your keyboard&#8217;s function key behavior in your OS settings.</p>\n</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-info-circle far\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\">\n<p><strong>You don&#8217;t have to memorize all of them at once.</strong> – Pick three to start. I&#8217;d suggest <strong>Cmd/Ctrl + S</strong> (save), <strong>Cmd/Ctrl + K</strong> (Command Palette), and the responsive trio. Those alone will change how fast you build.</p>\n</div></li></ul><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-106 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">Summary</h2></div><div class=\"fusion-text fusion-text-141\"><p>Keyboard shortcuts only work if you actually use them. Reading this post won&#8217;t make you faster. Using one shortcut ten times a day, every day, for a week — that will.</p>\n<p>So next time you sit down to build a page in Avada Live, pick one shortcut from this list and force yourself to use it instead of clicking. By the end of the week, it&#8217;ll be automatic. Then add another.</p>\n</div></div></div></div></div>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:79:\"https://avada.com/blog/how-to-use-the-avada-live-visual-builder-shortcuts/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:9;a:6:{s:4:\"data\";s:79:\"\n		\n		\n					\n		\n		\n		\n				\n		\n		\n		\n\n					\n										\n					\n					\n			\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:5:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:37:\"The WordPress Media Library Explained\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:61:\"https://avada.com/blog/the-wordpress-media-library-explained/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:69:\"https://avada.com/blog/the-wordpress-media-library-explained/#respond\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 20 May 2026 07:17:50 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:3:{i:0;a:5:{s:4:\"data\";s:9:\"WordPress\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:15:\"Beginners Guide\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:2;a:5:{s:4:\"data\";s:11:\"Setup Guide\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:33:\"http://theme-fusion.com/?p=386710\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:312:\"In this post, we will explore the WordPress Media Library to help you understand where your images and other media files are stored once they are added to your website. We will also look at how you can perform basic editing on your images, including changing their size with the scaling or cropping tools and ...\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"michaelb\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:41246:\"<div class=\"fusion-fullwidth fullwidth-box fusion-builder-row-10 fusion-flex-container nonhundred-percent-fullwidth non-hundred-percent-height-scrolling\" style=\"--awb-border-radius-top-left:0px;--awb-border-radius-top-right:0px;--awb-border-radius-bottom-right:0px;--awb-border-radius-bottom-left:0px;--awb-flex-wrap:wrap;\" ><div class=\"fusion-builder-row fusion-row fusion-flex-align-items-flex-start fusion-flex-content-wrap\" style=\"max-width:1331.2px;margin-left: calc(-4% / 2 );margin-right: calc(-4% / 2 );\"><div class=\"fusion-layout-column fusion_builder_column fusion-builder-column-9 fusion_builder_column_1_1 1_1 fusion-flex-column\" style=\"--awb-bg-blend:overlay;--awb-bg-size:cover;--awb-width-large:100%;--awb-margin-top-large:20px;--awb-spacing-right-large:1.92%;--awb-margin-bottom-large:20px;--awb-spacing-left-large:1.92%;--awb-width-medium:100%;--awb-spacing-right-medium:1.92%;--awb-spacing-left-medium:1.92%;--awb-width-small:100%;--awb-spacing-right-small:1.92%;--awb-spacing-left-small:1.92%;\"><div class=\"fusion-column-wrapper fusion-flex-justify-content-flex-start fusion-content-layout-column\"><div class=\"fusion-text fusion-text-142\"><p>In this post, we will explore the <a href=\"https://wordpress.org/documentation/article/media-library-screen/\" target=\"_blank\" rel=\"noopener noreferrer\">WordPress Media Library</a> to help you understand where your images and other media files are stored once they are added to your website. We will also look at how you can perform basic editing on your images, including changing their size with the scaling or cropping tools and rotating and flipping them. This may be especially helpful once you have gone through the <a href=\"https://avada.com/blog/wordpress-posts-and-pages-explained/\" target=\"_self\" rel=\"noopener noreferrer\">WordPress Pages and Posts</a> post.</p>\n</div><div class=\"fusion-image-element\" style=\"--awb-caption-title-font-family:var(--h2_typography-font-family);--awb-caption-title-font-weight:var(--h2_typography-font-weight);--awb-caption-title-font-style:var(--h2_typography-font-style);--awb-caption-title-size:var(--h2_typography-font-size);--awb-caption-title-transform:var(--h2_typography-text-transform);--awb-caption-title-line-height:var(--h2_typography-line-height);--awb-caption-title-letter-spacing:var(--h2_typography-letter-spacing);\"><span class=\" fusion-imageframe imageframe-none imageframe-19 hover-type-none\"><img decoding=\"async\" width=\"2000\" height=\"500\" alt=\"WordPress Democratize Publishing\" title=\"WordPress Democratize Publishing\" src=\"https://avada.com/wp-content/uploads/2026/03/wordpress-democratize-publishing.png\" class=\"img-responsive wp-image-897499\" srcset=\"https://avada.com/wp-content/uploads/2026/03/wordpress-democratize-publishing-200x50.png 200w, https://avada.com/wp-content/uploads/2026/03/wordpress-democratize-publishing-400x100.png 400w, https://avada.com/wp-content/uploads/2026/03/wordpress-democratize-publishing-600x150.png 600w, https://avada.com/wp-content/uploads/2026/03/wordpress-democratize-publishing-800x200.png 800w, https://avada.com/wp-content/uploads/2026/03/wordpress-democratize-publishing-1200x300.png 1200w, https://avada.com/wp-content/uploads/2026/03/wordpress-democratize-publishing.png 2000w\" sizes=\"(max-width: 1024px) 100vw, (max-width: 640px) 100vw, 2000px\" /></span></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-143\"><p>Finally, we will cover how to add image galleries to your posts and pages. This feature of <a href=\"https://wordpress.org/\" target=\"_blank\" rel=\"noopener noreferrer\">WordPress</a> makes it easy to insert a selection of images into a post and then configure how they are organized.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-107 fusion-sep-none fusion-title-text fusion-title-size-two awb-exclude-from-toc\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">Overview</h2></div><div class=\"awb-toc-el awb-toc-el--8\" data-awb-toc-id=\"8\" data-awb-toc-options=\"{&quot;allowed_heading_tags&quot;:{&quot;h2&quot;:0,&quot;h3&quot;:1},&quot;ignore_headings&quot;:&quot;.awb-toc-el__list.awb-toc-el__list--0 li:first-child&quot;,&quot;ignore_headings_words&quot;:&quot;&quot;,&quot;enable_cache&quot;:&quot;yes&quot;,&quot;highlight_current_heading&quot;:&quot;no&quot;,&quot;hide_hidden_titles&quot;:&quot;yes&quot;,&quot;limit_container&quot;:&quot;post_content&quot;,&quot;select_custom_headings&quot;:&quot;&quot;,&quot;icon&quot;:&quot;fa-angle-right far&quot;,&quot;counter_type&quot;:&quot;custom_icon&quot;}\" style=\"--awb-item-font-size:var(--awb-typography4-font-size);--awb-item-line-height:var(--awb-typography4-line-height);--awb-item-letter-spacing:var(--awb-typography4-letter-spacing);--awb-item-text-transform:var(--awb-typography4-text-transform);--awb-item-color:var(--awb-color8);--awb-item-color-hover:var(--awb-color5);--awb-item-bg-color-hover:rgba(101,189,125,0);--awb-counter-color:var(--awb-color6);--awb-hover-counter-color:var(--awb-color5);--awb-list-indent:15px;--awb-item-padding-top:3px;--awb-item-padding-right:0;--awb-item-padding-bottom:5px;--awb-item-padding-left:0;--awb-item-font-family:var(--awb-typography4-font-family);--awb-item-font-weight:var(--awb-typography4-font-weight);--awb-item-font-style:var(--awb-typography4-font-style);\"><div class=\"awb-toc-el__content\"></div></div>\n<div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:50px;width:100%;\"></div><div class=\"fusion-title title fusion-title-108 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">The WordPress Media Library Explained</h2></div><div class=\"fusion-text fusion-text-144\"><p>Every WordPress website has a media library. Each time you add an image to a post, page, or elsewhere on your website, it is automatically added to the media library. This library of media files, such as images, videos, and audio, can be found under the Media item in the sidebar menu of your WordPress website’s Admin Dashboard.</p>\n</div><div class=\"fusion-image-element\" style=\"text-align:center;--awb-caption-title-font-family:var(--h2_typography-font-family);--awb-caption-title-font-weight:var(--h2_typography-font-weight);--awb-caption-title-font-style:var(--h2_typography-font-style);--awb-caption-title-size:var(--h2_typography-font-size);--awb-caption-title-transform:var(--h2_typography-text-transform);--awb-caption-title-line-height:var(--h2_typography-line-height);--awb-caption-title-letter-spacing:var(--h2_typography-letter-spacing);\"><span class=\" fusion-imageframe imageframe-none imageframe-20 hover-type-none\" style=\"border:1px solid var(--awb-color2);\"><img decoding=\"async\" width=\"2000\" height=\"1345\" alt=\"WordPress Media Library\" title=\"WordPress Media Library\" src=\"https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-library-screen.jpg\" class=\"img-responsive wp-image-894552\" srcset=\"https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-library-screen-200x135.jpg 200w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-library-screen-400x269.jpg 400w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-library-screen-600x404.jpg 600w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-library-screen-800x538.jpg 800w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-library-screen-1200x807.jpg 1200w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-library-screen.jpg 2000w\" sizes=\"(max-width: 1024px) 100vw, (max-width: 640px) 100vw, 2000px\" /></span></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-145\"><p>Once you’ve opened the media library, you can change the view to either a list or grid layout. You can also filter the items by type or date and search the library for specific files.</p>\n</div><div class=\"fusion-image-element\" style=\"text-align:center;--awb-caption-title-font-family:var(--h2_typography-font-family);--awb-caption-title-font-weight:var(--h2_typography-font-weight);--awb-caption-title-font-style:var(--h2_typography-font-style);--awb-caption-title-size:var(--h2_typography-font-size);--awb-caption-title-transform:var(--h2_typography-text-transform);--awb-caption-title-line-height:var(--h2_typography-line-height);--awb-caption-title-letter-spacing:var(--h2_typography-letter-spacing);\"><span class=\" fusion-imageframe imageframe-none imageframe-21 hover-type-none\" style=\"border:1px solid var(--awb-color2);\"><img decoding=\"async\" width=\"2000\" height=\"555\" alt=\"WordPress Media Library Sorting Filter\" title=\"WordPress Media Library Sorting Filter\" src=\"https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-library-filter.jpg\" class=\"img-responsive wp-image-894553\" srcset=\"https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-library-filter-200x56.jpg 200w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-library-filter-400x111.jpg 400w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-library-filter-600x167.jpg 600w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-library-filter-800x222.jpg 800w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-library-filter-1200x333.jpg 1200w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-library-filter.jpg 2000w\" sizes=\"(max-width: 1024px) 100vw, (max-width: 640px) 100vw, 2000px\" /></span></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:50px;width:100%;\"></div><div class=\"fusion-title title fusion-title-109 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">Media Library Attachment Details</h2></div><div class=\"fusion-text fusion-text-146\"><p>Clicking an item in the media library lets you inspect the file and learn more about it. The attachment details screen displays information about the file, including its name, type, upload date, and file size and dimensions.</p>\n</div><div class=\"fusion-image-element\" style=\"text-align:center;--awb-liftup-border-radius:0px;--awb-caption-title-font-family:var(--h2_typography-font-family);--awb-caption-title-font-weight:var(--h2_typography-font-weight);--awb-caption-title-font-style:var(--h2_typography-font-style);--awb-caption-title-size:var(--h2_typography-font-size);--awb-caption-title-transform:var(--h2_typography-text-transform);--awb-caption-title-line-height:var(--h2_typography-line-height);--awb-caption-title-letter-spacing:var(--h2_typography-letter-spacing);\"><div class=\"awb-image-frame awb-image-frame-22 imageframe-liftup\"><span class=\" fusion-imageframe imageframe-none imageframe-22\" style=\"border:1px solid var(--awb-color2);\"><a href=\"https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-attachment-details.jpg\" class=\"fusion-lightbox\" data-rel=\"iLightbox[95e52ef329cb8aa60d0]\" data-title=\"WordPress Media Library Attachment Details\" title=\"WordPress Media Library Attachment Details\"><img decoding=\"async\" width=\"2000\" height=\"1502\" alt=\"WordPress Media Library Attachment Details\" src=\"https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-attachment-details.jpg\" class=\"img-responsive wp-image-894554\" srcset=\"https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-attachment-details-200x150.jpg 200w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-attachment-details-400x300.jpg 400w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-attachment-details-600x451.jpg 600w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-attachment-details-800x601.jpg 800w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-attachment-details-1200x901.jpg 1200w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-attachment-details.jpg 2000w\" sizes=\"(max-width: 1024px) 100vw, (max-width: 640px) 100vw, 2000px\" /></a></span></div></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-147\"><p>You can also see which post the image was uploaded to and where it is being used on your website. The URL field on the attachment details screen displays the direct link to the file. This can be useful if you want to manually link to the media file from one of your posts or pages, or even externally from your website. Examples of this could be in an email or a social media post.</p>\n<p>By default, every image and other media file uploaded to your website has an attachment page. This is a management page that includes the file and some other basic information about it. All changes made to the attachment details will be automatically saved in WordPress. Below is a list of the default settings on the attachment page:</p>\n</div><ul style=\"--awb-line-height:27.2px;--awb-icon-width:27.2px;--awb-icon-height:27.2px;--awb-icon-margin:11.2px;--awb-content-margin:38.4px;\" class=\"fusion-checklist fusion-checklist-25 fusion-checklist-default type-icons\"><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-angle-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><span style=\"color: rgb(87, 87, 87);\"><mark class=\"fusion-highlight light highlight1 awb-highlight-marker\" style=\"--awb-color:var(--awb-color4);\">Uploaded on</mark></span> – The date when the media file was uploaded.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-angle-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight light highlight1 awb-highlight-marker\" style=\"--awb-color:var(--awb-color4);\">Uploaded by</mark> – The author who uploaded the Media.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-angle-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight light highlight1 awb-highlight-marker\" style=\"--awb-color:var(--awb-color4);\">Uploaded to</mark> – Title of the Post or Page that contains this Media. Click on the title to view that Post or Page in an edit Screen. If the Media was unattached to any Post or Page, this line does not appear.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-angle-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight light highlight1 awb-highlight-marker\" style=\"--awb-color:var(--awb-color4);\">File name</mark> – The name of the media file.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-angle-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight light highlight1 awb-highlight-marker\" style=\"--awb-color:var(--awb-color4);\">File type</mark> – The MIME Type of media file.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-angle-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight light highlight1 awb-highlight-marker\" style=\"--awb-color:var(--awb-color4);\">File size</mark> – The file size of the media file.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-angle-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight light highlight1 awb-highlight-marker\" style=\"--awb-color:var(--awb-color4);\">Dimensions</mark> – (Image files only) The dimensions of image media.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-angle-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight light highlight1 awb-highlight-marker\" style=\"--awb-color:var(--awb-color4);\">Alternative Text</mark> – (Image files only) The alt text for the image, e.g., “Mountain View,” to describe the media. This is used for improved accessibility.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-angle-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight light highlight1 awb-highlight-marker\" style=\"--awb-color:var(--awb-color4);\">Title</mark> – The name of the media. A title is often shown on attachment pages and galleries if themes or plugins are designed to display it.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-angle-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight light highlight1 awb-highlight-marker\" style=\"--awb-color:var(--awb-color4);\">Caption</mark> – A brief explanation of the media.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-angle-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight light highlight1 awb-highlight-marker\" style=\"--awb-color:var(--awb-color4);\">Description</mark> – An explanation of this particular media.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-angle-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight light highlight1 awb-highlight-marker\" style=\"--awb-color:var(--awb-color4);\">File URL</mark> – Read-only display of a direct link to the media file.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-angle-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight light highlight1 awb-highlight-marker\" style=\"--awb-color:var(--awb-color4);\">Copy URL to clipboard</mark> – Click to copy the URL of the file into the clipboard.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-angle-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight light highlight1 awb-highlight-marker\" style=\"--awb-color:var(--awb-color4);\">Artist</mark> – (Voice files only) Singer, composer or producer of this media.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-angle-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight light highlight1 awb-highlight-marker\" style=\"--awb-color:var(--awb-color4);\">Album</mark> – (Voice files only) Album title that includes this media.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-angle-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight light highlight1 awb-highlight-marker\" style=\"--awb-color:var(--awb-color4);\">View attachment page</mark> &#8211; Shows the media in a simulated view of how the image would look when displayed in your Theme.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-angle-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight light highlight1 awb-highlight-marker\" style=\"--awb-color:var(--awb-color4);\">Edit more details</mark> &#8211; Displays the Edit Media Screen. See the Edit Media for details on editing Media information.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-angle-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight light highlight1 awb-highlight-marker\" style=\"--awb-color:var(--awb-color4);\">Download file</mark> &#8211; Makes it easier for users to download their uploaded media by providing a download link on the attachment details screen and in the media modal.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-angle-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight light highlight1 awb-highlight-marker\" style=\"--awb-color:var(--awb-color4);\">Delete permanently</mark> &#8211; Deletes the media.</div></li><li class=\"fusion-li-item\" style=\"\"><span class=\"icon-wrapper circle-no\"><i class=\"fusion-li-icon fa-angle-right fal\" aria-hidden=\"true\"></i></span><div class=\"fusion-li-item-content\"><mark class=\"fusion-highlight light highlight1 awb-highlight-marker\" style=\"--awb-color:var(--awb-color4);\">Edit image</mark> &#8211; (Image files only) Allows you to make edits such as rotate, scale, and crop. See the Edit Image Screen.</div></li></ul><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:50px;width:100%;\"></div><div class=\"fusion-title title fusion-title-110 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">Adding Files to the WordPress Media Library</h2></div><div class=\"fusion-text fusion-text-148\"><p>Images or other media files you insert into your posts and pages are automatically added to the media library, and you can also add them directly to the library yourself. You might want to do this if you’d like to make several files available to your co-authors for use in their posts or if you need to link to the files from elsewhere on your site or link to them externally without publishing them in a post.</p>\n<p>Adding the images directly to the media library is very straightforward. You can drag and drop them into place by clicking on the <strong>&#8220;Add New&#8221;</strong> item under the Media sidebar menu. Alternatively, you can click the Select Files button to locate the files on your computer the old-fashioned way. You can select multiple files simultaneously to save time with whichever option you choose.</p>\n</div><div class=\"fusion-image-element\" style=\"text-align:center;--awb-caption-title-font-family:var(--h2_typography-font-family);--awb-caption-title-font-weight:var(--h2_typography-font-weight);--awb-caption-title-font-style:var(--h2_typography-font-style);--awb-caption-title-size:var(--h2_typography-font-size);--awb-caption-title-transform:var(--h2_typography-text-transform);--awb-caption-title-line-height:var(--h2_typography-line-height);--awb-caption-title-letter-spacing:var(--h2_typography-letter-spacing);\"><span class=\" fusion-imageframe imageframe-none imageframe-23 hover-type-none\" style=\"border:1px solid var(--awb-color2);\"><img decoding=\"async\" width=\"2000\" height=\"456\" alt=\"WordPress Upload New Media\" title=\"WordPress Upload New Media\" src=\"https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-upload-media.png\" class=\"img-responsive wp-image-894555\" srcset=\"https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-upload-media-200x46.png 200w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-upload-media-400x91.png 400w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-upload-media-600x137.png 600w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-upload-media-800x182.png 800w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-upload-media-1200x274.png 1200w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-upload-media.png 2000w\" sizes=\"(max-width: 1024px) 100vw, (max-width: 640px) 100vw, 2000px\" /></span></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-149\"><p>Once the files are in the library, they can be edited and inserted into your posts and pages by clicking the Add Media button on the post editor screen.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-111 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">Editing Images in WordPress</h2></div><div class=\"fusion-text fusion-text-150\"><p>When viewing the attachment details page for an image, you will notice, at the bottom, a <strong>&#8220;Edit More Details&#8221;</strong> link. Clicking this button takes you to an <strong>&#8220;Edit&#8221;</strong> option. If you click <strong>&#8220;Edit,&#8221;</strong> you will be presented with options that allow you to make basic changes to the image. The editing features include cropping, scaling, image rotation, and image flipping.</p>\n</div><div class=\"fusion-image-element\" style=\"text-align:center;--awb-liftup-border-radius:0px;--awb-caption-title-font-family:var(--h2_typography-font-family);--awb-caption-title-font-weight:var(--h2_typography-font-weight);--awb-caption-title-font-style:var(--h2_typography-font-style);--awb-caption-title-size:var(--h2_typography-font-size);--awb-caption-title-transform:var(--h2_typography-text-transform);--awb-caption-title-line-height:var(--h2_typography-line-height);--awb-caption-title-letter-spacing:var(--h2_typography-letter-spacing);\"><div class=\"awb-image-frame awb-image-frame-24 imageframe-liftup\"><span class=\" fusion-imageframe imageframe-none imageframe-24\" style=\"border:1px solid var(--awb-color2);\"><a href=\"https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-edit-image.jpg\" class=\"fusion-lightbox\" data-rel=\"iLightbox[fb7a4ae3f7f8db4c546]\" data-title=\"WordPress Basic Image Editing\" title=\"WordPress Basic Image Editing\"><img decoding=\"async\" width=\"2000\" height=\"1248\" alt=\"WordPress Basic Image Editing\" src=\"https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-edit-image.jpg\" class=\"img-responsive wp-image-894556\" srcset=\"https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-edit-image-200x125.jpg 200w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-edit-image-400x250.jpg 400w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-edit-image-600x374.jpg 600w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-edit-image-800x499.jpg 800w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-edit-image-1200x749.jpg 1200w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-edit-image.jpg 2000w\" sizes=\"(max-width: 1024px) 100vw, (max-width: 640px) 100vw, 2000px\" /></a></span></div></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-151\"><p>However, you can also scale an image proportionally to reduce its dimensions while maintaining its aspect ratio. Furthermore, you can also crop an image by dragging the cursor over it to make a selection. This allows you to select the area to keep, with the rest of the image discarded.</p>\n</div><div class=\"fusion-image-element\" style=\"text-align:center;--awb-liftup-border-radius:0px;--awb-caption-title-font-family:var(--h2_typography-font-family);--awb-caption-title-font-weight:var(--h2_typography-font-weight);--awb-caption-title-font-style:var(--h2_typography-font-style);--awb-caption-title-size:var(--h2_typography-font-size);--awb-caption-title-transform:var(--h2_typography-text-transform);--awb-caption-title-line-height:var(--h2_typography-line-height);--awb-caption-title-letter-spacing:var(--h2_typography-letter-spacing);\"><div class=\"awb-image-frame awb-image-frame-25 imageframe-liftup\"><span class=\" fusion-imageframe imageframe-none imageframe-25\" style=\"border:1px solid var(--awb-color2);\"><a href=\"https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-edit-image-scale.jpg\" class=\"fusion-lightbox\" data-rel=\"iLightbox[ad059906aca4a611273]\" data-title=\"WordPress Scale Image\" title=\"WordPress Scale Image\"><img decoding=\"async\" width=\"2000\" height=\"1247\" alt=\"WordPress Scale Image\" src=\"https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-edit-image-scale.jpg\" class=\"img-responsive wp-image-894557\" srcset=\"https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-edit-image-scale-200x125.jpg 200w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-edit-image-scale-400x249.jpg 400w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-edit-image-scale-600x374.jpg 600w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-edit-image-scale-800x499.jpg 800w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-edit-image-scale-1200x748.jpg 1200w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-edit-image-scale.jpg 2000w\" sizes=\"(max-width: 1024px) 100vw, (max-width: 640px) 100vw, 2000px\" /></a></span></div></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-152\"><p>After you’ve made any changes, remember to save the image before returning it to the media library. Now, you can insert the new version of the file into your posts and pages. Any previous instances of the image on your website will remain as they were.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-112 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">WordPress Media Library Settings</h2></div><div class=\"fusion-text fusion-text-153\"><p>Whenever you upload a new image to your website, WordPress creates three more versions of that file: thumbnail, media, and large. Each of these three versions has different dimensions or physical size. You can change these three default sizes through the Media Settings screen if necessary.</p>\n</div><div class=\"fusion-image-element\" style=\"text-align:center;--awb-caption-title-font-family:var(--h2_typography-font-family);--awb-caption-title-font-weight:var(--h2_typography-font-weight);--awb-caption-title-font-style:var(--h2_typography-font-style);--awb-caption-title-size:var(--h2_typography-font-size);--awb-caption-title-transform:var(--h2_typography-text-transform);--awb-caption-title-line-height:var(--h2_typography-line-height);--awb-caption-title-letter-spacing:var(--h2_typography-letter-spacing);\"><span class=\" fusion-imageframe imageframe-none imageframe-26 hover-type-none\"><img decoding=\"async\" width=\"1700\" height=\"1500\" alt=\"WordPress Media Settings\" title=\"WordPress Media Settings\" src=\"https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-edit-media-settings.jpg\" class=\"img-responsive wp-image-894558\" srcset=\"https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-edit-media-settings-200x176.jpg 200w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-edit-media-settings-400x353.jpg 400w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-edit-media-settings-600x529.jpg 600w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-edit-media-settings-800x706.jpg 800w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-edit-media-settings-1200x1059.jpg 1200w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-edit-media-settings.jpg 1700w\" sizes=\"(max-width: 1024px) 100vw, (max-width: 640px) 100vw, 1700px\" /></span></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-154\"><p>In the media library settings, you can also configure how files are organized on your server as you upload them. Managing one or multiple <a href=\"https://1.envato.market/jKdLZ\" target=\"_blank\" rel=\"noopener noreferrer\">Avada</a> websites will mean that you will be managing hundreds, if not thousands, of media files such as images, videos, audios, documents, etc., and this is why WordPress media organization is vital. This is where <a href=\"https://ninjateam.org/wordpress-media-library-folders/\" target=\"_blank\" rel=\"noopener noreferrer\">FileBird</a> comes in.</p>\n</div><div class=\"fusion-alert alert custom alert-custom fusion-alert-left awb-alert-inherit-link-color\" style=\"--awb-background-color:#EBFAFF;--awb-accent-color:#2b4575;--awb-border-size:0px;--awb-border-top-left-radius:5px;--awb-border-top-right-radius:5px;--awb-border-bottom-left-radius:5px;--awb-border-bottom-right-radius:5px;\" role=\"alert\"><div class=\"fusion-alert-content-wrapper\"><span class=\"alert-icon\"><i class=\"fa-info-circle fal\" aria-hidden=\"true\"></i></span><span class=\"fusion-alert-content\">The <a href=\"https://avada.com/blog/filebird-a-best-selling-wordpress-media-management-plugin/\" target=\"_self\" rel=\"noopener noreferrer\">FileBird plugin</a> is included and 100% free with your purchase of Avada. Once you have purchased Avada for your website, you can download the plugin from your <a href=\"https://avada.com/documentation/how-to-use-my-avada/\" target=\"_self\" rel=\"noopener noreferrer\">My Avada</a> account.</span></div></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-113 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">Cleaning Up the Media Library</h2></div><div class=\"fusion-text fusion-text-155\"><p>As each image you add to your WordPress website is automatically added to the media library, the size of the library can quickly grow. While you won’t want to delete any images used in your posts, you may&nbsp;want to delete the ones in the library that haven’t been used on your site.</p>\n<p>WordPress makes it easy to filter the images or other media files that haven’t been inserted into (attached to) a page or post. You can view all the unattached files by selecting <strong>&#8220;Unattached&#8221;</strong> from the filter drop-down list.</p>\n</div><div class=\"fusion-image-element\" style=\"text-align:center;--awb-caption-title-font-family:var(--h2_typography-font-family);--awb-caption-title-font-weight:var(--h2_typography-font-weight);--awb-caption-title-font-style:var(--h2_typography-font-style);--awb-caption-title-size:var(--h2_typography-font-size);--awb-caption-title-transform:var(--h2_typography-text-transform);--awb-caption-title-line-height:var(--h2_typography-line-height);--awb-caption-title-letter-spacing:var(--h2_typography-letter-spacing);\"><span class=\" fusion-imageframe imageframe-none imageframe-27 hover-type-none\" style=\"border:1px solid var(--awb-color2);\"><img decoding=\"async\" width=\"2000\" height=\"911\" alt=\"Unattached Media Library Images\" title=\"Unattached Media Library Images\" src=\"https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-unnattached.jpg\" class=\"img-responsive wp-image-894559\" srcset=\"https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-unnattached-200x91.jpg 200w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-unnattached-400x182.jpg 400w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-unnattached-600x273.jpg 600w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-unnattached-800x364.jpg 800w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-unnattached-1200x547.jpg 1200w, https://avada.com/wp-content/uploads/2024/06/wordpress-media-library-post-unnattached.jpg 2000w\" sizes=\"(max-width: 1024px) 100vw, (max-width: 640px) 100vw, 2000px\" /></span></div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:20px;width:100%;\"></div><div class=\"fusion-text fusion-text-156\"><p>These are the files that were either uploaded directly to the media library rather than inserted into a post first, or added to a post but later deleted. If you are sure you no longer need these files, you can delete them in one fell swoop by clicking the <strong>&#8220;Delete Selected&#8221;</strong> button.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:30px;width:100%;\"></div><div class=\"fusion-title title fusion-title-114 fusion-sep-none fusion-title-text fusion-title-size-two\" style=\"--awb-margin-top-small:0px;--awb-margin-bottom-small:0.5em;\"><h2 class=\"fusion-title-heading title-heading-left fusion-responsive-typography-calculated\" style=\"margin:0;text-transform:capitalize;--fontSize:32;line-height:1.25;\">Summary</h2></div><div class=\"fusion-text fusion-text-157\"><p>Hopefully, you now understand how WordPress stores and manages the images and other media files you&#8217;ve added to your website. WordPress image galleries can also be a handy way to work with images more effectively on your website. </p>\n<p>Using image thumbnails, which automatically link to larger versions of your photographs and other images, can help your pages load faster and let your visitors see more of your media content on a single page.</p>\n</div><div class=\"fusion-separator fusion-full-width-sep\" style=\"align-self: center;margin-left: auto;margin-right: auto;margin-bottom:10px;width:100%;\"></div><div class=\"fusion-alert alert custom alert-custom fusion-alert-left awb-alert-inherit-link-color\" style=\"--awb-background-color:#ebfaff;--awb-accent-color:#005272;--awb-border-size:0px;--awb-border-top-left-radius:5px;--awb-border-top-right-radius:5px;--awb-border-bottom-left-radius:5px;--awb-border-bottom-right-radius:5px;\" role=\"alert\"><div class=\"fusion-alert-content-wrapper\"><span class=\"alert-icon\"><i class=\"avada-elements-avada-logo\" aria-hidden=\"true\"></i></span><span class=\"fusion-alert-content\"><a href=\"https://avada.com/\" target=\"_blank\" rel=\"noopener noreferrer\">Avada</a> is not only a WordPress theme; it is more than that. It is an intuitive <a href=\"https://avada.com/feature/live-visual-builder/\" target=\"_blank\" rel=\"noopener noreferrer\">Website Builder</a> for WordPress and <a href=\"https://avada.com/feature/woocommerce/\" target=\"_blank\" rel=\"noopener noreferrer\">eCommerce</a>. Avada&#8217;s design and styling flexibility will empower anyone, from beginners to freelancers, to launch professional websites fast.</span></div></div></div></div></div></div>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:66:\"https://avada.com/blog/the-wordpress-media-library-explained/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}}s:27:\"http://www.w3.org/2005/Atom\";a:1:{s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:0:\"\";s:7:\"attribs\";a:1:{s:0:\"\";a:3:{s:4:\"href\";s:23:\"https://avada.com/feed/\";s:3:\"rel\";s:4:\"self\";s:4:\"type\";s:19:\"application/rss+xml\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:44:\"http://purl.org/rss/1.0/modules/syndication/\";a:2:{s:12:\"updatePeriod\";a:1:{i:0;a:5:{s:4:\"data\";s:9:\"\n	hourly	\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:15:\"updateFrequency\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"\n	1	\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}}}}}}}s:4:\"type\";i:128;s:7:\"headers\";a:17:{s:4:\"date\";s:29:\"Sat, 04 Jul 2026 12:00:58 GMT\";s:12:\"content-type\";s:34:\"application/rss+xml; charset=UTF-8\";s:6:\"server\";s:10:\"cloudflare\";s:4:\"vary\";s:15:\"Accept-Encoding\";s:4:\"etag\";s:34:\"\"e1d404401bef635208d7f0b2d3a3ba27\"\";s:13:\"last-modified\";s:29:\"Fri, 03 Jul 2026 14:19:47 GMT\";s:4:\"link\";s:54:\"<https://avada.com/wp-json/>; rel=\"https://api.w.org/\"\";s:12:\"x-powered-by\";s:9:\"WP Engine\";s:11:\"x-cacheable\";s:17:\"CacheAlways: feed\";s:13:\"cache-control\";s:28:\"max-age=600, must-revalidate\";s:7:\"x-cache\";s:4:\"MISS\";s:3:\"age\";s:3:\"175\";s:16:\"content-encoding\";s:4:\"gzip\";s:10:\"set-cookie\";s:304:\"__cf_bm=1d6dt7spnthvDn.Oc7OAKMUYka9PvBppqnRmMBzJk.s-1783166458.503832-1.0.1.1-dzbd2dwbM0GkletvkKlEJ18sWSW42dxi_DX3XyLupJe5Keqpa5AgGxWh3kF2OnNWaZwKuqM3ONPSIR2_AWjzXVU6dHtyrBXo58JZf8Rta4fG0pJw1BnoZGNfyBNJpSl1; HttpOnly; SameSite=None; Secure; Path=/; Domain=avada.com; Expires=Sat, 04 Jul 2026 12:30:58 GMT\";s:15:\"cf-cache-status\";s:3:\"HIT\";s:6:\"cf-ray\";s:20:\"a15df8fdabbefe