=\"no-repeat\" background_position=\"left top\" hover_type=\"none\" border_position=\"all\" animation_speed=\"0.1\" border_sizes_top=\"0px\" border_sizes_bottom=\"0px\" border_sizes_left=\"0px\" border_sizes_right=\"0px\" first=\"true\" min_height=\"\" link=\"\"][fusion_content_boxes layout=\"icon-on-top\" columns=\"4\" icon_align=\"left\" animation_direction=\"left\" animation_speed=\"0.1\" hide_on_mobile=\"small-visibility,medium-visibility,large-visibility\" heading_size=\"2\" iconspin=\"no\" icon_hover_type=\"pulsate\"][fusion_content_box title=\"Analytisch &amp; Transparant\" icon=\"fusion-prefix-constructionhome-solid\" iconspin=\"no\" circlecolor=\"hsla(calc(var(--awb-color5-h) + 140),calc(var(--awb-color5-s) - 30%),calc(var(--awb-color5-l) - 20%),var(--awb-color5-a))\" image_max_width=\"35\" link_target=\"_self\" animation_direction=\"left\" animation_speed=\"0.3\"][fusion_separator style_type=\"single solid\" top_margin=\"0\" bottom_margin=\"20\" sep_color=\"hsla(var(--awb-color8-h),var(--awb-color8-s),calc( var(--awb-color8-l) + 36% ),var(--awb-color8-a))\" border_size=\"2px\" icon=\"\" icon_circle=\"\" icon_circle_color=\"\" width=\"20px\" alignment=\"center\" class=\"\" id=\"\"/]Wij werken met meetbare data, geen verkooppraatjes. U weet vooraf precies wat u krijgt en wat het oplevert.<p></p>[/fusion_content_box][fusion_content_box title=\"Hoogste Kwaliteitsnormen\" icon=\"fusion-prefix-constructionsun-regular\" iconspin=\"no\" circlecolor=\"hsla(calc(var(--awb-color5-h) + 175),calc(var(--awb-color5-s) - 40%),calc(var(--awb-color5-l) - 5%),var(--awb-color5-a))\" image_max_width=\"35\" link_target=\"_self\" animation_direction=\"left\" animation_speed=\"0.3\"][fusion_separator style_type=\"single solid\" top_margin=\"0\" bottom_margin=\"20\" sep_color=\"hsla(var(--awb-color8-h),var(--awb-color8-s),calc( var(--awb-color8-l) + 36% ),var(--awb-color8-a))\" border_size=\"2px\" icon=\"\" icon_circle=\"\" icon_circle_color=\"\" width=\"20px\" alignment=\"center\" class=\"\" id=\"\"/]Erkende materialen en vakkundige uitvoering, elke keer opnieuw.<p></p>[/fusion_content_box][fusion_content_box title=\"Vakkundig Team\" icon=\"fusion-prefix-constructionusers-solid\" iconspin=\"no\" circlecolor=\"hsla(calc(var(--awb-color5-h) - 25),var(--awb-color5-s),var(--awb-color5-l),var(--awb-color5-a))\" image_max_width=\"35\" link_target=\"_self\" animation_direction=\"left\" animation_speed=\"0.3\"][fusion_separator style_type=\"single solid\" top_margin=\"0\" bottom_margin=\"20\" sep_color=\"hsla(var(--awb-color8-h),var(--awb-color8-s),calc( var(--awb-color8-l) + 36% ),var(--awb-color8-a))\" border_size=\"2px\" icon=\"\" icon_circle=\"\" icon_circle_color=\"\" width=\"20px\" alignment=\"center\" class=\"\" id=\"\"/]Onze monteurs zijn gecertificeerd en werken volgens een vast, herhaalbaar proces.<p></p>[/fusion_content_box][fusion_content_box title=\"Slimme Subsidie-Oplossingen\" icon=\"fusion-prefix-constructionlightbulb-regular\" iconspin=\"no\" image_max_width=\"35\" link_target=\"_self\" animation_direction=\"left\" animation_speed=\"0.3\" circlecolor=\"hsla(calc(var(--awb-color5-h) + 35),var(--awb-color5-s),calc(var(--awb-color5-l) - 22%),var(--awb-color5-a))\"][fusion_separator style_type=\"single solid\" top_margin=\"0\" bottom_margin=\"20\" sep_color=\"hsla(var(--awb-color8-h),var(--awb-color8-s),calc( var(--awb-color8-l) + 36% ),var(--awb-color8-a))\" border_size=\"2px\" icon=\"\" icon_circle=\"\" icon_circle_color=\"\" width=\"20px\" alignment=\"center\" class=\"\" id=\"\"/]Wij kennen de ISDE-regels van binnen en buiten en halen er voor u uit wat erin zit.<p></p>[/fusion_content_box][/fusion_content_boxes][/fusion_builder_column][/fusion_builder_row][/fusion_builder_container][fusion_builder_container hundred_percent=\"no\" equal_height_columns=\"no\" hide_on_mobile=\"no\" background_image=\"http://warmvast.local/wp-content/uploads/2015/12/home-parallax-144609983.jpg\" background_position=\"center center\" background_repeat=\"